def wait_frame_change(timeout_sec: float = 15.0, poll_ms: int = 400) -> dict[str, Any]:
    first = capture_desktop("wait_before")
    h0 = first["frame_hash"]
    t0 = time.time()
    while time.time() - t0 < timeout_sec:
        time.sleep(max(0.1, poll_ms / 1000.0))
        cur = capture_desktop("wait_poll")
        if cur["frame_hash"] != h0:
            return {"ok": True, "changed": True, "before": first["path"], "after": cur["path"], "elapsed_sec": round(time.time() - t0, 2)}
    after = capture_desktop("wait_timeout")
    return {"ok": False, "changed": False, "before": first["path"], "after": after["path"], "elapsed_sec": round(time.time() - t0, 2), "reason": "timeout_no_frame_change"}

