"""In-process specialist roles — company topology inside ManualQA-Agent."""
from __future__ import annotations

import json
from datetime import datetime, timezone
from pathlib import Path
from typing import Any

from paths import WORKSPACE

ROLES: dict[str, dict[str, Any]] = {
    "orchestrator": {
        "title": "Agents Orchestrator",
        "owns": "phase gates, handoffs, no-skip ISTQB order",
        "produces": "flow-state + next action",
        "not_responsible": "guessing UI; inventing OTP",
    },
    "intake": {
        "title": "Jira / Story Intake",
        "owns": "assigned tasks, stories, existing Xray clone (read-only), credentials request",
        "produces": "assignedTasks/, UserStories/, ExistingTestCases/",
        "not_responsible": "Pass/Fail verdicts",
    },
    "mapper": {
        "title": "Experience Mapper (SBTM)",
        "owns": "headed map with no Pass/Fail",
        "produces": "map/ nodes + living plan",
        "not_responsible": "Book1 share; REAL_BUG labels",
    },
    "designer": {
        "title": "Test Designer",
        "owns": "EP/BVA/decision tables/state transition; NEW cases; Jira tone harvest",
        "produces": "NewTestCases/ + knowledgeBase harvest",
        "not_responsible": "editing existing Xray",
    },
    "executor": {
        "title": "Headed Executor",
        "owns": "Eyes-Brain-Hands execution of cases",
        "produces": "proof PNGs + attempt logs",
        "not_responsible": "final REAL_BUG without honesty referee",
    },
    "honesty_referee": {
        "title": "Honesty Referee",
        "owns": "20-approach / 3-repro obvious gate; 3-cycle close",
        "produces": "verdicts PASS|REAL_BUG|BLOCKED|N/A",
        "not_responsible": "writing Book1 prose",
    },
    "book1_reporter": {
        "title": "Book1 Reporter",
        "owns": "SHARE-parity Excel + bug drafts with crop proof",
        "produces": "outputs/<STORY>/*-Book1.xlsx + bugs/",
        "not_responsible": "headed navigation",
    },
    "learner": {
        "title": "Retrospective Learner",
        "owns": "post-task skill updates",
        "produces": "knowledgeBase/skills learn notes",
        "not_responsible": "live execution",
    },
}


def _now() -> str:
    return datetime.now(timezone.utc).isoformat()


def roles_dir() -> Path:
    p = WORKSPACE / "agents" / "roles"
    p.mkdir(parents=True, exist_ok=True)
    return p


def list_roles() -> dict[str, Any]:
    return {"ok": True, "roles": ROLES}


def dispatch(role: str, instruction: str) -> dict[str, Any]:
    key = (role or "").strip().lower()
    if key not in ROLES:
        return {"ok": False, "error": f"unknown role {role!r}", "known": list(ROLES)}
    meta = ROLES[key]
    path = roles_dir() / f"{key}.json"
    prev = {}
    if path.exists():
        try:
            prev = json.loads(path.read_text(encoding="utf-8"))
        except Exception:
            prev = {}
    log = list(prev.get("log") or [])
    entry = {"at": _now(), "instruction": instruction}
    log.append(entry)
    payload = {
        "role": key,
        "title": meta["title"],
        "owns": meta["owns"],
        "produces": meta["produces"],
        "not_responsible": meta["not_responsible"],
        "latest_instruction": instruction,
        "log": log[-50:],
        "status": "dispatched",
    }
    path.write_text(json.dumps(payload, indent=2), encoding="utf-8")
    return {
        "ok": True,
        "contract": payload,
        "agent_order": (
            f"Act as {meta['title']}. Own: {meta['owns']}. "
            f"Produce: {meta['produces']}. Do NOT: {meta['not_responsible']}. "
            f"Instruction: {instruction}"
        ),
    }


def role_status(role: str = "") -> dict[str, Any]:
    if role:
        path = roles_dir() / f"{role.strip().lower()}.json"
        if not path.exists():
            return {"ok": False, "error": "no dispatch yet", "role": role}
        return {"ok": True, "state": json.loads(path.read_text(encoding="utf-8"))}
    out = {}
    for p in roles_dir().glob("*.json"):
        out[p.stem] = json.loads(p.read_text(encoding="utf-8"))
    return {"ok": True, "roles": out}

