@mcp.tool()
def mqa_hotkey(*keys: str) -> dict[str, Any]:
    """Send hotkey chord, e.g. ctrl, c — pass keys as separate args if client supports; else use mqa_hotkey_chord."""
    try:
        import pyautogui

        pyautogui.FAILSAFE = True
        seq = [k for k in keys if k]
        if not seq:
            return {"ok": False, "error": "no keys"}
        pyautogui.hotkey(*seq)
        return {"ok": True, "keys": seq}
    except Exception as e:  # noqa: BLE001
        return {"ok": False, "error": str(e)}


@mcp.tool()
def mqa_hotkey_chord(keys: str) -> dict[str, Any]:
    """Hotkey from comma-separated string, e.g. 'ctrl,v' or 'alt,tab'."""
    parts = [p.strip() for p in (keys or "").split(",") if p.strip()]
    return mqa_hotkey(*parts)


