def mqa_press(key: str) -> dict[str, Any]:
    """Press a single key (enter, tab, esc, ...)."""
    try:
        import pyautogui

        pyautogui.FAILSAFE = True
        pyautogui.press(key)
        return {"ok": True, "key": key}
    except Exception as e:  # noqa: BLE001
        return {"ok": False, "error": str(e)}


@mcp.tool()
def mqa_file_bug_draft(
    key: str,
    title: str,
    body: str,
    proof_paths: str = "",
) -> dict[str, Any]:
    """Write a bug draft under bugs/<KEY>/. Agent uploads to Jira via Atlassian MCP with PNG attach."""
    safe = "".join(c for c in key if c.isalnum() or c in "-_") or "BUG"
    dest = WORKSPACE / "bugs" / safe
    dest.mkdir(parents=True, exist_ok=True)
    proofs = [p.strip() for p in (proof_paths or "").replace(";", ",").split(",") if p.strip()]
    md = f"# {title}\n\nKey: {safe}\n\n{body}\n\n## Proof\n\n"
    for p in proofs:
        md += f"- `{p}`\n"
    path = dest / "bug-draft.md"
    path.write_text(md, encoding="utf-8")
    meta = {"key": safe, "title": title, "proofs": proofs, "path": str(path)}
    (dest / "meta.json").write_text(json.dumps(meta, indent=2), encoding="utf-8")
    return {
        "ok": True,
        **meta,
        "next": "Upload via Atlassian MCP createJiraIssue + attach PNG proofs. Match harvested Jira tone.",
    }


