"""Restart Edge with remote debugging, restore session, CDP-fill Account Inquiry + RR + capture proofs."""
from __future__ import annotations

import json
import subprocess
import time
from pathlib import Path

from playwright.sync_api import sync_playwright

OUT = Path(r"E:/ManualQA-Agent/workspace/default-run/reports/live-manual/PF-59194")
PROOF = OUT / "proof-cdp-edge"
PROOF.mkdir(parents=True, exist_ok=True)
R: dict = {"ok": [], "fail": [], "proofs": [], "notes": []}
PORT = 9333
BASE = "https://uat.fusionx.biz/web/lending/cNwNb"
AI = f"{BASE}/account-management/inquiry?mode=account"
RR = f"{BASE}/transaction-management/receipt-reallocation"
RR_CREATE = f"{BASE}/transaction-management/receipt-reallocation/create"
EDGE = r"C:\Program Files (x86)\Microsoft\Edge\Application\msedge.exe"
if not Path(EDGE).exists():
    EDGE = r"C:\Program Files\Microsoft\Edge\Application\msedge.exe"


def shot(page, name: str) -> str:
    p = PROOF / f"{time.strftime('%H%M%S')}_{name}.png"
    page.screenshot(path=str(p), full_page=False)
    R["proofs"].append(str(p))
    print("SHOT", name, flush=True)
    return str(p)


def restart_edge_debug():
    # Soft: try connect first; if fail, relaunch with debugging + restore
    subprocess.run(["taskkill", "/IM", "msedge.exe", "/F"], capture_output=True)
    time.sleep(2)
    # Use a dedicated debug profile cloned isn't needed — restore-last-session on default may lock.
    # Safer: launch with remote debugging and user will need SSO once OR use temp profile + login.
    user_data = Path(r"C:\Users\ThejanaD\AppData\Local\Temp\edge-mqa-cdp-profile")
    user_data.mkdir(parents=True, exist_ok=True)
    subprocess.Popen(
        [
            EDGE,
            f"--remote-debugging-port={PORT}",
            f"--user-data-dir={user_data}",
            "--start-maximized",
            "https://fusionx-uat.aunex0.com/Account/Login",
        ],
        stdout=subprocess.DEVNULL,
        stderr=subprocess.DEVNULL,
    )
    time.sleep(5)


def login(page, email: str, password: str) -> bool:
    page.goto("https://fusionx-uat.aunex0.com/Account/Login", wait_until="domcontentloaded", timeout=120_000)
    for _ in range(60):
        try:
            if page.get_by_placeholder("Username").count():
                break
        except Exception:
            pass
        page.wait_for_timeout(1000)
    shot(page, "login-wait")
    if page.get_by_placeholder("Username").count() == 0:
        R["fail"].append("login_form_timeout")
        return False
    page.get_by_placeholder("Username").fill(email)
    page.get_by_placeholder("Password").fill(password)
    page.get_by_role("button", name="SIGN IN").click()
    page.wait_for_timeout(12000)
    shot(page, "after-login")
    page.goto(f"{BASE}/dashboard", wait_until="domcontentloaded", timeout=120_000)
    page.wait_for_timeout(8000)
    shot(page, "dashboard")
    if "login" in page.url.lower():
        R["fail"].append("login_failed")
        return False
    R["ok"].append("login")
    return True


def do_ai(page) -> bool:
    page.goto(AI, wait_until="domcontentloaded", timeout=120_000)
    page.wait_for_timeout(6000)
    shot(page, "ai-land")
    page.get_by_text("Search by Account").first.click(timeout=10000)
    page.wait_for_timeout(1500)
    # fill all visible text inputs that look like search
    page.evaluate(
        """() => {
          const want='0042250036';
          const inputs=[...document.querySelectorAll('input')].filter(i=>i.offsetParent && !['hidden','checkbox','radio','password'].includes(i.type||''));
          for (const t of inputs) {
            const ph=(t.placeholder||'').toLowerCase();
            if (ph.includes('search') || ph==='' || ph.includes('account')) {
              const d=Object.getOwnPropertyDescriptor(HTMLInputElement.prototype,'value');
              d.set.call(t, want);
              t.dispatchEvent(new Event('input',{bubbles:true}));
              t.dispatchEvent(new Event('change',{bubbles:true}));
              t.dispatchEvent(new KeyboardEvent('keydown',{key:'Enter',bubbles:true}));
            }
          }
          return inputs.map(i=>({ph:i.placeholder,v:i.value,type:i.type}));
        }"""
    )
    page.keyboard.press("Enter")
    page.wait_for_timeout(2000)
    try:
        page.locator(".anticon-search").first.click(timeout=2000)
    except Exception:
        pass
    page.wait_for_timeout(5000)
    shot(page, "ai-results")
    body = page.locator("body").inner_text()
    print("AI body has acct?", "0042250036" in body, flush=True)
    if "0042250036" not in body:
        # try fill via locator
        page.get_by_placeholder("Search").first.fill("0042250036")
        page.keyboard.press("Enter")
        page.wait_for_timeout(5000)
        shot(page, "ai-results2")
        body = page.locator("body").inner_text()
    if "0042250036" not in body:
        R["fail"].append("ai_search_no_row")
        return False
    page.get_by_text("Select", exact=True).first.click(timeout=8000)
    page.wait_for_timeout(5000)
    shot(page, "ai-open")
    page.get_by_text("Receipt Details", exact=False).first.click(timeout=10000)
    page.wait_for_timeout(4000)
    shot(page, "ai-receipt-details")
    R["ok"].append("ai_receipt_details")
    return True


def do_rr(page) -> None:
    page.goto(RR_CREATE, wait_until="domcontentloaded", timeout=120_000)
    page.wait_for_timeout(6000)
    shot(page, "rr-create")
    try:
        page.get_by_text("Internal", exact=True).first.click(timeout=5000)
    except Exception:
        pass
    page.wait_for_timeout(2000)
    shot(page, "rr-internal")
    page.evaluate(
        """() => {
          const want='LNLOAN00110000348ILON2607';
          const inputs=[...document.querySelectorAll('input')].filter(i=>i.offsetParent && i.type!=='radio' && i.type!=='checkbox');
          for (const t of inputs) {
            const d=Object.getOwnPropertyDescriptor(HTMLInputElement.prototype,'value');
            d.set.call(t, want);
            t.dispatchEvent(new Event('input',{bubbles:true}));
            t.dispatchEvent(new Event('change',{bubbles:true}));
          }
        }"""
    )
    page.keyboard.press("Enter")
    page.wait_for_timeout(5000)
    shot(page, "rr-loan")
    try:
        page.locator("table").get_by_text("Select").first.click(timeout=8000)
        R["ok"].append("rr_select")
    except Exception as e:
        R["fail"].append(f"rr_select:{e}")
    page.wait_for_timeout(4000)
    shot(page, "rr-after-select")
    try:
        save = page.get_by_role("button", name="Save")
        if save.count():
            R["notes"].append(f"Save enabled={save.first.is_enabled()}")
            shot(page, "rr-save")
            R["ok"].append("rr_save_probed")
    except Exception:
        pass
    page.goto(RR, wait_until="domcontentloaded", timeout=120_000)
    page.wait_for_timeout(4000)
    try:
        page.get_by_text("Pending", exact=False).first.click(timeout=5000)
        page.wait_for_timeout(2000)
        page.get_by_text("Select", exact=True).first.click(timeout=5000)
        page.wait_for_timeout(4000)
        shot(page, "rr-pending")
        body = page.locator("body").inner_text()
        if "Approve" in body:
            R["ok"].append("rr_pending_approve")
    except Exception as e:
        R["fail"].append(f"pending:{e}")


def main():
    maker = json.loads(Path(r"E:/ManualQA-Agent/secrets/tmp-creds.json").read_text(encoding="utf-8-sig"))
    checker = json.loads(Path(r"E:/ManualQA-Agent/secrets/tmp-checker-creds.json").read_text(encoding="utf-8-sig"))

    restart_edge_debug()
    with sync_playwright() as p:
        browser = None
        for i in range(20):
            try:
                browser = p.chromium.connect_over_cdp(f"http://127.0.0.1:{PORT}")
                break
            except Exception as e:
                print("wait cdp", i, e, flush=True)
                time.sleep(1)
        if not browser:
            raise RuntimeError("CDP connect failed")
        ctx = browser.contexts[0] if browser.contexts else browser.new_context()
        page = ctx.pages[0] if ctx.pages else ctx.new_page()
        try:
            if not login(page, maker["email"], maker["password"]):
                raise SystemExit(2)
            do_ai(page)
            do_rr(page)
            # checker
            ctx.clear_cookies()
            if login(page, checker["email"], checker["password"]):
                page.goto(RR, wait_until="domcontentloaded", timeout=120_000)
                page.wait_for_timeout(5000)
                try:
                    page.get_by_text("Pending", exact=False).first.click(timeout=8000)
                    page.wait_for_timeout(2000)
                    page.get_by_text("Select", exact=True).first.click(timeout=8000)
                    page.wait_for_timeout(4000)
                    shot(page, "checker-pending")
                    body = page.locator("body").inner_text()
                    for n in ("Approve", "Reject", "Return"):
                        if n in body:
                            R["ok"].append(f"checker_{n}")
                except Exception as e:
                    R["fail"].append(f"checker:{e}")
        finally:
            (OUT / "CDP-EDGE-RESULT.json").write_text(json.dumps(R, indent=2), encoding="utf-8")
            print("RESULT", json.dumps({"ok": R["ok"], "fail": R["fail"], "notes": R["notes"]}, indent=2), flush=True)


if __name__ == "__main__":
    main()

