"""Restart Default Edge with CDP, login maker, drive Account Inquiry + RR Internal.

Never prints passwords. Uses secrets/tmp-creds.json.
"""
from __future__ import annotations

import json
import subprocess
import time
from pathlib import Path

from playwright.sync_api import sync_playwright

OUT = Path(r"E:/ManualQA-Agent/workspace/default-run/reports/live-manual/PF-59194")
PROOF = OUT / "proof-cdp-default"
PROOF.mkdir(parents=True, exist_ok=True)
EDGE = r"C:\Program Files (x86)\Microsoft\Edge\Application\msedge.exe"
if not Path(EDGE).exists():
    EDGE = r"C:\Program Files\Microsoft\Edge\Application\msedge.exe"
USER_DATA = Path.home() / "AppData/Local/Microsoft/Edge/User Data"
PORT = 9334
LOGIN = "https://fusionx-uat.aunex0.com/Account/Login"
AI = "https://uat.fusionx.biz/web/lending/cNwNb/account-management/inquiry?mode=account"
RR_CREATE = (
    "https://uat.fusionx.biz/web/lending/cNwNb/transaction-management/"
    "receipt-reallocation/create"
)
ACCOUNT = "0042250036"
LOAN = "LNLOAN00110000348ILON2607"


def shot(page, name: str) -> Path:
    p = PROOF / f"{name}.png"
    page.screenshot(path=str(p), full_page=False)
    print(f"SHOT {p}", flush=True)
    return p


def kill_edge():
    subprocess.run(
        ["taskkill", "/F", "/IM", "msedge.exe"],
        capture_output=True,
        text=True,
    )
    time.sleep(2.5)


def start_edge():
    # Separate debugging profile clone to avoid locking Default while preserving cookies copy is hard;
    # use Default with remote debugging after kill.
    cmd = [
        EDGE,
        f"--remote-debugging-port={PORT}",
        f"--user-data-dir={USER_DATA}",
        "--profile-directory=Default",
        "--no-first-run",
        "--no-default-browser-check",
        LOGIN,
    ]
    subprocess.Popen(cmd, stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)
    time.sleep(5)


def wait_login_form(page, timeout_s: float = 90) -> bool:
    end = time.time() + timeout_s
    while time.time() < end:
        try:
            # common AuNEXO patterns
            for sel in (
                'input[name="Username"]',
                'input[name="username"]',
                'input#Username',
                'input[type="email"]',
                'input[placeholder*="sername" i]',
                'input[type="text"]',
            ):
                loc = page.locator(sel)
                if loc.count() and loc.first.is_visible():
                    print(f"FORM {sel}", flush=True)
                    return True
        except Exception as e:
            print(f"wait: {e}", flush=True)
        time.sleep(1.5)
        shot(page, f"wait-{int(time.time()) % 100000}")
    return False


def main():
    maker = json.loads(
        Path(r"E:/ManualQA-Agent/secrets/tmp-creds.json").read_text(encoding="utf-8-sig")
    )
    email = maker.get("email") or maker.get("username") or maker.get("user")
    password = maker["password"]
    assert email and password

    kill_edge()
    start_edge()

    result = {"ok": False, "steps": []}
    with sync_playwright() as p:
        browser = p.chromium.connect_over_cdp(f"http://127.0.0.1:{PORT}")
        ctx = browser.contexts[0] if browser.contexts else browser.new_context()
        page = ctx.pages[0] if ctx.pages else ctx.new_page()
        page.goto(LOGIN, wait_until="domcontentloaded", timeout=60000)
        shot(page, "01-login-nav")
        result["steps"].append({"url": page.url, "title": page.title()})

        # hard reload in case splash stuck
        page.reload(wait_until="domcontentloaded")
        time.sleep(3)
        shot(page, "02-after-reload")

        if not wait_login_form(page, 75):
            # try clicking Azure AD / Sign in with Microsoft if present
            for text in ("Azure", "Microsoft", "Sign in", "SIGN IN", "Continue"):
                try:
                    page.get_by_text(text, exact=False).first.click(timeout=2000)
                    time.sleep(3)
                    shot(page, f"03-click-{text[:8]}")
                except Exception:
                    pass
            if not wait_login_form(page, 40):
                result["error"] = "no_login_form"
                result["url"] = page.url
                result["html_inputs"] = page.eval_on_selector_all(
                    "input", "els => els.map(e => ({t:e.type,n:e.name,id:e.id,ph:e.placeholder}))"
                )
                (OUT / "CDP-DEFAULT-RESULT.json").write_text(
                    json.dumps(result, indent=2), encoding="utf-8"
                )
                print(json.dumps(result, indent=2), flush=True)
                return

        # fill username/password via DOM (works where OS type fails)
        user_sel = None
        for sel in (
            'input[name="Username"]',
            'input#Username',
            'input[name="username"]',
            'input[type="email"]',
            'input[type="text"]',
        ):
            if page.locator(sel).count():
                user_sel = sel
                break
        pwd = page.locator('input[type="password"]').first
        page.locator(user_sel).first.fill(email)
        pwd.fill(password)
        shot(page, "04-filled")
        # submit
        submitted = False
        for sel in ('button[type="submit"]', 'input[type="submit"]', "button:has-text('SIGN')"):
            try:
                page.locator(sel).first.click(timeout=2500)
                submitted = True
                break
            except Exception:
                continue
        if not submitted:
            page.keyboard.press("Enter")
        time.sleep(12)
        shot(page, "05-after-login")
        result["steps"].append({"after_login_url": page.url, "title": page.title()})

        # Account Inquiry
        page.goto(AI, wait_until="domcontentloaded", timeout=60000)
        time.sleep(5)
        shot(page, "06-ai")
        # fill search via React-friendly events
        filled = page.evaluate(
            """(acct) => {
              const inputs = [...document.querySelectorAll('input')];
              const target = inputs.find(i =>
                /account|search|customer/i.test(i.placeholder||'') ||
                /account|search/i.test(i.name||'') ||
