RR_CREATE = (
    "https://uat.fusionx.biz/web/lending/cNwNb/transaction-management/"
    "receipt-reallocation/create"
)
ACCOUNT = "0042250036"
LOAN = "LNLOAN00110000348ILON2607"
nshot = 0


def shot(page, name: str):
    global nshot
    if nshot >= 12:
        return
    nshot += 1
    p = PROOF / f"{name}.png"
    try:
        page.screenshot(path=str(p), full_page=False)
        print(f"SHOT {p}", flush=True)
    except Exception as e:
        print(f"SHOT_FAIL {e}", flush=True)


def frames_info(page):
    info = []
    for f in page.frames:
        try:
            info.append(
                {
                    "url": f.url,
                    "name": f.name,
                    "inputs": f.evaluate(
                        "() => document.querySelectorAll('input').length"
                    ),
                }
            )
        except Exception as e:
            info.append({"url": getattr(f, "url", ""), "err": str(e)[:80]})
    return info


def find_login_frame(page):
    for f in page.frames:
        try:
            n = f.locator('input[type="password"]').count()
            if n:
                return f
            n2 = f.locator('input[name="Username"], input#Username').count()
            if n2:
                return f
        except Exception:
            continue
    return page.main_frame


def main():
    maker = json.loads(
        Path(r"E:/ManualQA-Agent/secrets/tmp-creds.json").read_text(encoding="utf-8-sig")
    )
    email = maker.get("email") or maker.get("username") or maker.get("user")
    password = maker["password"]
    result = {"ok": False}

    with sync_playwright() as p:
        browser = p.chromium.connect_over_cdp(f"http://127.0.0.1:{PORT}")
        ctx = browser.contexts[0]
        page = ctx.pages[0] if ctx.pages else ctx.new_page()
        page.goto(LOGIN, wait_until="domcontentloaded", timeout=90000)
        time.sleep(4)
        shot(page, "01-login")
        result["frames0"] = frames_info(page)

        form_frame = None
        for i in range(30):
            fi = frames_info(page)
            print(f"poll {i} frames={fi}", flush=True)
            form_frame = find_login_frame(page)
            try:
                if form_frame.locator('input[type="password"]').count() or form_frame.locator(
                    'input[type="text"], input[type="email"]'
                ).count():
                    # require at least one visible-ish input
                    if form_frame.locator("input").count() > 0:
                        print(f"FORM on {form_frame.url}", flush=True)
                        break
            except Exception:
                pass
            form_frame = None
            if i in (4, 10, 18):
                page.reload(wait_until="domcontentloaded")
                time.sleep(3)
            time.sleep(2)

        if form_frame is None:
            result["error"] = "no_form"
            result["frames"] = frames_info(page)
            try:
                result["body"] = page.inner_text("body")[:800]
                result["html_len"] = len(page.content())
            except Exception as e:
                result["body_err"] = str(e)
            shot(page, "99-no-form")
            (OUT / "CDP-LIVE-RESULT.json").write_text(json.dumps(result, indent=2), encoding="utf-8")
            print(json.dumps(result, indent=2)[:2500], flush=True)
            return

        fr = form_frame
        # fill
        u = fr.locator(
            'input[name="Username"], input#Username, input[type="email"], input[type="text"]'
        ).first
        u.click()
        u.fill(email)
        pw = fr.locator('input[type="password"]').first
        pw.click()
        pw.fill(password)
        shot(page, "02-filled")
        try:
            fr.locator('button[type="submit"], input[type="submit"], button:has-text("SIGN")').first.click(
                timeout=4000
            )
        except Exception:
            fr.locator("input").last.press("Enter")
        time.sleep(18)
        shot(page, "03-after-login")
        result["after"] = {"url": page.url, "title": page.title(), "frames": frames_info(page)}

        # still login?
        if page.locator('input[type="password"]').count() and "Login" in page.url:
            result["error"] = "still_login"
            (OUT / "CDP-LIVE-RESULT.json").write_text(json.dumps(result, indent=2), encoding="utf-8")
            print(json.dumps(result, indent=2), flush=True)
            return

        page.goto(AI, wait_until="domcontentloaded", timeout=90000)
        time.sleep(6)
        shot(page, "04-ai")
        fill = page.evaluate(
            """(acct) => {
              const inputs = [...document.querySelectorAll('input')].filter(i => i.offsetParent);
              let t = inputs.find(i => /account|search|customer/i.test(
                (i.placeholder||'')+(i.name||'')+(i.id||'')+(i.getAttribute('aria-label')||'')
              )) || inputs.find(i => (i.type||'text')==='text' || i.type==='search');
              if (!t) return {ok:false, n:inputs.length};
              const set = Object.getOwnPropertyDescriptor(HTMLInputElement.prototype,'value').set;
              t.focus(); set.call(t, acct);
              ['input','change','keyup'].forEach(e => t.dispatchEvent(new Event(e,{bubbles:true})));
              return {ok:true, value:t.value, ph:t.placeholder};
            }""",
            ACCOUNT,
        )
        result["ai_fill"] = fill
        shot(page, "05-ai-fill")
        page.keyboard.press("Enter")
        time.sleep(2)
        for name in ("Search", "Select"):
            try:
                page.get_by_role("button", name=name).first.click(timeout=2000)
                time.sleep(2)
            except Exception:
                pass
        shot(page, "06-ai-result")
        for label in ("Receipt Details", "Select"):
            try:
                page.get_by_text(label, exact=False).first.click(timeout=2500)
                time.sleep(3)
                shot(page, f"07-{label[:8]}")
            except Exception:
                pass

        page.goto(RR_CREATE, wait_until="domcontentloaded", timeout=90000)
        time.sleep(5)
        shot(page, "08-rr")
        try:
            page.get_by_text("Internal", exact=False).first.click(timeout=3000)
            time.sleep(2)
        except Exception:
            pass
        page.evaluate(
            """(loan) => {
              const inputs = [...document.querySelectorAll('input')].filter(i => i.offsetParent);
              const t = inputs[0]; if (!t) return false;
              const set = Object.getOwnPropertyDescriptor(HTMLInputElement.prototype,'value').set;
              set.call(t, loan);
              t.dispatchEvent(new Event('input',{bubbles:true}));
              return true;
            }""",
            LOAN,
        )
        page.keyboard.press("Enter")
        time.sleep(2)
        try:
            page.get_by_text("Select", exact=False).first.click(timeout=2500)
        except Exception:
            pass
        time.sleep(3)
        shot(page, "09-rr-sel")
        try:
            save = page.get_by_role("button", name="Save")
            result["save_enabled"] = bool(save.count() and save.first.is_enabled())
        except Exception as e:
            result["save_err"] = str(e)
        shot(page, "10-save")
        result["ok"] = True
        result["final"] = page.url
        (OUT / "CDP-LIVE-RESULT.json").write_text(json.dumps(result, indent=2), encoding="utf-8")
        print(json.dumps(result, indent=2), flush=True)


if __name__ == "__main__":
