using System;
using System.Diagnostics;
using System.Runtime.InteropServices;
public class ForceFg {
  [DllImport("user32.dll")] static extern bool SetForegroundWindow(IntPtr hWnd);
  [DllImport("user32.dll")] static extern bool ShowWindow(IntPtr hWnd, int nCmdShow);
  [DllImport("user32.dll")] static extern IntPtr GetForegroundWindow();
  [DllImport("user32.dll")] static extern uint GetWindowThreadProcessId(IntPtr hWnd, out uint lpdwProcessId);
  [DllImport("kernel32.dll")] static extern uint GetCurrentThreadId();
  [DllImport("user32.dll")] static extern bool AttachThreadInput(uint idAttach, uint idAttachTo, bool fAttach);
  [DllImport("user32.dll")] static extern bool BringWindowToTop(IntPtr hWnd);
  public static string Go(IntPtr h) {
    ShowWindow(h, 9);
    IntPtr fg = GetForegroundWindow();
    uint fgPid; uint fgTid = GetWindowThreadProcessId(fg, out fgPid);
    uint cur = GetCurrentThreadId();
    uint tgtPid; uint tgtTid = GetWindowThreadProcessId(h, out tgtPid);
    AttachThreadInput(cur, fgTid, true);
    AttachThreadInput(cur, tgtTid, true);
    BringWindowToTop(h);
    SetForegroundWindow(h);
    AttachThreadInput(cur, fgTid, false);
    AttachThreadInput(cur, tgtTid, false);
    return "ok";
