"""Connect to Chrome CDP 9333 and execute PF-59422 search + inquiry path."""
from __future__ import annotations

import json
import time
from pathlib import Path

from playwright.sync_api import sync_playwright

PROOF = Path(r"E:\LIQA\workspace\default-run\reports\proof\PF-59422")
CDP = "http://127.0.0.1:9333"
MANAGE = "https://uat.fusionx.biz/web/td/cNwNb/accounts/manage-account"


def shot(page, name: str):
    p = PROOF / name
    page.screenshot(path=str(p), full_page=False)
    print("SHOT", name, page.url[:140])


def pick_page(context):
    # Prefer TD manage-account / fusionx tab
    for p in context.pages:
        u = p.url or ""
        if "uat.fusionx.biz" in u and "/td/" in u:
            return p
    for p in context.pages:
        if "uat.fusionx.biz" in (p.url or ""):
            return p
    return context.pages[0] if context.pages else context.new_page()


def select_gbaf(page):
    for text in ["General Banking & Finance", "GBAF Business"]:
        try:
            loc = page.get_by_text(text, exact=False).first
            if loc.is_visible(timeout=2000):
                loc.click(timeout=3000)
                print("GBAF click", text)
                page.wait_for_timeout(2000)
                return True
        except Exception as e:
            print("GBAF miss", text, type(e).__name__)
    return False


def fill_search(page, value: str) -> bool:
    # Ensure Customer Details tab
    try:
        page.get_by_text("Search By Customer Details", exact=False).first.click(timeout=3000)
        page.wait_for_timeout(500)
    except Exception:
        pass

    # Prefer placeholder Search
    selectors = [
        'input[placeholder*="Search" i]',
        'input[type="text"]',
        'input:not([type="hidden"])',
    ]
    for sel in selectors:
        locs = page.locator(sel)
        n = locs.count()
        print("SEL", sel, "count", n)
        for i in range(min(n, 8)):
            loc = locs.nth(i)
            try:
                if not loc.is_visible():
                    continue
                box = loc.bounding_box()
                if not box or box["width"] < 100:
                    continue
                # skip sidebar search (narrow / left)
                if box["x"] < 250:
                    print("skip sidebar-ish", box)
                    continue
                loc.click()
                loc.fill("")
                loc.fill(value)
                page.wait_for_timeout(200)
                loc.press("Enter")
                print("FILLED", value, "via", sel, i, box)
                page.wait_for_timeout(3500)
                return True
            except Exception as e:
                print("fill fail", i, type(e).__name__, e)
    # JS React-aware set
    ok = page.evaluate(
        """(v) => {
          const inputs = [...document.querySelectorAll('input')].filter(i => i.offsetParent && (i.placeholder||'').toLowerCase().includes('search'));
          const el = inputs.sort((a,b)=>b.offsetWidth-a.offsetWidth)[0];
          if (!el) return {ok:false};
          el.focus();
          const proto = window.HTMLInputElement.prototype;
          const desc = Object.getOwnPropertyDescriptor(proto, 'value');
          desc.set.call(el, v);
          el.dispatchEvent(new InputEvent('input', { bubbles: true, data: v, inputType: 'insertText' }));
          el.dispatchEvent(new Event('change', { bubbles: true }));
          el.dispatchEvent(new KeyboardEvent('keydown', { key: 'Enter', code: 'Enter', bubbles: true }));
          el.dispatchEvent(new KeyboardEvent('keypress', { key: 'Enter', code: 'Enter', bubbles: true }));
          el.dispatchEvent(new KeyboardEvent('keyup', { key: 'Enter', code: 'Enter', bubbles: true }));
          return {ok:true, val: el.value, ph: el.placeholder};
        }""",
        value,
    )
    print("JS", ok)
    page.wait_for_timeout(3500)
    return bool(ok and ok.get("ok"))


def main():
    with sync_playwright() as p:
        browser = p.chromium.connect_over_cdp(CDP)
        context = browser.contexts[0] if browser.contexts else browser.new_context()
        page = pick_page(context)
        page.bring_to_front()
        print("PAGE", page.url)
        shot(page, "60-cdp-start.png")

        page.goto(MANAGE, wait_until="domcontentloaded", timeout=90000)
        page.wait_for_timeout(4000)
        select_gbaf(page)
        page.wait_for_timeout(2000)
        # personalization wait
        for _ in range(10):
            body = ""
            try:
                body = page.inner_text("body")[:400]
            except Exception:
                pass
            if "personalization" in body.lower():
                print("waiting personalization")
                page.wait_for_timeout(2000)
                select_gbaf(page)
            else:
                break
        shot(page, "61-cdp-manage.png")

        fill_search(page, "JOHN")
        shot(page, "62-cdp-search-john.png")

        # If Select visible, click first Select for JOHN
        try:
            page.get_by_role("button", name="Select").first.click(timeout=5000)
            print("clicked Select")
            page.wait_for_timeout(3000)
        except Exception as e:
            print("Select miss", type(e).__name__, e)
            # try link/text
            try:
                page.get_by_text("Select", exact=True).first.click(timeout=3000)
                page.wait_for_timeout(3000)
            except Exception as e2:
                print("Select text miss", e2)

        shot(page, "63-cdp-after-select.png")

        # Look for Customer Details / Inquiry / Ownership Transfer History
        texts = [
            "Customer Details",
            "Account Inquiry",
            "View Ownership Transfer History",
            "Ownership Transfer History",
            "Ownership Transfer",
        ]
        found = {}
        body = ""
        try:
            body = page.inner_text("body")
        except Exception:
            pass
        for t in texts:
            found[t] = t.lower() in body.lower()
        print("FOUND", json.dumps(found))
        (PROOF / "64-cdp-findings.json").write_text(json.dumps({"url": page.url, "found": found, "body_sample": body[:2500]}, indent=2), encoding="utf-8")

        for t in ["View Ownership Transfer History", "Ownership Transfer History", "Customer Details"]:
            try:
                loc = page.get_by_text(t, exact=False).first
                if loc.is_visible(timeout=1500):
                    loc.click()
                    print("clicked", t)
                    page.wait_for_timeout(2500)
                    shot(page, f"65-cdp-{t.replace(' ', '_')[:40]}.png")
            except Exception:
                pass

        # Expand Account Management and dump menu text
        try:
            page.get_by_text("Account Management", exact=False).first.click(timeout=3000)
            page.wait_for_timeout(1000)
        except Exception:
            pass
        shot(page, "66-cdp-am-menu.png")
        menu = page.evaluate(
            """() => {
              const side = document.querySelector('nav, aside, [class*="sidebar" i], [class*="SideBar" i]');
              return (side ? side.innerText : document.body.innerText).slice(0, 3000);
            }"""
        )
        print("MENU_SAMPLE", menu[:1200].replace("\n", " | "))
        (PROOF / "67-cdp-menu.txt").write_text(menu, encoding="utf-8")
        shot(page, "68-cdp-final.png")
        print("DONE")


if __name__ == "__main__":
    main()

"""Stabilize AuNEXO login then enter TD from Home (same tab). Never print secrets."""
from __future__ import annotations

import json
import time
from pathlib import Path

from playwright.sync_api import sync_playwright

PROOF = Path(r"E:\LIQA\workspace\default-run\reports\proof\PF-59422")
CREDS = Path(r"E:\LIQA\secrets\tmp-creds.json")
CDP = "http://127.0.0.1:9333"
HOME = "https://uat.fusionx.biz/web/home/cNwNb/dashboard"
MANAGE = "https://uat.fusionx.biz/web/td/cNwNb/accounts/manage-account"


def shot(page, name: str):
    page.screenshot(path=str(PROOF / name), full_page=False)
    print("SHOT", name, (page.url or "")[:140])


def creds():
    d = json.loads(CREDS.read_text(encoding="utf-8"))
    return d["maker_email"], d["maker_password"]


def on_fusion(page) -> bool:
    u = (page.url or "").lower()
    return "uat.fusionx.biz/web" in u and "aunex" not in u and "login" not in u


def do_login(page, email: str, password: str) -> bool:
    page.goto(HOME, wait_until="domcontentloaded", timeout=120000)
    page.wait_for_timeout(3000)
    if on_fusion(page):
        print("already_in")
        shot(page, "140-already.png")
        return True

    # Clear and fill email+password
    email_box = page.locator('input[type="email"]').first
    if email_box.count() == 0:
        email_box = page.locator('input[placeholder="Username"]').first
    email_box.click()
    email_box.fill(email)
    page.locator('input[type="password"]').first.fill(password)
    # Remember me on
    try:
        toggle = page.locator('text=Remember Me').locator("..").locator("input, button, [role=switch]").first
        # ignore
    except Exception:
        pass
    page.locator('button:has-text("SIGN IN")').first.click()
    # Wait for navigation away from aunexo
    for i in range(24):
        page.wait_for_timeout(2500)
        print("login_poll", i, page.url[:110])
        shot(page, f"141-login-poll-{i}.png") if i % 3 == 0 else None
        if on_fusion(page):
            # settle
            page.wait_for_timeout(3000)
            shot(page, "142-home.png")
            return True
        # If invalid credentials message
        try:
            b = page.inner_text("body").lower()
            if "invalid" in b or "incorrect" in b or "failed" in b:
                print("LOGIN_ERROR_TEXT")
                (PROOF / "143-error.txt").write_text(b[:1500], encoding="utf-8")
                break
        except Exception:
            pass
    shot(page, "144-login-timeout.png")
    return on_fusion(page)


def enter_td(page) -> bool:
    """Prefer clicking TD tile from Home; fallback URL."""
    shot(page, "150-before-td.png")
    # Try clickable TD / Term Deposit
    for label in ["TD", "Term Deposit", "Term Deposits", "Fixed Deposit"]:
        try:
            loc = page.get_by_text(label, exact=True).first
            if loc.is_visible(timeout=1500):
                loc.click()
                page.wait_for_timeout(4000)
                print("clicked", label, page.url[:100])
                if "/td/" in page.url or "td" in page.url.lower():
                    shot(page, "151-td-click.png")
                    return True
        except Exception:
            continue
    # tiles often have img/alt
    try:
        page.locator('[href*="/td/"], a:has-text("TD")').first.click(timeout=4000)
        page.wait_for_timeout(4000)
        print("href td", page.url[:100])
    except Exception as e:
        print("href miss", type(e).__name__)

    if "/td/" not in (page.url or ""):
        page.goto("https://uat.fusionx.biz/web/td/cNwNb/home", wait_until="domcontentloaded", timeout=120000)
        page.wait_for_timeout(4000)
    shot(page, "152-td.png")
    return on_fusion(page) and ("/td/" in page.url or "td" in page.url)


def select_gbaf(page):
    try:
        page.get_by_text("General Banking & Finance", exact=False).first.click(timeout=4000)
        page.wait_for_timeout(2000)
        print("GBAF")
        return True
    except Exception:
        return False


def wait_ready(page):
    for _ in range(20):
        b = ""
        try:
            b = page.inner_text("body")[:500].lower()
        except Exception:
            pass
        if "personalization" in b:
            page.wait_for_timeout(1500)
            select_gbaf(page)
            continue
        break


def search_and_select(page):
    page.goto(MANAGE, wait_until="domcontentloaded", timeout=120000)
    page.wait_for_timeout(3000)
    select_gbaf(page)
    wait_ready(page)
    if not on_fusion(page):
        print("LOST_SESSION_ON_MANAGE", page.url)
        shot(page, "160-lost.png")
        return False
    shot(page, "161-manage.png")
    try:
        page.get_by_text("Search By Customer Details", exact=False).first.click(timeout=3000)
    except Exception:
        pass
    filled = False
    for loc in page.locator('input[placeholder*="Search" i]').all():
        box = loc.bounding_box()
        if not box or box["x"] < 260:
            continue
        loc.fill("JOHN")
        loc.press("Enter")
        filled = True
        print("filled", box)
        break
    if not filled:
        page.evaluate(
            """() => {
              const el=[...document.querySelectorAll('input')].filter(i=>i.offsetParent&&(i.placeholder||'').toLowerCase().includes('search')&&i.getBoundingClientRect().x>260).sort((a,b)=>b.offsetWidth-a.offsetWidth)[0];
              if(!el) return false;
              const s=Object.getOwnPropertyDescriptor(HTMLInputElement.prototype,'value').set;
              el.focus(); s.call(el,'JOHN');
              el.dispatchEvent(new InputEvent('input',{bubbles:true,data:'JOHN',inputType:'insertText'}));
              el.dispatchEvent(new KeyboardEvent('keydown',{key:'Enter',bubbles:true}));
              return true;
            }"""
        )
    page.wait_for_timeout(5000)
    shot(page, "162-results.png")
    try:
        page.get_by_role("button", name="Select").first.click(timeout=8000)
        print("Select")
    except Exception:
        try:
            page.locator("text=Select").first.click(timeout=5000)
        except Exception as e:
            print("no select", e)
    page.wait_for_timeout(4000)
    shot(page, "163-selected.png")
    body = page.inner_text("body")
    findings = {k: k.lower() in body.lower() for k in [
        "JOHN NGEERA", "CUS000000020107", "Customer Details", "Account Inquiry",
        "View Ownership Transfer History", "Ownership Transfer History",
        "Manage Selected Account", "403", "Forbidden",
    ]}
    print("FINDINGS", findings)
    (PROOF / "164-findings.json").write_text(
        json.dumps({"url": page.url, "findings": findings, "sample": body[:4000]}, indent=2),
        encoding="utf-8",
    )
    for label in ["View Ownership Transfer History", "Ownership Transfer History", "Customer Details"]:
        if findings.get(label):
            try:
                page.get_by_text(label, exact=False).first.click(timeout=5000)
                page.wait_for_timeout(3000)
                shot(page, "165-" + label.replace(" ", "_")[:35] + ".png")
            except Exception as e:
                print("click", label, e)
    shot(page, "166-final.png")
    return True


def main():
    email, password = creds()
    with sync_playwright() as p:
        browser = p.chromium.connect_over_cdp(CDP)
        ctx = browser.contexts[0]
        # Reuse an existing page if on login/fusion
        page = None
        for pg in ctx.pages:
            if "aunex" in (pg.url or "").lower() or "fusionx" in (pg.url or "").lower() or "microsoft" in (pg.url or "").lower():
                page = pg
                break
        if page is None:
            page = ctx.new_page()
        page.bring_to_front()
        if not do_login(page, email, password):
            print("LOGIN_FAILED")
            return
        if not enter_td(page):
            print("TD_FAILED", page.url)
            shot(page, "153-td-fail.png")
            # still try manage if somehow in
        select_gbaf(page)
        wait_ready(page)
        search_and_select(page)
        print("DONE", page.url)


if __name__ == "__main__":
    main()

"""Login via CDP with press_sequentially; soft screenshots; never print secrets."""
from __future__ import annotations

import json
import time
from pathlib import Path

from playwright.sync_api import sync_playwright

PROOF = Path(r"E:\LIQA\workspace\default-run\reports\proof\PF-59422")
CREDS = Path(r"E:\LIQA\secrets\tmp-creds.json")
CDP = "http://127.0.0.1:9333"
HOME = "https://uat.fusionx.biz/web/home/cNwNb/dashboard"
MANAGE = "https://uat.fusionx.biz/web/td/cNwNb/accounts/manage-account"


def shot(page, name: str):
    try:
        page.screenshot(path=str(PROOF / name), full_page=False, timeout=10000)
        print("SHOT", name, (page.url or "")[:120])
    except Exception as e:
        print("SHOT_FAIL", name, type(e).__name__)


def on_fusion(page) -> bool:
    u = (page.url or "").lower()
    return "uat.fusionx.biz/web" in u and "aunex" not in u and "/account/login" not in u


def main():
    d = json.loads(CREDS.read_text(encoding="utf-8"))
    email, password = d["maker_email"], d["maker_password"]
    print("email_domain_ok", email.endswith("@lolctech.com"), "pw_len", len(password))

    with sync_playwright() as p:
        browser = p.chromium.connect_over_cdp(CDP)
        ctx = browser.contexts[0]
        page = ctx.new_page()
        page.set_default_timeout(20000)
        page.goto(HOME, wait_until="domcontentloaded", timeout=120000)
        page.wait_for_timeout(2000)
        shot(page, "170-start.png")
        if on_fusion(page):
            print("ALREADY")
        else:
            # email
            box = page.locator('input[type="email"]').first
            box.click()
            box.fill("")
