    """Wait until personalization gone; click GBAF only when modal title present."""
    t0 = time.time()
    i = 0
    gbaf_clicks = 0
    while time.time() - t0 < max_s:
        b = body(page).lower()
        if "personalization is in progress" in b:
            if i % 4 == 0:
                shot(page, f"{tag}-w-pers-{i}.png")
            page.wait_for_timeout(2000)
            i += 1
            continue
        # Only treat as modal when the title is present (not sidebar GBAF chip)
        if "select banking & finance type" in b or "select banking and finance type" in b:
            shot(page, f"{tag}-w-gbaf-modal.png")
            if gbaf_clicks < 3:
                clicked = False
                for pat in (r"General Banking & Finance", r"Conventional products under the GBAF"):
                    try:
                        loc = page.get_by_text(re.compile(pat, re.I))
                        if loc.count():
                            loc.first.click(timeout=4000)
                            clicked = True
                            gbaf_clicks += 1
                            page.wait_for_timeout(3000)
                            break
                    except Exception:
                        continue
                if clicked:
                    shot(page, f"{tag}-w-after-gbaf.png")
                    continue
            # modal stuck — still return so caller can proceed / fail honestly
            return False
        # ready enough (app shell without banking-type modal)
