"""PF-59422 honesty-20 + MethmiB 2QA on FusionX TD (CDP :9555). No password printing."""
from __future__ import annotations

import base64
import json
import re
import time
from pathlib import Path

from playwright.sync_api import sync_playwright

PROOF = Path(r"E:\LIQA\workspace\default-run\reports\proof\PF-59422")
PROOF.mkdir(parents=True, exist_ok=True)
OUT = PROOF / "honesty20-reinit-run.json"
CREDS = Path(r"E:\LIQA\secrets\tmp-creds.json")

CASE = "PF-59422-HISTORY-BTN-REINIT"
TD_HOME = "https://uat.fusionx.biz/web/td/cNwNb/dashboard"
MANAGE = "https://uat.fusionx.biz/web/td/cNwNb/accounts/manage-account"


def load_creds():
    d = json.loads(CREDS.read_text(encoding="utf-8"))
    return d["maker_email"], d["maker_password"], d["checker_email"], d["checker_password"]


def txt(page, n=2500):
    return page.evaluate(
        "(n) => (document.body && document.body.innerText || '').slice(0, n)", n
    )


def shot(page, name: str) -> str:
    cdp = page.context.new_cdp_session(page)
    data = cdp.send("Page.captureScreenshot", {"format": "png"})
    path = PROOF / f"{name}.png"
    path.write_bytes(base64.b64decode(data["data"]))
    return str(path)


def history_visible(t: str) -> bool:
    return bool(re.search(r"Ownership\s+Transfer\s+History", t, re.I))


def td_page(browser):
    for ctx in browser.contexts:
        for pg in ctx.pages:
            if "/web/td/" in pg.url and "chrome://" not in pg.url:
                return pg
    # fallback first non-ui
    for ctx in browser.contexts:
        for pg in ctx.pages:
            if pg.url.startswith("http"):
                return pg
    raise RuntimeError("no page")


def ensure_gbaf(page):
    t = txt(page, 800)
    if "Select Banking & Finance Type" in t or "GBAF" in t and "Business Unit" in t:
        try:
            page.get_by_text("GBAF", exact=True).first.click(timeout=3000)
            time.sleep(0.5)
            page.get_by_role("button", name=re.compile("Continue|OK|Select", re.I)).first.click(
                timeout=3000
            )
            time.sleep(1.5)
        except Exception:
            pass


def goto_manage(page):
    page.goto(MANAGE, wait_until="domcontentloaded", timeout=60000)
    time.sleep(2.5)
    ensure_gbaf(page)
    # force sidebar manage if needed
    try:
        page.locator('[id="/cNwNb/accounts/manage-account"]').click(force=True, timeout=4000)
        time.sleep(1.5)
    except Exception:
        pass


def search_john(page):
    # Prefer content search box
    box = page.locator('input[placeholder*="Search" i], input[type="search"]').last
    try:
        box.click(timeout=4000)
        box.fill("")
        box.fill("JOHN")
        box.press("Enter")
    except Exception:
        page.keyboard.type("JOHN")
        page.keyboard.press("Enter")
    time.sleep(2.5)


def select_john(page):
    # Prefer JOHN NGEERA row Select
    try:
        row = page.locator("tr").filter(has_text=re.compile("JOHN NGEERA", re.I)).first
        row.get_by_text("Select", exact=True).click(force=True, timeout=6000)
    except Exception:
        page.locator("table").get_by_text("Select", exact=True).first.click(
            force=True, timeout=8000
        )
    time.sleep(2.5)


def success_check(page) -> dict:
    t = txt(page)
    ok = history_visible(t)
    return {
        "history": ok,
        "crm": "Customer Relationship Management" in t,
        "snip": t[:500],
        "url": page.url,
    }


def attempt(page, n: int, name: str, fn) -> dict:
    try:
        fn()
        time.sleep(1.0)
        chk = success_check(page)
        proof = shot(page, f"honesty-{n:02d}-{name}")
        result = "FOUND_WAY" if chk["history"] else "FAILED"
        return {
            "n": n,
            "approach": name,
            "result": result,
            "proof": proof,
            **chk,
        }
    except Exception as e:
        proof = ""
        try:
            proof = shot(page, f"honesty-{n:02d}-{name}-err")
        except Exception:
            pass
        return {
            "n": n,
            "approach": name,
            "result": "FAILED",
            "proof": proof,
            "error": str(e)[:300],
            "history": False,
            "url": getattr(page, "url", ""),
        }


def login_if_needed(page, email: str, password: str):
    t = txt(page, 600)
    if "Sign in" in t or "password" in t.lower() or "login" in page.url.lower():
        try:
            page.locator('input[type="email"], input[name="loginfmt"]').first.fill(email, timeout=5000)
            page.keyboard.press("Enter")
            time.sleep(2)
        except Exception:
            pass
        try:
            page.locator('input[type="password"]').first.fill(password, timeout=8000)
            page.keyboard.press("Enter")
            time.sleep(4)
        except Exception:
            pass
        # stay signed in etc
        for label in ("Yes", "Next", "Continue"):
            try:
                page.get_by_role("button", name=label).click(timeout=2000)
                time.sleep(1)
            except Exception:
                pass


def logout_azure(page):
    # best-effort Microsoft logout then TD entry
    try:
        page.goto("https://login.microsoftonline.com/logout.srf", wait_until="domcontentloaded", timeout=30000)
        time.sleep(2)
    except Exception:
        pass


def run_honesty(page) -> list[dict]:
    results = []

    def a01():
        # already on selected manage account — click Customer Details
        page.bring_to_front()
        if "manage-account/" in page.url and page.url.rstrip("/").count("/") > 6:
            pass
        else:
            goto_manage(page)
            search_john(page)
            select_john(page)
        page.get_by_text("Customer Details", exact=False).first.click(force=True, timeout=5000)

    def a02():
        page.get_by_text("Accounts", exact=True).first.click(force=True, timeout=4000)
        time.sleep(1)
        page.get_by_text("Customer Details", exact=False).first.click(force=True, timeout=4000)

    def a03():
        page.reload(wait_until="domcontentloaded")
        time.sleep(2.5)
        ensure_gbaf(page)

    def a04():
        goto_manage(page)
        search_john(page)
        select_john(page)

    def a05():
        # search then keyboard Enter on Select via focus
        goto_manage(page)
        search_john(page)
        page.locator("table").get_by_text("Select", exact=True).nth(0).focus()
        page.keyboard.press("Enter")
        time.sleep(2)

    def a06():
        goto_manage(page)
        search_john(page)
        page.locator("table").get_by_text("Select", exact=True).nth(1).click(force=True, timeout=5000)
        time.sleep(2)

    def a07():
        # scroll + look for any History-like control in DOM
        page.evaluate("window.scrollTo(0, document.body.scrollHeight)")
        time.sleep(0.5)
        page.evaluate("window.scrollTo(0, 0)")
        loc = page.locator("text=/History/i")
        if loc.count():
            loc.first.click(force=True, timeout=3000)

    def a08():
        # Maintenance menu Ownership Transfer if present
        for label in ("Maintenance", "Ownership Transfer", "Owner Transfer"):
            try:
                page.get_by_text(label, exact=False).first.click(force=True, timeout=2500)
                time.sleep(1)
            except Exception:
                pass

    def a09():
        # Account Inquiry sibling URLs under TD
        for path in (
            "/web/td/cNwNb/accounts/account-inquiry",
            "/web/td/cNwNb/accounts/inquiry",
            "/web/td/cNwNb/customer/inquiry",
        ):
            page.goto("https://uat.fusionx.biz" + path, wait_until="domcontentloaded", timeout=30000)
            time.sleep(1.5)
            if "404" not in txt(page, 400) and "not found" not in txt(page, 400).lower():
                break
        ensure_gbaf(page)

    def a10():
        # open Customer Inquiry cob tab if exists in browser
        pass  # handled below with page switch

    def a11():
        page.goto(TD_HOME, wait_until="domcontentloaded", timeout=60000)
        time.sleep(2)
        ensure_gbaf(page)
        page.locator('[id="/cNwNb/accounts/manage-account"]').click(force=True, timeout=5000)
        time.sleep(1.5)
        search_john(page)
        select_john(page)

    def a12():
        # Search By Accounts tab then back
        goto_manage(page)
        try:
            page.get_by_text("Search By Accounts", exact=False).first.click(timeout=3000)
            time.sleep(1)
        except Exception:
            pass
        try:
            page.get_by_text("Search By Customer Details", exact=False).first.click(timeout=3000)
        except Exception:
            pass
        search_john(page)
        select_john(page)

    def a13():
        # double-click Select
        goto_manage(page)
        search_john(page)
        sel = page.locator("table").get_by_text("Select", exact=True).first
        sel.dblclick(timeout=5000)
        time.sleep(2)

    def a14():
        # hard CDP reload bypass cache
        page.evaluate("location.reload(true)")
        time.sleep(3)
        ensure_gbaf(page)

    def a15():
        # click toast / dismiss then look again
        for label in ("Close", "OK", "Dismiss", "×"):
            try:
                page.get_by_text(label, exact=True).first.click(timeout=1500)
            except Exception:
                pass
        page.get_by_text("Customer Details", exact=False).first.click(force=True, timeout=4000)

    def a16():
        # Confirmation List then back to Manage Account
        try:
            page.locator('[id="/cNwNb/accounts/confirmation-list"]').click(force=True, timeout=3000)
            time.sleep(1.5)
        except Exception:
            pass
        goto_manage(page)
        search_john(page)
        select_john(page)

    def a17():
        # Expand any accordion / more actions
        for label in ("More", "Actions", "View", "Details", "Expand"):
            try:
                page.get_by_text(label, exact=True).first.click(force=True, timeout=1500)
                time.sleep(0.5)
            except Exception:
                pass

    def a18():
        # try Ownership in page HTML buttons
        handles = page.locator("button, a, span").filter(has_text=re.compile("Owner|Transfer|History", re.I))
        if handles.count():
            handles.first.click(force=True, timeout=3000)
            time.sleep(1.5)

    def a19():
        # re-select after clearing search
        goto_manage(page)
        box = page.locator('input[placeholder*="Search" i], input[type="search"]').last
        try:
            box.fill("")
            box.press("Enter")
            time.sleep(1)
        except Exception:
            pass
        search_john(page)
        select_john(page)
        page.get_by_text("Customer Details", exact=False).first.click(force=True, timeout=4000)

    def a20():
        # stay on selected URL and inspect all frames text
        for fr in page.frames:
            try:
                t = fr.inner_text("body")
                if history_visible(t):
                    # click it in frame
                    fr.get_by_text(re.compile("Ownership Transfer History", re.I)).first.click(timeout=3000)
            except Exception:
                pass

    approaches = [
        ("customer-details-tab", a01),
        ("accounts-then-details", a02),
        ("reload-selected", a03),
        ("research-select-john", a04),
        ("keyboard-enter-select", a05),
        ("select-second-john-row", a06),
        ("scroll-click-history-text", a07),
        ("maintenance-ownership-menu", a08),
        ("td-account-inquiry-urls", a09),
        ("noop-placeholder", a10),
        ("from-td-dashboard-manage", a11),
        ("search-by-accounts-toggle", a12),
        ("doubleclick-select", a13),
        ("hard-reload", a14),
        ("dismiss-toast-details", a15),
        ("confirmation-list-roundtrip", a16),
        ("more-actions-expand", a17),
        ("owner-transfer-history-dom", a18),
        ("clear-research-details", a19),
        ("all-frames-history-scan", a20),
    ]

    # replace a10 with Customer Inquiry tab switch if available
    def a10_real():
        browser = page.context.browser
        assert browser
        for ctx in browser.contexts:
            for pg in ctx.pages:
                if "onboarding/view" in pg.url or "Customer Inquiry" in (pg.title() or ""):
                    pg.bring_to_front()
                    time.sleep(1)
                    # copy check onto that page via mutating outer page ref — use evaluate on pg
                    nonlocal_holder["alt"] = pg
                    return
        # else open from selected manage if link exists
        try:
            page.get_by_text("Customer Inquiry", exact=False).first.click(timeout=3000)
            time.sleep(2)
        except Exception:
            pass

    nonlocal_holder: dict = {}
    approaches[9] = ("customer-inquiry-surface", a10_real)

    for i, (name, fn) in enumerate(approaches, 1):
        # for a10 use alt page if set mid-flight — handle specially
        if name == "customer-inquiry-surface":
            fn()
            pg = nonlocal_holder.get("alt", page)
            chk = success_check(pg)
            proof = shot(pg, f"honesty-{i:02d}-{name}")
            results.append(
                {
                    "n": i,
                    "approach": name,
                    "result": "FOUND_WAY" if chk["history"] else "FAILED",
                    "proof": proof,
                    **chk,
                }
            )
            # bring TD back
            page.bring_to_front()
        else:
            results.append(attempt(page, i, name, fn))
        # early exit if found a way
        if results[-1]["result"] == "FOUND_WAY":
            break
    return results


def run_checker_2qa(browser, checker_email, checker_password) -> dict:
    # new page in same browser for checker walk
    ctx = browser.contexts[0]
    page = ctx.new_page()
    logout_azure(page)
    page.goto(TD_HOME, wait_until="domcontentloaded", timeout=60000)
    time.sleep(2)
    login_if_needed(page, checker_email, checker_password)
    page.goto(TD_HOME, wait_until="domcontentloaded", timeout=60000)
    time.sleep(2.5)
    ensure_gbaf(page)
    shot(page, "2qa-00-td-home")
    # product gate
    t0 = txt(page)
    if "fusion" not in t0.lower() and "TD" not in t0:
        return {"ok": False, "error": "not_td", "snip": t0[:300]}
    goto_manage(page)
    shot(page, "2qa-01-manage")
    search_john(page)
