from __future__ import annotations

import base64
import json
import re
import subprocess
import time
from pathlib import Path

from playwright.sync_api import sync_playwright

PROOF = Path(r"E:\LIQA\workspace\default-run\reports\proof\PF-59440")
CREDS = Path(r"E:\LIQA\secrets\tmp-creds.json")
CHROME = r"C:\Program Files\Google\Chrome\Application\chrome.exe"
PROFILE = Path(r"E:\LIQA\workspace\default-run\.chrome-checker-9557")
PORT = 9557
CASA_HOME = "https://uat.fusionx.biz/web/casa/cNwNb/"
CASA_SETTINGS = "https://uat.fusionx.biz/web/casa/cNwNb/settings"


def creds():
    d = json.loads(CREDS.read_text(encoding="utf-8"))
    return d["checker_email"], d["checker_password"]


def txt(page, n=2000):
    for _ in range(6):
        try:
            return page.evaluate(
                "(n) => (document.body && document.body.innerText || '').slice(0, n)", n
            )
        except Exception:
            time.sleep(1)
    return ""


def shot(page, name: str) -> str:
    path = PROOF / f"{name}.png"
    for _ in range(4):
        try:
            cdp = page.context.new_cdp_session(page)
            data = cdp.send("Page.captureScreenshot", {"format": "png"})
            path.write_bytes(base64.b64decode(data["data"]))
            return str(path)
        except Exception:
            try:
                page.screenshot(path=str(path), timeout=12000)
                return str(path)
            except Exception:
                time.sleep(1)
    return str(path)


def ensure_port():
    import urllib.request

    try:
        urllib.request.urlopen(f"http://127.0.0.1:{PORT}/json/version", timeout=1)
        return
    except Exception:
        pass
    PROFILE.mkdir(parents=True, exist_ok=True)
    subprocess.Popen(
        [
            CHROME,
            f"--remote-debugging-port={PORT}",
            f"--user-data-dir={PROFILE}",
            "--no-first-run",
            "--no-default-browser-check",
            CASA_HOME,
        ],
        stdout=subprocess.DEVNULL,
        stderr=subprocess.DEVNULL,
    )
    for _ in range(50):
        try:
            urllib.request.urlopen(f"http://127.0.0.1:{PORT}/json/version", timeout=1)
            return
        except Exception:
            time.sleep(0.4)
    raise RuntimeError("port not up")


def login(page, email: str, password: str) -> bool:
    page.goto(CASA_HOME, wait_until="domcontentloaded", timeout=90000)
    time.sleep(2.5)
    shot(page, "2qa-login-01")
    for label in ("Continue with AzureAd", "Continue with Azure", "AzureAd", "Azure AD"):
        try:
            page.get_by_text(label, exact=False).first.click(timeout=3000)
            time.sleep(2.5)
            break
        except Exception:
            pass
    t = txt(page)
    if "SIGN IN" in t or "Username" in t:
        try:
            page.get_by_placeholder(re.compile("Username|Email|User", re.I)).first.fill(
                email, timeout=3000
            )
        except Exception:
            try:
                page.locator("input").nth(0).fill(email)
            except Exception:
                pass
        try:
            page.get_by_placeholder(re.compile("Password", re.I)).first.fill(password, timeout=3000)
        except Exception:
            try:
                page.locator('input[type="password"]').first.fill(password)
            except Exception:
                pass
        try:
            page.get_by_role("button", name=re.compile("SIGN IN|Sign in", re.I)).click(timeout=3000)
            time.sleep(3)
        except Exception:
            pass

    for _ in range(14):
        url = page.url.lower()
        body = txt(page, 900)
        if "/web/casa/" in url and "login" not in url and "aunexo" not in body.lower():
            if any(
                x in body
                for x in ("Account Management", "Dashboard", "Settings", "IBAF", "CASA", "fusion")
            ):
                return True
        try:
            if page.locator('input[type="email"], input[name="loginfmt"]').count():
                page.locator('input[type="email"], input[name="loginfmt"]').first.fill(email)
                page.keyboard.press("Enter")
                time.sleep(2.5)
                continue
        except Exception:
            pass
        try:
            if page.locator('input[type="password"], input[name="passwd"]').count():
                page.locator('input[type="password"], input[name="passwd"]').first.fill(password)
                page.keyboard.press("Enter")
                time.sleep(4)
                continue
        except Exception:
            pass
        for lab in ("Yes", "Next", "Continue", "Ask later", "No"):
            try:
                page.get_by_role("button", name=re.compile(f"^{lab}$", re.I)).click(timeout=1200)
                time.sleep(1.2)
            except Exception:
                pass
        try:
            page.get_by_text(email, exact=False).first.click(timeout=1500)
            time.sleep(1.5)
        except Exception:
            pass
        low = body.lower()
        if any(x in low for x in ("approve", "authenticator", "enter code", "otp", "verify your identity")):
            shot(page, "2qa-mfa-gate")
            return False
        time.sleep(1)
        shot(page, "2qa-login-loop")
    shot(page, "2qa-login-final")
    body = txt(page, 800)
    return "/web/casa/" in page.url and "SIGN IN" not in body


def ensure_ibaf(page):
    body = txt(page, 1200)
    if "Select Banking" in body or "Islamic Banking" in body:
        try:
            page.get_by_text(re.compile("Islamic Banking|IBAF", re.I)).first.click(timeout=5000)
            time.sleep(0.5)
            page.get_by_role("button", name=re.compile("Continue|OK|Select", re.I)).first.click(
                timeout=4000
            )
            time.sleep(1.5)
        except Exception:
            pass


