                "needs_human_gate": "mfa" in txt(page, 500).lower()
                or (PROOF / "2qa-mfa-gate.png").exists(),
            }
            (PROOF / "2qa-methmib-run.json").write_text(json.dumps(out, indent=2), encoding="utf-8")
            print(json.dumps(out, indent=2))
            return
        ensure_ibaf(page)
        shot(page, "2qa-01-ibaf")
        page.goto(CASA_SETTINGS, wait_until="domcontentloaded", timeout=90000)
        time.sleep(2)
        ensure_ibaf(page)
        shot(page, "2qa-02-settings")
        # Find-a-Settings search
        try:
            box = page.get_by_placeholder(re.compile("Find|Search|Settings", re.I)).first
            box.click(timeout=4000)
            box.fill("Profit Sharing")
            time.sleep(1.5)
        except Exception:
            try:
                page.locator("input").first.fill("Profit Sharing")
                time.sleep(1.5)
            except Exception:
                pass
        shot(page, "2qa-03-search-profit")
        t_search = txt(page)
        # Product Definition expand
        try:
            page.get_by_text("Product Definition", exact=False).first.click(timeout=4000)
            time.sleep(1.2)
        except Exception:
            pass
        shot(page, "2qa-04-product-definition")
        t = txt(page)
        who = "MethmiB" if "MethmiB" in t else ("checker" if email.split("@")[0].lower() in t.lower() else "unknown")
        template_visible = has_psr_template(t) or has_psr_template(t_search)
        out = {
            "ok": True,
            "role": "checker_MethmiB",
            "who": who,
            "template_visible": template_visible,
            "settings_url": page.url,
            "proof": str(PROOF / "2qa-04-product-definition.png"),
            "snip": t[:700],
            "confirms_maker_defect": not template_visible,
            "product": "FusionX CASA",
            "story": "PF-59440",
            "bug": "PF-59454",
        }
        (PROOF / "2qa-methmib-run.json").write_text(json.dumps(out, indent=2), encoding="utf-8")
        print(json.dumps({k: out[k] for k in out if k != "snip"}, indent=2))
