                const t = (el.innerText || el.getAttribute('aria-label') || el.getAttribute('placeholder') || el.value || '').trim().split('\\n')[0];
                if (t && t.length > 0 && t.length < 100) out.push(t);
              });
              return [...new Set(out)].slice(0, 100);
            }"""
        )
    except Exception:
        return []


def open_url(page, slug: str, url: str) -> dict:
    rec = {"slug": slug, "target": url}
    page.goto(url, wait_until="domcontentloaded", timeout=90000)
    time.sleep(2)
    wait_ready(page)
    try:
        page.keyboard.press("Escape")
    except Exception:
        pass
    body = txt(page)
    rec["final_url"] = page.url
    rec["title_hit"] = bool(
        re.search(r"ROD\s+(Request|Approval)|Document\s+Release|Temporary\s+Release", body, re.I)
    )
    rec["snip"] = body[:600]
    rec["controls"] = inventory(page)
    rec["proof"] = shot(page, f"deep-{slug}")
    print(f"GOTO {slug} final={page.url} title_hit={rec['title_hit']} ctrls={len(rec['controls'])}", flush=True)
    return rec


def probe_new_request(page) -> dict:
    rec = {"step": "new-request"}
    page.goto(URLS["rod-request"], wait_until="domcontentloaded", timeout=90000)
    time.sleep(2)
    wait_ready(page)
    try:
        page.get_by_role("button", name=re.compile("New Request", re.I)).first.click(timeout=5000)
        time.sleep(2)
        wait_ready(page)
        rec["opened"] = True
    except Exception as e:
        rec["opened"] = False
        rec["error"] = str(e)[:200]
        shot(page, "deep-new-request-fail")
        return rec
    body = txt(page, 6000)
    rec["url"] = page.url
    rec["snip"] = body[:800]
    rec["controls"] = inventory(page)
    rec["proof"] = shot(page, "deep-new-request")
    # try fill search asset lightly
    try:
        page.get_by_placeholder(re.compile("Search Asset|Search", re.I)).first.fill("JOHN")
        time.sleep(0.5)
        page.get_by_role("button", name=re.compile("^Search$", re.I)).first.click(timeout=3000)
        time.sleep(2)
        wait_ready(page)
        rec["search_john"] = {"ok": True, "snip": txt(page, 800)[:300], "proof": shot(page, "deep-new-request-search-john")}
    except Exception as e:
        rec["search_john"] = {"ok": False, "error": str(e)[:160]}
    # Cancel / Back if present — do not submit
    for label in ("Cancel", "Close", "Back"):
        try:
            page.get_by_role("button", name=re.compile(f"^{label}$", re.I)).first.click(timeout=1200)
            time.sleep(1)
            rec["exit"] = label
            break
        except Exception:
            pass
    print(f"NEW REQUEST opened={rec.get('opened')} ctrls={len(rec.get('controls') or [])}", flush=True)
    return rec


def probe_approval_queue(page) -> dict:
    rec = {"step": "approval-queue"}
    page.goto(URLS["rod-approval"], wait_until="domcontentloaded", timeout=90000)
    time.sleep(2)
    wait_ready(page)
    body = txt(page, 5000)
    rec["url"] = page.url
    rec["has_approval_title"] = "ROD Approval" in body
    rec["controls"] = inventory(page)
    rec["snip"] = body[:700]
    rec["proof"] = shot(page, "deep-rod-approval")
    for act in ("Search", "Refresh", "Reset", "Filter"):
        try:
            page.get_by_role("button", name=re.compile(f"^{act}$", re.I)).first.click(timeout=1200)
            time.sleep(1)
            wait_ready(page)
            shot(page, f"deep-rod-approval-{act.lower()}")
            rec.setdefault("actions", []).append(act)
        except Exception:
            pass
    print(f"APPROVAL title={rec['has_approval_title']} ctrls={len(rec['controls'])}", flush=True)
    return rec


def run_port(port: int, who: str) -> dict:
    out = {"who": who, "port": port, "screens": [], "probes": {}}
    with sync_playwright() as p:
        browser = p.chromium.connect_over_cdp(f"http://127.0.0.1:{port}", timeout=12000)
        page = browser.contexts[0].pages[0]
        page.bring_to_front()
        print(f"=== {who} port {port} start {txt(page,120).replace(chr(10),' ')[:60]}", flush=True)
        for slug, url in URLS.items():
            out["screens"].append(open_url(page, slug, url))
        out["probes"]["new_request"] = probe_new_request(page)
        out["probes"]["approval"] = probe_approval_queue(page)
    return out


def main():
    results = {"story": "PF-59458", "runs": []}
    for port, who in [(9561, "MethmiB"), (9560, "ThejanaD")]:
        try:
            results["runs"].append(run_port(port, who))
        except Exception as e:
            results["runs"].append({"who": who, "port": port, "error": str(e)[:300]})
            print(f"FAIL {who}: {e}", flush=True)
    path = PROOF / "rod-deep-run.json"
    path.write_text(json.dumps(results, indent=2), encoding="utf-8")
    # slim print
    slim = {"story": "PF-59458", "runs": []}
    for r in results["runs"]:
        s = {"who": r.get("who"), "port": r.get("port"), "error": r.get("error"), "screens": []}
        for sc in r.get("screens") or []:
            s["screens"].append(
                {
                    "slug": sc.get("slug"),
                    "final_url": sc.get("final_url"),
                    "title_hit": sc.get("title_hit"),
                    "n_controls": len(sc.get("controls") or []),
                    "proof": sc.get("proof"),
                }
            )
        pr = r.get("probes") or {}
        s["new_request_opened"] = (pr.get("new_request") or {}).get("opened")
        s["approval_title"] = (pr.get("approval") or {}).get("has_approval_title")
        slim["runs"].append(s)
    print(json.dumps(slim, indent=2), flush=True)


if __name__ == "__main__":
    main()

