    (PROOF / "kickoff-run.json").write_text(json.dumps(out, indent=2), encoding="utf-8")
    (MAP / "living-map.md").write_text(
        "# PF-59462 living map (kickoff)\n\n```json\n" + json.dumps(out, indent=2) + "\n```\n",
        encoding="utf-8",
    )
