"""PF-59472 wait-for-human login then Accrued hunt (visible)."""
from __future__ import annotations

import base64
import json
import re
import sys
import time
from pathlib import Path

from playwright.sync_api import sync_playwright

sys.stdout.reconfigure(line_buffering=True)
PROOF = Path(r"E:\LIQA\workspace\default-run\reports\proof\PF-59472")
PROOF.mkdir(parents=True, exist_ok=True)
CREDS = json.loads(Path(r"E:\LIQA\secrets\tmp-creds.json").read_text(encoding="utf-8"))
BASE = "https://uat.fusionx.biz/web/lending/cNwNb"
ENTRY = f"{BASE}/dashboard"


def txt(page, n=12000):
    return page.evaluate("(n)=>(document.body&&document.body.innerText||'').slice(0,n)", n)


def shot(page, name):
    path = PROOF / f"{name}.png"
    try:
        cdp = page.context.new_cdp_session(page)
        data = cdp.send("Page.captureScreenshot", {"format": "png"})
        path.write_bytes(base64.b64decode(data["data"]))
    except Exception:
        page.screenshot(path=str(path), full_page=False)
    print("SHOT", path.name, flush=True)
    return str(path)


def wait_ready(page, sec=40):
    end = time.time() + sec
    while time.time() < end:
        low = txt(page, 700).lower()
        if "launching" in low or "personalization" in low:
            time.sleep(1)
            continue
        return True
    return False


def lending(page):
    low = txt(page, 3000).lower()
    return "loan account management" in low or ("welcome" in low and "cNwNb" in low)


def loginish(page):
    low = txt(page, 2000).lower()
    return "sign in" in low and ("username" in low or "azuread" in low)


def accrued_signals(body: str):
    low = body.lower()
    return {
        "accrued_interest": "accrued interest" in low,
        "menu_hit": bool(re.search(r"accrued\s+interest", low)),
    }


def try_click(page, label):
    try:
        page.get_by_text(label, exact=False).first.click(timeout=6000)
        time.sleep(1.4)
        wait_ready(page)
        return True
    except Exception as e:
        print("click fail", label, str(e)[:80], flush=True)
        return False


def fill_login(page):
    print("WATCH: fill AuNEXO Username/Password + SIGN IN (secrets not printed)", flush=True)
    try:
        page.get_by_placeholder("Username").fill(CREDS["maker_email"])
    except Exception:
        page.locator('input[type="text"]').first.fill(CREDS["maker_email"])
    try:
        page.get_by_placeholder("Password").fill(CREDS["maker_password"])
    except Exception:
        page.locator('input[type="password"]').first.fill(CREDS["maker_password"])
    page.get_by_role("button", name=re.compile(r"SIGN\s*IN", re.I)).click()
    print("WATCH: if MFA appears, complete it NOW in this Chrome window", flush=True)


def hunt(page, out):
    hunts = []
    page.goto(ENTRY, wait_until="domcontentloaded", timeout=90000)
    time.sleep(2)
    wait_ready(page)
    home = txt(page, 6000)
    out["home"] = {"proof": shot(page, "00-home-lending"), "signals": accrued_signals(home), "snip": home[:1200]}
    hunts.append({"where": "dashboard", **accrued_signals(home)})

    try:
        page.keyboard.press("Control+f")
        time.sleep(0.3)
        page.keyboard.type("Accrued Interest", delay=40)
        time.sleep(1)
        out["find"] = shot(page, "01-find-accrued")
        page.keyboard.press("Escape")
    except Exception:
        pass

    for label in ("Loan Account Management", "Account Maintenance"):
        try_click(page, label)
    am = txt(page, 12000)
    out["am"] = {"proof": shot(page, "10-am"), "signals": accrued_signals(am), "snip": am[:1500]}
    hunts.append({"where": "am", **accrued_signals(am)})

    if try_click(page, "Inquiry") or try_click(page, "Account Inquiry"):
        inq = txt(page, 8000)
        out["inquiry"] = {"proof": shot(page, "20-inquiry"), "signals": accrued_signals(inq), "snip": inq[:1000]}
        hunts.append({"where": "inquiry", **accrued_signals(inq)})

    page.goto(ENTRY, wait_until="domcontentloaded", timeout=90000)
    time.sleep(2)
    wait_ready(page)
    if try_click(page, "Settings"):
        st = txt(page, 12000)
        out["settings"] = {"proof": shot(page, "30-settings"), "signals": accrued_signals(st), "snip": st[:1500]}
        hunts.append({"where": "settings", **accrued_signals(st)})

    for route, name in (
        ("/account-management/accrued-interest", "40-route-am-accrued"),
        ("/transaction-management/accrued-interest", "41-route-tm-accrued"),
    ):
        page.goto(f"{BASE}{route}", wait_until="domcontentloaded", timeout=60000)
        time.sleep(2)
        wait_ready(page)
        body = txt(page, 9000)
        out[name] = {"url": page.url, "proof": shot(page, name), "signals": accrued_signals(body), "snip": body[:1000]}
        hunts.append({"where": name, **accrued_signals(body)})

    feature = any(
        h.get("menu_hit") or h.get("accrued_interest")
        for h in hunts
        if h.get("where") in ("dashboard", "am", "settings")
    )
    for key in ("40-route-am-accrued", "41-route-tm-accrued"):
        snip = ((out.get(key) or {}).get("snip") or "").lower()
        if "accrued interest" in snip and any(x in snip for x in ("create", "calculation", "amount", "batch", "process")):
            feature = True
    out["hunts"] = hunts
    out["assert"] = shot(page, "90-assert-final")
    out["verdict"] = "FEATURE_REACHABLE" if feature else "N/A_KENYA_NO_MENU"
    return out["verdict"]


def main():
    out = {"story": "PF-59472", "clone_of": "PF-58379", "engine": "LIQA", "mode": "human_wait_visible"}
    with sync_playwright() as p:
        browser = p.chromium.launch(headless=False, slow_mo=200, args=["--start-maximized", "--window-position=40,40"])
        context = browser.new_context(no_viewport=True)
        page = context.new_page()
        page.goto(ENTRY, wait_until="domcontentloaded", timeout=120000)
        time.sleep(2)
        shot(page, "00-open")
        if loginish(page):
            fill_login(page)
        print("WATCH: waiting up to 180s for Lending dashboard after MFA...", flush=True)
        deadline = time.time() + 180
        while time.time() < deadline:
            if lending(page):
                print("WATCH: Lending detected", flush=True)
                break
            if loginish(page):
                # stay; human may still be typing MFA
                pass
            else:
                # maybe intermediate
                try:
                    page.goto(ENTRY, wait_until="domcontentloaded", timeout=30000)
                except Exception:
                    pass
            time.sleep(3)
        if not lending(page):
            out["verdict"] = "LOGIN_BLOCKED"
            out["proof"] = shot(page, "99-login-timeout")
            (PROOF / "execute-run.json").write_text(json.dumps(out, indent=2), encoding="utf-8")
            print("VERDICT LOGIN_BLOCKED", flush=True)
            time.sleep(15)
            browser.close()
            return
        verdict = hunt(page, out)
        (PROOF / "execute-run.json").write_text(json.dumps(out, indent=2), encoding="utf-8")
        print("VERDICT", verdict, flush=True)
        time.sleep(25)
        browser.close()
    print("DONE", flush=True)


if __name__ == "__main__":
    main()

