        for label in ("Test details", "Test Details", "Manual Test Steps", "Manual"):
            try:
                loc = fr.get_by_role("tab", name=label)
                if loc.count() > 0:
                    loc.first.click(timeout=3000)
                    page.wait_for_timeout(1000)
                    return
            except Exception:
