def _try_import_csv(page, frame, csv_path: Path) -> dict[str, Any]:
    """Import Manual steps CSV via Xray Import — NEVER Jira Attachments file input."""
    _open_test_details(page, frame)
    frame = _find_xray_frame(page)
    errors: list[str] = []

    # 1) Click Import / Import steps and use file chooser (correct Xray path)
    for label in ("Import steps", "Import Steps", "Import CSV", "Import"):
        try:
            with page.expect_file_chooser(timeout=6000) as fc_info:
                clicked = _click_text(frame, [label], timeout=2500)
                if not clicked:
                    clicked = _click_text(page.main_frame, [label], timeout=2500)
                if not clicked:
                    continue
            chooser = fc_info.value
            chooser.set_files(str(csv_path))
            page.wait_for_timeout(2000)
            _click_text(frame, ["Import", "Upload", "Confirm", "OK", "Done", "Submit"], timeout=4000)
            page.wait_for_timeout(2000)
            if _attachment_toast(page):
                errors.append(f"{label}: landed as attachment — wrong control")
                continue
            return {"ok": True, "method": f"file_chooser:{label}", "path": str(csv_path)}
        except Exception as e:
            errors.append(f"{label}: {e}")

    # 2) Xray-local file input only (near Import / Add Step), skip Jira attachment inputs
    try:
        # Prefer inputs inside xray iframe / steps panel
        candidates = []
        for fr in _collect_frames(page):
            u = (fr.url or "").lower()
            near_steps = _frame_has_text(fr, "Add Step") or _frame_has_text(fr, "Import") or "xray" in u
            if not near_steps and fr is not frame:
                continue
            inputs = fr.locator("input[type='file']")
            for i in range(inputs.count()):
                el = inputs.nth(i)
                try:
                    # skip clearly attachment-dedicated inputs if marked
                    name = (el.get_attribute("name") or "") + " " + (el.get_attribute("id") or "")
                    if "attach" in name.lower():
                        continue
                    candidates.append((fr, el))
                except Exception:
                    continue
        # Do not use candidates if the only ones are page-level attachment dropzones
        # Prefer the last candidate inside xray frame
        for fr, el in reversed(candidates):
            try:
                # Must click Import first if present
                _click_text(fr, ["Import", "Import steps"], timeout=2000)
                el.set_input_files(str(csv_path))
                page.wait_for_timeout(2000)
                _click_text(fr, ["Import", "Upload", "Confirm", "OK", "Done"], timeout=3000)
                page.wait_for_timeout(1500)
                if _attachment_toast(page):
                    errors.append("file_input became attachment")
                    continue
                return {"ok": True, "method": "xray_file_input", "path": str(csv_path)}
            except Exception as e:
                errors.append(f"xray_file_input: {e}")
    except Exception as e:
        errors.append(str(e))

    return {"ok": False, "error": "Xray Import not found / attachment path blocked", "errors": errors}

