#!/usr/bin/env python3
import json
import os
import sys
from pathlib import Path

sys.path.insert(0, str(Path(__file__).resolve().parents[1] / "mcp"))
os.environ.setdefault("LIQA_CHROME_CDP", "http://127.0.0.1:9333")

from playwright.sync_api import sync_playwright

JS = """() => {
  const out=[];
  const walk=(root, depth=0) => {
    if(!root || depth>10) return;
    const nodes = root.querySelectorAll ? root.querySelectorAll('*') : [];
    for (const el of nodes) {
      const t=(el.innerText||el.textContent||'').trim().slice(0,100);
      const aria=(el.getAttribute('aria-label')||'');
      const title=(el.getAttribute('title')||'');
      const blob=(t+' '+aria+' '+title);
      if (/\\b(import|add step|manual test|steps)\\b/i.test(blob) && blob.length<120) {
        out.push({
          tag: el.tagName,
          role: el.getAttribute('role')||'',
          t: t.slice(0,80),
          aria,
          title,
          id: el.id||'',
          cls: (el.className||'').toString().slice(0,80),
        });
      }
      if (el.shadowRoot) walk(el.shadowRoot, depth+1);
    }
  };
  walk(document);
  // dedupe
  const seen=new Set();
  const uniq=[];
  for (const h of out) {
    const k=h.tag+'|'+h.t+'|'+h.aria;
    if (seen.has(k)) continue;
    seen.add(k);
    uniq.push(h);
  }
  return uniq.slice(0,60);
}"""


def dump(page, label: str) -> None:
    page.wait_for_timeout(4000)
    body = page.locator("body").inner_text(timeout=8000) or ""
    print("===", label, page.url[:90])
    for n in ["Add Step", "Import", "Manual Test Steps", "Action", "Expected Result", "No steps"]:
        print(" ", n, n.lower() in body.lower())
    try:
        hits = page.evaluate(JS)
        print(" HITS", json.dumps(hits[:30], indent=2)[:3000])
    except Exception as e:
        print(" jserr", e)
    shot = Path(r"E:\LIQA\workspace\default-run\reports\xray-ui-import") / f"probe-{label}.png"
    page.screenshot(path=str(shot), full_page=True)
    print(" shot", shot)


def main() -> None:
    with sync_playwright() as p:
        b = p.chromium.connect_over_cdp(os.environ["LIQA_CHROME_CDP"])
        page = b.contexts[0].pages[0] if b.contexts[0].pages else b.contexts[0].new_page()
        page.goto(
            "https://lolcgroupdev.atlassian.net/browse/PF-59194",
            wait_until="domcontentloaded",
            timeout=90000,
        )
        dump(page, "GOLD")
        page.goto(
            "https://lolcgroupdev.atlassian.net/browse/PF-59477",
            wait_until="domcontentloaded",
            timeout=90000,
        )
        dump(page, "TARGET")


if __name__ == "__main__":
    main()

#!/usr/bin/env python3
"""Upload Manual steps via Xray internal API using CDP browser cookies (no Xray API keys)."""
from __future__ import annotations

import csv
import json
import os
import sys
from pathlib import Path

import requests
from playwright.sync_api import sync_playwright

ROOT = Path(__file__).resolve().parents[1]
sys.path.insert(0, str(ROOT / "mcp"))
os.environ.setdefault("LIQA_CHROME_CDP", "http://127.0.0.1:9333")

XRAY = "https://us.xray.cloud.getxray.app"
JIRA = "https://lolcgroupdev.atlassian.net"
PROJECT_ID = "10115"


def load_steps(csv_path: Path) -> list[dict]:
    steps = []
    with csv_path.open(encoding="utf-8-sig", newline="") as f:
        for row in csv.DictReader(f):
            action = (row.get("Action") or "").strip()
            data = (row.get("Data") or "").strip()
            expected = (row.get("Expected Result") or row.get("Result") or "").strip()
            if action and expected:
                steps.append({"action": action, "data": data, "result": expected})
    return steps


def cookies_from_cdp() -> dict[str, str]:
    with sync_playwright() as p:
        b = p.chromium.connect_over_cdp(os.environ["LIQA_CHROME_CDP"])
        ctx = b.contexts[0]
        jar = {}
        for c in ctx.cookies():
            jar[c["name"]] = c["value"]
        return jar


def session_from_cookies(jar: dict[str, str]) -> requests.Session:
    s = requests.Session()
    for name, value in jar.items():
        # set for both hosts
        s.cookies.set(name, value, domain=".atlassian.net")
        s.cookies.set(name, value, domain=".getxray.app")
        s.cookies.set(name, value, domain="us.xray.cloud.getxray.app")
    s.headers.update(
        {
            "User-Agent": "Mozilla/5.0 LIQA-Xray-RPA",
            "Accept": "application/json, text/plain, */*",
            "Origin": JIRA,
            "Referer": f"{JIRA}/",
        }
    )
    return s


def get_issue_ids(issue_key: str) -> tuple[str, str]:
    # browse page already known mapping from prior probes for PF-59477=226837
    # Prefer REST via Atlassian if possible; else map from CDP page
    with sync_playwright() as p:
        b = p.chromium.connect_over_cdp(os.environ["LIQA_CHROME_CDP"])
        page = b.contexts[0].pages[0]
        page.goto(f"{JIRA}/browse/{issue_key}", wait_until="domcontentloaded", timeout=90000)
        page.wait_for_timeout(4000)
        # meta issue-id
        issue_id = page.evaluate(
            """() => {
              const m = document.querySelector('meta[name=\"ajs-issue-key\"]');
              const id = document.querySelector('meta[name=\"ajs-issue-id\"]');
              return (id && id.content) || (window.JIRA && JIRA.Issue && JIRA.Issue.getIssueId && JIRA.Issue.getIssueId()) || null;
            }"""
        )
        if not issue_id:
            # fallback from URL network: parse from xray iframe
            for fr in page.frames:
                u = fr.url or ""
                if "issueId=" in u:
                    import re

                    m = re.search(r"issueId=(\d+)", u)
                    if m:
                        issue_id = m.group(1)
                        break
        if not issue_id:
            raise RuntimeError(f"could not resolve issueId for {issue_key}")
        return issue_key, str(issue_id)


def fetch_versions(s: requests.Session, issue_id: str) -> dict:
    r = s.post(f"{XRAY}/api/internal/tests/versions", json={"issueIds": [int(issue_id)]}, timeout=60)
    return {"status": r.status_code, "text": r.text[:500], "json": _safe_json(r)}


def fetch_steps(s: requests.Session, issue_id: str, version_id: str) -> dict:
    r = s.get(
        f"{XRAY}/api/internal/test/{issue_id}/steps",
        params={"testVersionId": version_id, "startAt": 0, "maxResults": 200},
        timeout=60,
    )
    return {"status": r.status_code, "json": _safe_json(r), "text": r.text[:300]}


def _safe_json(r):
    try:
        return r.json()
    except Exception:
        return None


def try_put_steps(s: requests.Session, issue_id: str, version_id: str, steps: list[dict]) -> dict:
    payloads = [
        ("PUT", f"{XRAY}/api/internal/test/{issue_id}/steps", {"testVersionId": version_id, "steps": steps}),
        ("POST", f"{XRAY}/api/internal/test/{issue_id}/steps", {"testVersionId": version_id, "steps": steps}),
        (
            "PUT",
            f"{XRAY}/api/internal/test/{issue_id}/steps?testVersionId={version_id}",
            {"steps": steps},
        ),
        (
            "POST",
            f"{XRAY}/api/internal/test/{issue_id}/import/steps",
            {"testVersionId": version_id, "steps": steps},
        ),
    ]
    results = []
    for method, url, body in payloads:
        try:
            r = s.request(method, url, json=body, timeout=60)
            results.append({"method": method, "url": url, "status": r.status_code, "text": r.text[:400]})
            if r.status_code in (200, 201, 204):
                return {"ok": True, "method": method, "url": url, "status": r.status_code, "tries": results}
        except Exception as e:
            results.append({"method": method, "url": url, "error": str(e)})
    return {"ok": False, "tries": results}


