from __future__ import annotations

import json
import os
import time
from pathlib import Path

from playwright.sync_api import sync_playwright

os.environ.setdefault("LIQA_CHROME_CDP", "http://127.0.0.1:9333")
ROOT = Path(r"E:\LIQA\workspace\default-run\NewTestCases\PF-58380\sigiri-manual")
OUT = Path(r"E:\LIQA\workspace\default-run\reports\xray-ui-import")


def open_from_csv(aio, page) -> bool:
    body = aio.locator("body").inner_text(timeout=5000) or ""
    # Empty state: visible Import button
    if "There are no steps defined" in body or "Create or import test steps" in body:
        try:
            aio.get_by_role("button", name="Import").first.click(timeout=4000)
        except Exception:
            aio.get_by_text("Import", exact=True).first.click(timeout=4000)
        time.sleep(0.7)
    else:
        # Filled state: icon right of Add Step
        add = aio.get_by_role("button", name="Add Step")
        box = add.bounding_box()
        if not box:
            return False
        icons = aio.locator("button")
        opened = False
        for i in range(icons.count()):
            bb = icons.nth(i).bounding_box()
            if not bb:
                continue
            if abs(bb["y"] - box["y"]) < 10 and bb["x"] > box["x"] + 8 and bb["width"] <= 50:
                icons.nth(i).click()
                opened = True
                time.sleep(0.7)
                break
        if not opened:
            # fallback visible Import
            try:
                aio.get_by_text("Import", exact=True).first.click(timeout=3000)
            except Exception:
                return False
    for lab in ("From CSV", "From csv", "CSV", "Import from CSV"):
        for root in (aio, page):
            try:
                root.get_by_text(lab, exact=False).first.click(timeout=2500)
                return True
            except Exception:
                continue
    return False


def set_csv_and_confirm(page, csv_path: Path) -> bool:
    time.sleep(1.0)
    for f in page.frames:
        try:
            n = f.locator("input[type=file]").count()
        except Exception:
            continue
        if n <= 0:
            continue
        try:
            f.locator("input[type=file]").last.set_input_files(str(csv_path))
            time.sleep(1)
            for lab in ("Import", "Upload", "Confirm", "OK", "Done", "Submit"):
                try:
                    f.get_by_role("button", name=lab).first.click(timeout=2000)
                    return True
                except Exception:
                    try:
                        f.get_by_text(lab, exact=True).first.click(timeout=1500)
                        return True
                    except Exception:
                        continue
            return True  # file set even if no confirm
        except Exception:
            continue
    return False


def upload_one(issue_key: str, csv_path: Path) -> dict:
    with sync_playwright() as p:
        b = p.chromium.connect_over_cdp(os.environ["LIQA_CHROME_CDP"])
        page = b.contexts[0].pages[0]
        page.goto(
            f"https://lolcgroupdev.atlassian.net/browse/{issue_key}",
            wait_until="domcontentloaded",
            timeout=90000,
        )
        time.sleep(5)
        for _ in range(12):
            page.mouse.wheel(0, 1400)
            time.sleep(0.1)
        try:
            page.get_by_text("Test details", exact=False).first.click(timeout=4000)
        except Exception:
            pass
        time.sleep(3)
        aio = None
        for _ in range(25):
            aio = next((f for f in page.frames if "all-in-one" in (f.url or "")), None)
            if aio:
                break
            page.mouse.wheel(0, 700)
            time.sleep(0.4)
        if not aio:
            return {"ok": False, "error": "no aio", "issue": issue_key}
        try:
            aio.get_by_text("Dismiss", exact=True).first.click(timeout=1200)
        except Exception:
            pass
        if not open_from_csv(aio, page):
            snip = (aio.locator("body").inner_text() or "")[-700:]
            return {"ok": False, "error": "From CSV missing", "snip": snip, "issue": issue_key}
        if not set_csv_and_confirm(page, csv_path):
            return {"ok": False, "error": "file input missing", "issue": issue_key}
        time.sleep(3.5)
        body = aio.locator("body").inner_text(timeout=8000) or ""
        ok = ("Expected Result" in body) and ("Action" in body) and ("There are no steps defined" not in body)
        page.screenshot(path=str(OUT / f"{issue_key}-fromcsv.png"), full_page=True)
        return {"ok": ok, "issue": issue_key, "snip": body[:400]}


def main() -> int:
    mapping = [
        ("P00", "PF-59476", ROOT / "P00" / "P00-owner-exact-120.csv"),
        ("P02", "PF-59478", ROOT / "P02" / "P02-steps.csv"),
        ("P03", "PF-59479", ROOT / "P03" / "P03-steps.csv"),
        ("P04", "PF-59481", ROOT / "P04" / "P04-steps.csv"),
        ("P05", "PF-59480", ROOT / "P05" / "P05-steps.csv"),
    ]
    if not mapping[0][2].exists():
        mapping[0] = ("P00", "PF-59476", ROOT / "P00" / "P00-steps.csv")
    results = []
    for pack, key, csv_path in mapping:
        r = upload_one(key, csv_path)
        r["pack"] = pack
        results.append(r)
        print(json.dumps({k: r.get(k) for k in ("ok", "pack", "issue", "error")}))
    print(json.dumps({"ok": all(r.get("ok") for r in results), "results": [
        {k: r.get(k) for k in ("ok", "pack", "issue", "error")} for r in results
    ]}, indent=2))
    return 0 if all(r.get("ok") for r in results) else 1


if __name__ == "__main__":
    raise SystemExit(main())

