#!/usr/bin/env python3
import os
import re
import time
from pathlib import Path
from playwright.sync_api import sync_playwright

CSV = Path(r"E:\LIQA\workspace\default-run\NewTestCases\PF-58380\sigiri-manual\P02\P02-steps.csv")


def main() -> int:
    with sync_playwright() as p:
        b = p.chromium.connect_over_cdp("http://127.0.0.1:9333")
        page = b.contexts[0].pages[0]
        page.goto("https://lolcgroupdev.atlassian.net/browse/PF-59478", wait_until="domcontentloaded", timeout=90000)
        time.sleep(5)
        for _ in range(12):
            page.mouse.wheel(0, 1400)
            time.sleep(0.1)
        page.get_by_text("Test details", exact=False).first.click(timeout=4000)
        time.sleep(4)
        aio = next(f for f in page.frames if "all-in-one" in (f.url or ""))
        aio.get_by_role("button", name="Import").first.click(timeout=4000)
        time.sleep(1)
        # dump any text containing csv on page + frames
        for fr in [page.main_frame, *page.frames]:
            try:
                t = fr.locator("body").inner_text(timeout=2000) or ""
            except Exception:
                continue
            if re.search(r"csv", t, re.I):
                for line in t.splitlines():
                    if re.search(r"csv|clipboard|json|from test", line, re.I):
                        print("LINE", repr(line), "frame", (fr.url or "")[:70])
        # click via JS in all docs
        clicked = page.evaluate(
            """() => {
              const walk = (root) => {
                const nodes = root.querySelectorAll('*');
                for (const el of nodes) {
                  const t = (el.textContent||'').trim();
                  if (/^From csv/i.test(t) || /^from csv/i.test(t)) {
                    el.click();
                    return t;
                  }
                  if (el.shadowRoot) {
                    const r = walk(el.shadowRoot);
                    if (r) return r;
                  }
                }
                return null;
              };
              return walk(document);
            }"""
        )
        print("JS click page", clicked)
        if not clicked:
            for fr in page.frames:
                try:
                    clicked = fr.evaluate(
                        """() => {
                          const nodes = document.querySelectorAll('*');
                          for (const el of nodes) {
                            const t = (el.textContent||'').trim();
                            if (/^From csv/i.test(t)) { el.click(); return t; }
                          }
                          return null;
                        }"""
                    )
                except Exception:
                    continue
                if clicked:
                    print("JS click frame", clicked, (fr.url or "")[:80])
                    break
        time.sleep(1.2)
        for f in page.frames:
            try:
                n = f.locator("input[type=file]").count()
            except Exception:
                continue
            if n:
                f.locator("input[type=file]").last.set_input_files(str(CSV))
                print("SET OK", n)
                time.sleep(2.5)
                body = aio.locator("body").inner_text() or ""
                print("SUCCESS", "Expected Result" in body, "no steps" not in body.lower())
                print(body[:500])
                return 0 if "Expected Result" in body else 2
        print("no file input")
        return 1


if __name__ == "__main__":
    raise SystemExit(main())

