#!/usr/bin/env python3
"""Diagnose Xray From-csv flow on one empty Test issue."""
from __future__ import annotations

import json
import time
from pathlib import Path

from playwright.sync_api import sync_playwright

ISSUE = "PF-59478"
CSV = Path(r"E:\LIQA\workspace\default-run\NewTestCases\PF-58380\sigiri-manual\P02\P02-steps.csv")
OUT = Path(r"E:\LIQA\workspace\default-run\reports\xray-ui-import")
OUT.mkdir(parents=True, exist_ok=True)
CDP = "http://127.0.0.1:9333"


def dump_inputs(page, label: str) -> list[dict]:
    rows = []
    for i, f in enumerate(page.frames):
        try:
            n = f.locator("input[type=file]").count()
        except Exception:
            continue
        if n <= 0:
            continue
        for j in range(n):
            el = f.locator("input[type=file]").nth(j)
            try:
                info = el.evaluate(
                    """e => ({
                      id: e.id || '',
                      name: e.name || '',
                      accept: e.accept || '',
                      className: e.className || '',
                      hidden: e.hidden || e.style.display === 'none',
                      aria: e.getAttribute('aria-label') || '',
                      parentText: (e.closest('div')||e.parentElement||e).innerText?.slice(0,120) || '',
                      inDialog: !!e.closest('[role=dialog], .aui-dialog, .xray-dialog, [class*=Modal], [class*=modal]')
                    })"""
                )
            except Exception as ex:
                info = {"error": str(ex)}
            info.update({"frame_i": i, "input_i": j, "frame_url": (f.url or "")[:120]})
            rows.append(info)
    print(f"=== INPUTS after {label}: {len(rows)} ===")
    print(json.dumps(rows, indent=2)[:4000])
    return rows


def main() -> int:
    with sync_playwright() as p:
        b = p.chromium.connect_over_cdp(CDP)
        page = b.contexts[0].pages[0]
        page.goto(
            f"https://lolcgroupdev.atlassian.net/browse/{ISSUE}",
            wait_until="domcontentloaded",
            timeout=90000,
        )
        time.sleep(5)
        for _ in range(12):
            page.mouse.wheel(0, 1400)
            time.sleep(0.1)
        try:
            page.get_by_text("Test details", exact=False).first.click(timeout=4000)
        except Exception:
            pass
        time.sleep(4)
        aio = next((f for f in page.frames if "all-in-one" in (f.url or "")), None)
        if not aio:
            print("NO AIO")
            return 1
        try:
            aio.get_by_text("Dismiss", exact=True).first.click(timeout=1000)
        except Exception:
            pass
        body = aio.locator("body").inner_text() or ""
        print("EMPTY?", "There are no steps defined" in body)
        print("HAS EXPECTED?", "Expected Result" in body)
        dump_inputs(page, "before-import")

        # Click Import (empty state)
        aio.get_by_role("button", name="Import").first.click(timeout=5000)
        time.sleep(0.8)
        page.screenshot(path=str(OUT / f"{ISSUE}-diag-menu.png"), full_page=True)
        menu_text = aio.evaluate(
            """() => {
              const texts = [];
              for (const el of document.querySelectorAll('*')) {
                const own = Array.from(el.childNodes)
                  .filter(n => n.nodeType === 3)
                  .map(n => (n.textContent||'').trim())
                  .filter(Boolean)
                  .join(' ');
                if (/^From /i.test(own)) texts.push({own, tag: el.tagName, cls: el.className});
              }
              return texts;
            }"""
        )
        print("MENU ITEMS:", json.dumps(menu_text, indent=2))
        dump_inputs(page, "after-import-menu")

        # Click leaf From csv...
        hit = aio.evaluate(
            """() => {
              for (const el of document.querySelectorAll('*')) {
                const own = Array.from(el.childNodes)
                  .filter(n => n.nodeType === 3)
                  .map(n => (n.textContent||'').trim())
                  .filter(Boolean)
                  .join(' ');
                if (/^From csv/i.test(own)) {
                  el.click();
                  return {own, tag: el.tagName, cls: String(el.className).slice(0,80)};
                }
              }
              return null;
            }"""
        )
        print("HIT:", hit)
        time.sleep(1.5)
        page.screenshot(path=str(OUT / f"{ISSUE}-diag-after-fromcsv.png"), full_page=True)
        dump_inputs(page, "after-from-csv")

        # Also check dialogs / overlays on aio
        dialogs = aio.evaluate(
            """() => {
              const sels = ['[role=dialog]', '.aui-dialog2', '[class*=Modal]', '[class*=modal]', '[class*=Dialog]', 'form'];
              const out = [];
              for (const s of sels) {
                document.querySelectorAll(s).forEach((el, i) => {
                  out.push({sel: s, i, text: (el.innerText||'').slice(0,200), html: el.outerHTML.slice(0,300)});
                });
              }
              return out.slice(0, 20);
            }"""
        )
        print("DIALOGS:", json.dumps(dialogs, indent=2)[:5000])

        # Try expect_file_chooser with click again
        try:
            aio.get_by_role("button", name="Import").first.click(timeout=3000)
            time.sleep(0.5)
        except Exception as e:
            print("reopen import fail", e)

        try:
            with page.expect_file_chooser(timeout=5000) as fc_info:
                aio.evaluate(
                    """() => {
                      for (const el of document.querySelectorAll('*')) {
                        const own = Array.from(el.childNodes)
                          .filter(n => n.nodeType === 3)
                          .map(n => (n.textContent||'').trim())
                          .filter(Boolean)
                          .join(' ');
                        if (/^From csv/i.test(own)) { el.click(); return true; }
                      }
                      return false;
                    }"""
                )
            chooser = fc_info.value
            print("FILECHOOSER OK", chooser)
            chooser.set_files(str(CSV))
            time.sleep(2)
            for lab in ("Import", "Upload", "Confirm", "OK", "Done", "Next"):
                try:
                    aio.get_by_role("button", name=lab).first.click(timeout=1200)
                    print("clicked", lab)
                    break
                except Exception:
                    pass
            # also try page-level buttons
            for lab in ("Import", "Upload", "Confirm", "OK", "Done"):
                try:
                    page.get_by_role("button", name=lab).last.click(timeout=1200)
                    print("page clicked", lab)
                except Exception:
                    pass
            time.sleep(3)
        except Exception as e:
            print("FILECHOOSER FAIL:", type(e).__name__, e)

        body2 = aio.locator("body").inner_text() or ""
        print("AFTER RESULT empty?", "There are no steps defined" in body2)
        print("AFTER Expected?", "Expected Result" in body2)
        print("SNIP:", body2[:500])
        page.screenshot(path=str(OUT / f"{ISSUE}-diag-final.png"), full_page=True)
        return 0


if __name__ == "__main__":
    raise SystemExit(main())

#!/usr/bin/env python3
"""Upload one CSV into Xray Manual steps via #xray-csv-file dialog iframe."""
from __future__ import annotations

import json
import time
from pathlib import Path

from playwright.sync_api import sync_playwright

CDP = "http://127.0.0.1:9333"
OUT = Path(r"E:\LIQA\workspace\default-run\reports\xray-ui-import")
OUT.mkdir(parents=True, exist_ok=True)

CLICK_FROM_CSV = """() => {
  for (const el of document.querySelectorAll('*')) {
    const own = Array.from(el.childNodes)
      .filter(n => n.nodeType === 3)
      .map(n => (n.textContent || '').trim())
      .filter(Boolean)
      .join(' ');
    if (/^From csv/i.test(own)) {
      el.click();
      return {own, tag: el.tagName};
    }
  }
  return null;
}"""


def find_import_frame(page):
    for f in page.frames:
        u = f.url or ""
        if "manual-steps-import" in u:
            return f
    return None


def open_aio(page, issue: str):
    page.goto(
        f"https://lolcgroupdev.atlassian.net/browse/{issue}",
        wait_until="domcontentloaded",
        timeout=90000,
    )
    time.sleep(5)
    for _ in range(12):
        page.mouse.wheel(0, 1400)
        time.sleep(0.1)
    try:
        page.get_by_text("Test details", exact=False).first.click(timeout=4000)
    except Exception:
        pass
    time.sleep(4)
    aio = next((f for f in page.frames if "all-in-one" in (f.url or "")), None)
    if aio:
        try:
            aio.get_by_text("Dismiss", exact=True).first.click(timeout=1000)
        except Exception:
            pass
    return aio


def open_from_csv_menu(aio, page) -> dict:
    body = aio.locator("body").inner_text(timeout=5000) or ""
    if "There are no steps defined" in body or "Create or import test steps" in body:
        aio.get_by_role("button", name="Import").first.click(timeout=5000)
    else:
        add = aio.get_by_role("button", name="Add Step")
        box = add.bounding_box()
        opened = False
        for i in range(aio.locator("button").count()):
            bb = aio.locator("button").nth(i).bounding_box()
            if bb and box and abs(bb["y"] - box["y"]) < 10 and bb["x"] > box["x"] + 8 and bb["width"] <= 50:
                aio.locator("button").nth(i).click()
                opened = True
                break
        if not opened:
            aio.get_by_text("Import", exact=True).first.click(timeout=3000)
    time.sleep(0.7)
    hit = aio.evaluate(CLICK_FROM_CSV)
    return {"hit": hit, "was_empty": "There are no steps defined" in body}


def upload_one(page, issue: str, csv_path: Path) -> dict:
    aio = open_aio(page, issue)
    if not aio:
        return {"ok": False, "issue": issue, "error": "no aio"}
    body0 = aio.locator("body").inner_text() or ""
    if "Expected Result" in body0 and "There are no steps defined" not in body0:
        return {"ok": True, "issue": issue, "skipped": True, "reason": "already has steps"}

    menu = open_from_csv_menu(aio, page)
    if not menu.get("hit"):
        return {"ok": False, "issue": issue, "error": "From csv leaf not clicked", "menu": menu}

    # Wait for import dialog iframe
    imp = None
    for _ in range(30):
        imp = find_import_frame(page)
        if imp:
            break
        time.sleep(0.25)
    if not imp:
        return {"ok": False, "issue": issue, "error": "manual-steps-import iframe missing", "menu": menu}

    # Set the dedicated Xray CSV input
    file_input = imp.locator("#xray-csv-file, input[name=csvFile], input[type=file][accept*='csv']").first
    try:
        file_input.wait_for(state="attached", timeout=8000)
        file_input.set_input_files(str(csv_path))
    except Exception as e:
        return {"ok": False, "issue": issue, "error": f"set csv failed: {e}", "imp_url": (imp.url or "")[:160]}

    time.sleep(1.2)
    # Dump buttons in import frame for debugging if needed
    try:
        btns = imp.evaluate(
            """() => Array.from(document.querySelectorAll('button, input[type=submit], a.aui-button'))
              .map(b => ({tag: b.tagName, text: (b.innerText||b.value||'').trim().slice(0,60), id: b.id||'', cls: String(b.className).slice(0,60)}))
              .filter(b => b.text)"""
        )
    except Exception:
        btns = []

    clicked = None
    for lab in ("Import", "Upload", "Next", "Confirm", "OK", "Done", "Submit"):
        try:
            imp.get_by_role("button", name=lab).first.click(timeout=2000)
            clicked = lab
            break
        except Exception:
            try:
                imp.get_by_text(lab, exact=True).first.click(timeout=1500)
                clicked = lab
                break
            except Exception:
                continue
    # Also try parent page dialog footer buttons
    if not clicked:
        for lab in ("Import", "Upload", "Next", "Confirm", "OK", "Done"):
            try:
                page.get_by_role("button", name=lab).last.click(timeout=1500)
                clicked = f"page:{lab}"
                break
            except Exception:
                continue

    # Wait for dialog to close / steps to appear
    for _ in range(40):
        time.sleep(0.5)
        try:
            body = aio.locator("body").inner_text(timeout=2000) or ""
        except Exception:
            body = ""
        if "Expected Result" in body and "There are no steps defined" not in body:
            page.screenshot(path=str(OUT / f"{issue}-steps-ok.png"), full_page=True)
            return {
                "ok": True,
                "issue": issue,
                "method": "xray-csv-file",
                "clicked": clicked,
                "btns": btns[:12],
                "csv": str(csv_path),
            }
        # maybe mapping wizard needs Next
        if find_import_frame(page):
            try:
                find_import_frame(page).get_by_role("button", name="Next").first.click(timeout=800)
            except Exception:
                pass
            try:
                find_import_frame(page).get_by_role("button", name="Import").first.click(timeout=800)
            except Exception:
                pass

    page.screenshot(path=str(OUT / f"{issue}-steps-fail.png"), full_page=True)
    try:
        body_final = aio.locator("body").inner_text(timeout=2000) or ""
    except Exception:
        body_final = ""
    return {
        "ok": False,
        "issue": issue,
        "error": "steps not visible after import",
        "clicked": clicked,
        "btns": btns[:20],
        "snip": body_final[:400],
        "imp_still": bool(find_import_frame(page)),
    }


def main() -> int:
    mapping = [
        ("PF-59476", Path(r"E:\LIQA\workspace\default-run\NewTestCases\PF-58380\sigiri-manual\P00\P00-owner-exact-120.csv")),
        ("PF-59478", Path(r"E:\LIQA\workspace\default-run\NewTestCases\PF-58380\sigiri-manual\P02\P02-steps.csv")),
        ("PF-59479", Path(r"E:\LIQA\workspace\default-run\NewTestCases\PF-58380\sigiri-manual\P03\P03-steps.csv")),
        ("PF-59481", Path(r"E:\LIQA\workspace\default-run\NewTestCases\PF-58380\sigiri-manual\P04\P04-steps.csv")),
        ("PF-59480", Path(r"E:\LIQA\workspace\default-run\NewTestCases\PF-58380\sigiri-manual\P05\P05-steps.csv")),
    ]
    # fallback if owner-exact missing
    if not mapping[0][1].exists():
        mapping[0] = (
            "PF-59476",
            Path(r"E:\LIQA\workspace\default-run\NewTestCases\PF-58380\sigiri-manual\P00\P00-steps.csv"),
        )

    results = []
    with sync_playwright() as p:
        b = p.chromium.connect_over_cdp(CDP)
        page = b.contexts[0].pages[0]
        for issue, csv_path in mapping:
            if not csv_path.exists():
                results.append({"ok": False, "issue": issue, "error": f"missing {csv_path}"})
                print(json.dumps(results[-1]))
                continue
            r = upload_one(page, issue, csv_path)
            results.append(r)
            print(json.dumps({k: r.get(k) for k in ("ok", "issue", "error", "skipped", "clicked", "method")}))
            # close leftover dialog if any
            try:
                page.keyboard.press("Escape")
            except Exception:
                pass
            time.sleep(1)

    summary = {"all_ok": all(r.get("ok") for r in results), "results": results}
    (OUT / "batch-xray-csv-file.json").write_text(json.dumps(summary, indent=2), encoding="utf-8")
    print(json.dumps({"all_ok": summary["all_ok"]}, indent=2))
    return 0 if summary["all_ok"] else 1


if __name__ == "__main__":
    raise SystemExit(main())

