#!/usr/bin/env python3
"""Complete Xray Manual CSV import using #xray-csv-file in manual-steps-import iframe."""
from __future__ import annotations

import json
import time
from pathlib import Path

from playwright.sync_api import sync_playwright

CDP = "http://127.0.0.1:9333"
OUT = Path(r"E:\LIQA\workspace\default-run\reports\xray-ui-import")
OUT.mkdir(parents=True, exist_ok=True)

CLICK_FROM_CSV = """() => {
  for (const el of document.querySelectorAll('*')) {
    const own = Array.from(el.childNodes)
      .filter(n => n.nodeType === 3)
      .map(n => (n.textContent || '').trim())
      .filter(Boolean)
      .join(' ');
    if (/^From csv/i.test(own)) {
      el.click();
      return {own, tag: el.tagName};
    }
  }
  return null;
}"""


def dismiss_overlays(page) -> None:
    for _ in range(4):
        try:
            page.keyboard.press("Escape")
        except Exception:
            pass
        time.sleep(0.2)
    for sel in (
        'button[aria-label="Close"]',
        'button[aria-label="Cancel"]',
        ".aui-dialog2-header-close",
    ):
        try:
            page.locator(sel).first.click(timeout=800)
        except Exception:
            pass


def find_import_frame(page):
    for f in page.frames:
        if "manual-steps-import" in (f.url or ""):
            return f
    return None


def open_aio(page, issue: str):
    dismiss_overlays(page)
    page.goto(
        f"https://lolcgroupdev.atlassian.net/browse/{issue}",
        wait_until="domcontentloaded",
        timeout=90000,
    )
    time.sleep(5)
    dismiss_overlays(page)
    for _ in range(14):
        page.mouse.wheel(0, 1400)
        time.sleep(0.08)
    try:
        page.get_by_text("Test details", exact=False).first.click(timeout=4000)
    except Exception:
        pass
    time.sleep(4)
    aio = next((f for f in page.frames if "all-in-one" in (f.url or "")), None)
    if aio:
        try:
            aio.get_by_text("Dismiss", exact=True).first.click(timeout=1000)
        except Exception:
            pass
    return aio


def upload_one(page, issue: str, csv_path: Path) -> dict:
    aio = open_aio(page, issue)
    if not aio:
        return {"ok": False, "issue": issue, "error": "no aio"}

    body0 = aio.locator("body").inner_text(timeout=5000) or ""
    if "Expected Result" in body0 and "There are no steps defined" not in body0:
        return {"ok": True, "issue": issue, "skipped": True, "reason": "already has steps"}

    # Open Import menu (empty-state button)
    try:
        aio.get_by_role("button", name="Import").first.click(timeout=5000)
    except Exception:
        try:
            aio.get_by_text("Import", exact=True).first.click(timeout=4000)
        except Exception as e:
            return {"ok": False, "issue": issue, "error": f"Import click: {e}"}
    time.sleep(0.8)

    hit = aio.evaluate(CLICK_FROM_CSV)
    if not hit:
        return {"ok": False, "issue": issue, "error": "From csv leaf not clicked"}

    imp = None
    for _ in range(40):
        imp = find_import_frame(page)
        if imp:
            break
        time.sleep(0.25)
    if not imp:
        return {"ok": False, "issue": issue, "error": "manual-steps-import iframe missing"}

    # Snapshot dialog UI before file set
    try:
        dlg_text = imp.locator("body").inner_text(timeout=3000) or ""
    except Exception:
        dlg_text = ""

    file_input = imp.locator("#xray-csv-file")
    if file_input.count() == 0:
        file_input = imp.locator("input[name=csvFile]")
    if file_input.count() == 0:
        file_input = imp.locator("input[type=file]")
    try:
        file_input.first.set_input_files(str(csv_path))
    except Exception as e:
        return {
            "ok": False,
            "issue": issue,
            "error": f"set_input_files: {e}",
            "dlg": dlg_text[:300],
        }

    time.sleep(1.5)
    try:
        btns = imp.evaluate(
            """() => Array.from(document.querySelectorAll('button, input[type=button], input[type=submit], a'))
              .map(b => ({text: (b.innerText||b.value||'').trim().slice(0,80), id: b.id||'', disabled: !!b.disabled}))
              .filter(b => b.text)"""
        )
    except Exception:
        btns = []

    # Prefer primary Import in dialog body
    clicked = None
    for lab in ("Import", "Next", "Upload", "Confirm", "OK", "Done", "Submit", "Save"):
        try:
            btn = imp.get_by_role("button", name=lab)
            if btn.count():
                btn.first.click(timeout=2500)
                clicked = lab
                break
        except Exception:
            continue
    if not clicked:
        # parent dialog chrome (outside iframe)
        for lab in ("Import", "Next", "Upload", "Confirm", "OK", "Done"):
            try:
                page.locator("section[role=dialog]").get_by_role("button", name=lab).last.click(timeout=2000)
                clicked = f"dialog:{lab}"
                break
            except Exception:
                continue

    # Wizard loop
    for _ in range(50):
        time.sleep(0.4)
        try:
            body = aio.locator("body").inner_text(timeout=2000) or ""
        except Exception:
            body = ""
        if "Expected Result" in body and "There are no steps defined" not in body:
            page.screenshot(path=str(OUT / f"{issue}-ok.png"), full_page=True)
            return {
                "ok": True,
                "issue": issue,
                "method": "xray-csv-file",
                "clicked": clicked,
                "btns": btns[:15],
            }

        cur = find_import_frame(page)
        if not cur:
            continue
        for lab in ("Next", "Import", "Finish", "Confirm", "OK"):
            try:
                b = cur.get_by_role("button", name=lab)
                if b.count() and b.first.is_enabled():
                    b.first.click(timeout=800)
                    clicked = f"{clicked}+{lab}" if clicked else lab
                    break
            except Exception:
                continue
        try:
            page.locator("section[role=dialog]").get_by_role("button", name="Import").last.click(timeout=600)
        except Exception:
            pass

    page.screenshot(path=str(OUT / f"{issue}-fail.png"), full_page=True)
    try:
        dlg2 = ""
        cur = find_import_frame(page)
        if cur:
            dlg2 = cur.locator("body").inner_text(timeout=2000) or ""
    except Exception:
        dlg2 = ""
    try:
        snip = aio.locator("body").inner_text(timeout=2000) or ""
    except Exception:
        snip = ""
    return {
        "ok": False,
        "issue": issue,
        "error": "steps not visible after import",
        "clicked": clicked,
        "btns": btns[:20],
        "dlg_before": dlg_text[:400],
        "dlg_after": dlg2[:500],
        "snip": snip[:400],
        "imp_still": bool(find_import_frame(page)),
    }


def main() -> int:
    mapping = [
        ("PF-59476", Path(r"E:\LIQA\workspace\default-run\NewTestCases\PF-58380\sigiri-manual\P00\P00-owner-exact-120.csv")),
        ("PF-59478", Path(r"E:\LIQA\workspace\default-run\NewTestCases\PF-58380\sigiri-manual\P02\P02-steps.csv")),
        ("PF-59479", Path(r"E:\LIQA\workspace\default-run\NewTestCases\PF-58380\sigiri-manual\P03\P03-steps.csv")),
        ("PF-59481", Path(r"E:\LIQA\workspace\default-run\NewTestCases\PF-58380\sigiri-manual\P04\P04-steps.csv")),
        ("PF-59480", Path(r"E:\LIQA\workspace\default-run\NewTestCases\PF-58380\sigiri-manual\P05\P05-steps.csv")),
    ]
    if not mapping[0][1].exists():
        mapping[0] = (
            "PF-59476",
            Path(r"E:\LIQA\workspace\default-run\NewTestCases\PF-58380\sigiri-manual\P00\P00-steps.csv"),
        )

    results = []
    with sync_playwright() as p:
        b = p.chromium.connect_over_cdp(CDP)
        page = b.contexts[0].pages[0]
        for issue, csv_path in mapping:
            r = upload_one(page, issue, csv_path)
            results.append(r)
            print(
                json.dumps(
                    {
                        k: r.get(k)
                        for k in ("ok", "issue", "error", "skipped", "clicked", "method")
                    }
                )
            )
            if not r.get("ok") and r.get("btns") is not None:
                print("  btns:", json.dumps(r.get("btns"))[:500])
                print("  dlg:", (r.get("dlg_after") or r.get("dlg_before") or "")[:300])
            dismiss_overlays(page)
            time.sleep(1.0)

    (OUT / "batch-xray-csv-file.json").write_text(
        json.dumps({"all_ok": all(x.get("ok") for x in results), "results": results}, indent=2),
        encoding="utf-8",
    )
    print(json.dumps({"all_ok": all(x.get("ok") for x in results)}, indent=2))
    return 0 if all(x.get("ok") for x in results) else 1


if __name__ == "__main__":
    raise SystemExit(main())

