    except Exception:
        return False
    return ("Expected Result" in body) and ("There are no steps defined" not in body)


def upload_one(page, issue: str, csv_path: Path) -> dict:
    aio = open_issue(page, issue)
    if not aio:
        return {"ok": False, "issue": issue, "error": "all-in-one not loaded"}
    if has_steps(aio):
        return {"ok": True, "issue": issue, "skipped": True, "reason": "already has steps"}

    try:
        aio.get_by_role("button", name="Import").first.click(timeout=6000)
    except Exception as e:
        return {"ok": False, "issue": issue, "error": f"Import button: {e}"}
    time.sleep(0.9)
    hit = aio.evaluate(CLICK_FROM_CSV)
    if not hit:
        return {"ok": False, "issue": issue, "error": "From csv menuitem not clicked"}

    # Wait for dialog iframe element first (more reliable than frames list)
    try:
        page.wait_for_selector(
            "section[role=dialog] iframe[src*='manual-steps-import'], "
            "iframe[src*='manual-steps-import']",
            timeout=25000,
        )
    except Exception as e:
        return {
            "ok": False,
            "issue": issue,
            "error": f"dialog iframe selector: {e}",
            "hit": hit,
        }
    time.sleep(1.5)
    imp = wait_import_frame(page, timeout_s=25)
    if not imp:
        return {"ok": False, "issue": issue, "error": "Playwright frame missing after iframe src"}

    # Wait for #xray-csv-file
    file_ok = False
    for _ in range(40):
        try:
            if imp.locator("#xray-csv-file").count() > 0:
                file_ok = True
                break
        except Exception:
            # frame may briefly detach while loading
            imp = wait_import_frame(page, timeout_s=5) or imp
        time.sleep(0.35)
    if not file_ok:
        try:
            snip = imp.locator("body").inner_text(timeout=3000) or ""
        except Exception:
            snip = ""
        return {
            "ok": False,
            "issue": issue,
            "error": "#xray-csv-file missing",
            "dlg": snip[:400],
        }

    try:
        dlg_before = imp.locator("body").inner_text(timeout=3000) or ""
    except Exception:
        dlg_before = ""

    imp.locator("#xray-csv-file").first.set_input_files(str(csv_path))
    time.sleep(1.5)

    try:
        btns = imp.evaluate(
            """() => Array.from(document.querySelectorAll('button, input[type=submit], a.aui-button'))
              .map(b => ({t:(b.innerText||b.value||'').trim(), d:!!b.disabled}))
              .filter(b => b.t)"""
        )
    except Exception:
        btns = []

    clicked = []
    for lab in ("Import", "Next", "Upload", "Confirm", "OK", "Done"):
        try:
            btn = imp.get_by_role("button", name=lab)
            if btn.count():
                btn.first.click(timeout=2500)
                clicked.append(lab)
                break
        except Exception:
            continue
    # parent dialog chrome
    for lab in ("Import", "Next", "Confirm", "OK"):
        try:
            page.locator("section[role=dialog]").get_by_role("button", name=lab).last.click(
                timeout=1200
            )
            clicked.append(f"chrome:{lab}")
        except Exception:
            pass

    for _ in range(60):
        time.sleep(0.45)
        # refresh aio handle
        aio2 = wait_aio(page, timeout_s=2) or aio
        if has_steps(aio2):
            page.screenshot(path=str(OUT / f"{issue}-ok.png"), full_page=True)
            return {
                "ok": True,
                "issue": issue,
                "method": "xray-csv-file",
                "clicked": clicked,
                "btns": btns[:15],
            }
        cur = wait_import_frame(page, timeout_s=1)
        if cur:
            for lab in ("Next", "Import", "Finish", "Confirm"):
                try:
                    b = cur.get_by_role("button", name=lab)
                    if b.count() and b.first.is_enabled():
                        b.first.click(timeout=700)
                        clicked.append(lab)
                        break
                except Exception:
                    continue
            try:
                page.locator("section[role=dialog]").get_by_role(
                    "button", name="Import"
                ).last.click(timeout=500)
            except Exception:
                pass

    page.screenshot(path=str(OUT / f"{issue}-fail.png"), full_page=True)
    try:
        snip = (wait_aio(page, 3) or aio).locator("body").inner_text(timeout=2000) or ""
    except Exception:
        snip = ""
    try:
        cur = wait_import_frame(page, 2)
        dlg_after = cur.locator("body").inner_text(timeout=2000) if cur else ""
    except Exception:
        dlg_after = ""
    return {
        "ok": False,
        "issue": issue,
        "error": "steps not visible after import",
        "clicked": clicked,
        "btns": btns[:20],
        "dlg_before": dlg_before[:400],
        "dlg_after": (dlg_after or "")[:500],
        "snip": snip[:400],
    }


def main() -> int:
    mapping = [
        (
            "PF-59476",
            Path(
                r"E:\LIQA\workspace\default-run\NewTestCases\PF-58380\sigiri-manual\P00\P00-owner-exact-120.csv"
            ),
        ),
        (
            "PF-59478",
            Path(
                r"E:\LIQA\workspace\default-run\NewTestCases\PF-58380\sigiri-manual\P02\P02-steps.csv"
            ),
        ),
        (
            "PF-59479",
            Path(
                r"E:\LIQA\workspace\default-run\NewTestCases\PF-58380\sigiri-manual\P03\P03-steps.csv"
            ),
        ),
        (
            "PF-59481",
            Path(
                r"E:\LIQA\workspace\default-run\NewTestCases\PF-58380\sigiri-manual\P04\P04-steps.csv"
            ),
        ),
        (
            "PF-59480",
            Path(
                r"E:\LIQA\workspace\default-run\NewTestCases\PF-58380\sigiri-manual\P05\P05-steps.csv"
            ),
        ),
    ]
    if not mapping[0][1].exists():
        mapping[0] = (
            "PF-59476",
            Path(
                r"E:\LIQA\workspace\default-run\NewTestCases\PF-58380\sigiri-manual\P00\P00-steps.csv"
            ),
        )

    results = []
    with sync_playwright() as p:
        b = p.chromium.connect_over_cdp(CDP)
        page = b.contexts[0].pages[0]
        for issue, csv_path in mapping:
            r = upload_one(page, issue, csv_path)
            results.append(r)
            print(
                json.dumps(
                    {
                        k: r.get(k)
                        for k in (
                            "ok",
                            "issue",
                            "error",
                            "skipped",
                            "clicked",
                            "method",
                        )
                    }
                )
            )
            if not r.get("ok"):
