        aio.evaluate(CLICK_FROM_CSV)
        page.wait_for_selector("iframe[src*='manual-steps-import']", timeout=25000)
        time.sleep(1.5)
        imp = get_imp()
        end = time.time() + 20
        while time.time() < end:
            try:
                if imp and imp.locator("#xray-csv-file").count():
                    break
            except Exception:
                pass
            imp = get_imp() or imp
            time.sleep(0.3)
        # ensure header checkbox etc
