            # leave defaults
        except Exception:
            pass
        imp.locator("#xray-csv-file").first.set_input_files(str(CSV))
        time.sleep(1)
        imp.get_by_role("button", name="Next").first.click(timeout=5000)
        time.sleep(2)
        imp = get_imp()

    body = imp.locator("body").inner_text(timeout=5000) or ""
    print("BODY\n", body[:1200])

    # dump selects / comboboxes
    info = imp.evaluate(
        """() => {
          const out = {selects: [], comboboxes: [], buttons: [], labels: []};
          document.querySelectorAll('select').forEach((s,i) => {
            out.selects.push({
              i, id: s.id, name: s.name,
              options: Array.from(s.options).map(o => o.text.trim()).slice(0,20),
              value: s.value,
              selectedText: s.options[s.selectedIndex]?.text
            });
          });
          document.querySelectorAll('[role=combobox], [aria-haspopup=listbox]').forEach((el,i) => {
            out.comboboxes.push({
              i, tag: el.tagName, text: (el.innerText||'').trim().slice(0,80),
              aria: el.getAttribute('aria-label')||'', id: el.id||''
            });
          });
          document.querySelectorAll('button').forEach(b => {
            out.buttons.push((b.innerText||'').trim());
          });
          // rows
          const rows = Array.from(document.querySelectorAll('tr, [class*=row], [class*=Row]')).slice(0,20)
            .map(r => (r.innerText||'').trim().slice(0,120));
          out.rows = rows;
          return out;
        }"""
    )
    print(json.dumps(info, indent=2)[:5000])

    # Try mapping via native select if present
    for s in info.get("selects") or []:
        opts = s.get("options") or []
        print("SELECT", s.get("i"), opts)

    # Heuristic: for each row with Action/Data/Expected, open dropdown and pick matching
    mapping_targets = ["Action", "Data", "Expected Result"]
    for target in mapping_targets:
        # find a "Don't map this field" near the target label
        try:
            # click the dropdown that is on the same row as target sample
            row = imp.locator("tr", has_text=re.compile(re.escape(target), re.I)).first
            if row.count() == 0:
                row = imp.get_by_text(target, exact=False).locator("xpath=ancestor::*[self::tr or self::div][1]")
            # open select/combobox in row
            try:
                row.locator("select").first.select_option(label=target)
