                continue
            except Exception as e:
                print("select fail", target, e)
            try:
                row.get_by_text("Don't map this field", exact=False).first.click(timeout=2000)
                time.sleep(0.4)
                # click option in listbox / page
                for root in (imp, page):
                    try:
                        root.get_by_role("option", name=target, exact=True).first.click(timeout=1500)
                        print("mapped option", target)
                        break
                    except Exception:
                        try:
                            root.get_by_text(target, exact=True).last.click(timeout=1500)
                            print("mapped text", target)
                            break
                        except Exception:
                            continue
            except Exception as e:
                print("combo fail", target, e)
        except Exception as e:
            print("row fail", target, e)

    time.sleep(1)
    print("AFTER MAP\n", (imp.locator("body").inner_text(timeout=4000) or "")[:1000])
