    except Exception as e:
        print("Validate fail", e)
    time.sleep(2)
    print("AFTER VALIDATE\n", (imp.locator("body").inner_text(timeout=4000) or "")[:1200])
    btns = imp.evaluate(
        """() => Array.from(document.querySelectorAll('button')).map(b => ({t:(b.innerText||'').trim(), d:!!b.disabled}))"""
    )
    print("BTNS", btns)
    for lab in ("Import", "Finish", "Confirm", "Next", "OK"):
        try:
            b = imp.get_by_role("button", name=lab)
            if b.count() and b.first.is_enabled():
                b.first.click(timeout=2000)
                print("clicked", lab)
                time.sleep(1.5)
        except Exception:
            pass
    print("FINAL DLG\n", (imp.locator("body").inner_text(timeout=3000) or "")[:800])
    aio = next(f for f in page.frames if "all-in-one" in (f.url or ""))
    print("AIO empty?", "There are no steps defined" in (aio.locator("body").inner_text() or ""))
    print("AIO expected?", "Expected Result" in (aio.locator("body").inner_text() or ""))

#!/usr/bin/env python3
"""Map Xray CSV fields and finish import on current/open issue."""
from __future__ import annotations

import json
import re
import time
from pathlib import Path

from playwright.sync_api import sync_playwright

CSV = Path(r"E:\LIQA\workspace\default-run\NewTestCases\PF-58380\sigiri-manual\P02\P02-steps.csv")
OUT = Path(r"E:\LIQA\workspace\default-run\reports\xray-ui-import")
CLICK_FROM_CSV = """() => {
  for (const el of document.querySelectorAll('*')) {
    const own = Array.from(el.childNodes)
      .filter(n => n.nodeType === 3)
      .map(n => (n.textContent || '').trim())
      .filter(Boolean)
      .join(' ');
    if (/^From csv/i.test(own)) {
      (el.closest('[role=menuitem]') || el).click();
      return true;
    }
  }
  return false;
}"""


def wait_frame(page, needle: str, timeout_s: float = 45):
    end = time.time() + timeout_s
    while time.time() < end:
        for f in page.frames:
            if needle in (f.url or ""):
                return f
        time.sleep(0.35)
    return None


def open_to_map_fields(page, issue: str, csv_path: Path):
    for _ in range(3):
        page.keyboard.press("Escape")
        time.sleep(0.15)
    page.goto(
        f"https://lolcgroupdev.atlassian.net/browse/{issue}",
        wait_until="domcontentloaded",
        timeout=120000,
    )
    time.sleep(8)
    for _ in range(20):
        page.mouse.wheel(0, 1100)
        time.sleep(0.12)
    try:
        page.get_by_text("Test details", exact=False).first.click(timeout=5000)
    except Exception:
        pass
    aio = wait_frame(page, "all-in-one", 50)
    if not aio:
        raise RuntimeError("no aio")
    time.sleep(1.5)
    try:
        aio.get_by_text("Dismiss", exact=True).first.click(timeout=800)
    except Exception:
        pass

    # If already has steps, stop
    body = aio.locator("body").inner_text(timeout=5000) or ""
    if "Expected Result" in body and "There are no steps defined" not in body:
        return aio, None, "already"

    aio.get_by_role("button", name="Import").first.click(timeout=8000)
    time.sleep(0.9)
    if not aio.evaluate(CLICK_FROM_CSV):
        raise RuntimeError("from csv miss")
    page.wait_for_selector("iframe[src*='manual-steps-import']", timeout=30000)
    time.sleep(2)
    imp = wait_frame(page, "manual-steps-import", 30)
    if not imp:
        raise RuntimeError("no import frame")
    end = time.time() + 25
    while time.time() < end:
        try:
            if imp.locator("#xray-csv-file").count():
                break
        except Exception:
            imp = wait_frame(page, "manual-steps-import", 5) or imp
        time.sleep(0.3)

    # Prefer Contains Header checked
    try:
        label = imp.get_by_text("Contains Header", exact=False).first
        # click nearby checkbox if unchecked — best effort
        box = label.locator("xpath=ancestor::*[.//input[@type='checkbox']][1]//input[@type='checkbox']")
        if box.count() and not box.first.is_checked():
            box.first.check()
    except Exception:
        pass

    imp.locator("#xray-csv-file").first.set_input_files(str(csv_path))
    time.sleep(1.2)
    imp.get_by_role("button", name="Next").first.click(timeout=8000)
    time.sleep(2.5)
    imp = wait_frame(page, "manual-steps-import", 20) or imp
    return aio, imp, "map"


def map_fields(imp, page) -> list[str]:
    done = []
    info = imp.evaluate(
        """() => {
          const selects = Array.from(document.querySelectorAll('select')).map((s,i) => ({
            i, options: Array.from(s.options).map(o => o.text.trim()),
            selected: s.options[s.selectedIndex]?.text || ''
          }));
          return {selects, html: document.body.innerHTML.slice(0,5000)};
        }"""
    )
    print("SELECTS", json.dumps(info.get("selects"), indent=2)[:2500])

    targets = ["Action", "Data", "Expected Result"]
    # Native <select> path
    for s in info.get("selects") or []:
        opts = s.get("options") or []
        for t in targets:
            if t in opts and t not in done:
                try:
                    imp.locator("select").nth(s["i"]).select_option(label=t)
                    done.append(t)
                    print("select mapped", t, "via", s["i"])
                except Exception as e:
                    print("select err", t, e)

    if len(done) >= 3:
        return done

    # Combobox / custom dropdown path: each row has CSV header text and a "Don't map..." control
    body = imp.locator("body").inner_text(timeout=4000) or ""
    print("MAP BODY\n", body[:900])

    # Find all "Don't map this field" controls and map in order Action, Data, Expected Result
    # based on left-side CSV column order from our file
    dont = imp.get_by_text("Don't map this field", exact=False)
    count = dont.count()
    print("Don't map count", count)
    order = ["Action", "Data", "Expected Result"]
    for i in range(min(count, len(order))):
        target = order[i]
        if target in done:
            continue
        try:
            dont.nth(i).click(timeout=3000)
            time.sleep(0.5)
            picked = False
            for root in (imp, page):
                for role in ("option", "menuitem"):
                    try:
                        root.get_by_role(role, name=target, exact=True).first.click(timeout=1500)
                        picked = True
                        break
                    except Exception:
                        continue
                if picked:
                    break
                try:
                    # listbox popup may be in parent page
                    root.locator(f"text={target}").last.click(timeout=1500)
                    picked = True
                except Exception:
                    pass
                if picked:
                    break
            if picked:
                done.append(target)
                print("combo mapped", target)
            else:
                print("combo miss", target)
            time.sleep(0.4)
            # refresh locator
            dont = imp.get_by_text("Don't map this field", exact=False)
        except Exception as e:
            print("row", i, e)

    # Also try select_option by matching option values containing action/data/result
    if len(done) < 3:
        selects = imp.locator("select")
        for i in range(selects.count()):
            try:
                options = selects.nth(i).evaluate(
                    "s => Array.from(s.options).map(o => ({v:o.value, t:o.text.trim()}))"
                )
            except Exception:
                continue
            for t in targets:
                if t in done:
                    continue
                match = next((o for o in options if o["t"] == t or t.lower() in o["t"].lower()), None)
                if match:
                    try:
                        selects.nth(i).select_option(value=match["v"])
                        done.append(t)
                        print("value mapped", t)
                    except Exception:
                        try:
                            selects.nth(i).select_option(label=match["t"])
                            done.append(t)
                        except Exception as e:
                            print("value fail", t, e)

    return done


def finish_import(imp, page, aio) -> bool:
    for lab in ("Validate", "Next", "Import", "Finish", "Confirm"):
        try:
            b = imp.get_by_role("button", name=lab)
            if b.count() and b.first.is_enabled():
                b.first.click(timeout=3000)
                print("click", lab)
                time.sleep(1.5)
                # refresh
                for f in page.frames:
                    if "manual-steps-import" in (f.url or ""):
                        imp = f
                        break
        except Exception:
            continue

    for _ in range(40):
        time.sleep(0.5)
        aio2 = wait_frame(page, "all-in-one", 2) or aio
        try:
            body = aio2.locator("body").inner_text(timeout=2000) or ""
        except Exception:
            body = ""
        if "Expected Result" in body and "There are no steps defined" not in body:
            return True
        cur = wait_frame(page, "manual-steps-import", 1)
        if cur:
            for lab in ("Validate", "Import", "Finish", "Next", "Confirm"):
                try:
                    b = cur.get_by_role("button", name=lab)
                    if b.count() and b.first.is_enabled():
                        b.first.click(timeout=700)
                        print("retry", lab)
                except Exception:
                    pass
    return False


def main() -> int:
    with sync_playwright() as p:
        b = p.chromium.connect_over_cdp("http://127.0.0.1:9333")
        page = b.contexts[0].pages[0]
        aio, imp, stage = open_to_map_fields(page, "PF-59478", CSV)
        print("stage", stage)
        if stage == "already":
            print("already has steps")
            return 0
        mapped = map_fields(imp, page)
        print("mapped", mapped)
        print("AFTER\n", (imp.locator("body").inner_text(timeout=4000) or "")[:1000])
        ok = finish_import(imp, page, aio)
        page.screenshot(path=str(OUT / ("PF-59478-ok.png" if ok else "PF-59478-mapfail.png")), full_page=True)
        print("ok", ok)
        if not ok:
            cur = wait_frame(page, "manual-steps-import", 2)
            if cur:
                print("dlg", (cur.locator("body").inner_text(timeout=3000) or "")[:1000])
        return 0 if ok else 1


if __name__ == "__main__":
    raise SystemExit(main())

