#!/usr/bin/env python3
"""Open CSV import to Map Fields, dump DOM, map Action/Data/Expected Result, Validate+Import."""
from __future__ import annotations

import json
import time
from pathlib import Path

from playwright.sync_api import sync_playwright

CDP = "http://127.0.0.1:9333"
CSV = Path(r"E:\LIQA\workspace\default-run\NewTestCases\PF-58380\sigiri-manual\P02\P02-steps.csv")
OUT = Path(r"E:\LIQA\workspace\default-run\reports\xray-ui-import")
OUT.mkdir(parents=True, exist_ok=True)

CLICK_FROM_CSV = """() => {
  for (const el of document.querySelectorAll('*')) {
    const own = Array.from(el.childNodes)
      .filter(n => n.nodeType === 3)
      .map(n => (n.textContent || '').trim())
      .filter(Boolean)
      .join(' ');
    if (/^From csv/i.test(own)) {
      (el.closest('[role=menuitem]') || el).click();
      return true;
    }
  }
  return false;
}"""


def wait_frame(page, needle: str, timeout_s: float = 50):
    end = time.time() + timeout_s
    while time.time() < end:
        for f in page.frames:
            if needle in (f.url or ""):
                return f
        time.sleep(0.35)
    return None


def log(msg: str) -> None:
    print(msg.encode("ascii", "replace").decode("ascii"))


def open_map(page, issue: str, csv_path: Path):
    for _ in range(3):
        page.keyboard.press("Escape")
        time.sleep(0.15)
    page.goto(
        f"https://lolcgroupdev.atlassian.net/browse/{issue}",
        wait_until="domcontentloaded",
        timeout=120000,
    )
    time.sleep(8)
    for _ in range(20):
        page.mouse.wheel(0, 1100)
        time.sleep(0.1)
    try:
        page.get_by_text("Test details", exact=False).first.click(timeout=5000)
    except Exception:
        pass
    aio = wait_frame(page, "all-in-one", 50)
    if not aio:
        raise RuntimeError("no aio")
    time.sleep(1.5)
    try:
        aio.get_by_text("Dismiss", exact=True).first.click(timeout=800)
    except Exception:
        pass
    body = aio.locator("body").inner_text(timeout=5000) or ""
    if "Expected Result" in body and "There are no steps defined" not in body:
        return aio, None, True

    aio.get_by_role("button", name="Import").first.click(timeout=8000)
    time.sleep(0.9)
    assert aio.evaluate(CLICK_FROM_CSV)
    page.wait_for_selector("iframe[src*='manual-steps-import']", timeout=30000)
    time.sleep(2)
    imp = wait_frame(page, "manual-steps-import", 30)
    assert imp
    end = time.time() + 25
    while time.time() < end:
        try:
            if imp.locator("#xray-csv-file").count():
                break
        except Exception:
            imp = wait_frame(page, "manual-steps-import", 5) or imp
        time.sleep(0.3)

    # Contains Header checkbox
    try:
        cb = imp.locator("input[type=checkbox]").first
        if cb.count() and not cb.is_checked():
            cb.check()
    except Exception:
        pass

    imp.locator("#xray-csv-file").first.set_input_files(str(csv_path))
    time.sleep(1.2)
    imp.get_by_role("button", name="Next").first.click(timeout=8000)
    time.sleep(2.5)
    imp = wait_frame(page, "manual-steps-import", 20) or imp
    return aio, imp, False


def dump_and_map(imp, page) -> dict:
    body = imp.locator("body").inner_text(timeout=5000) or ""
    (OUT / "map-body.txt").write_text(body, encoding="utf-8")
    info = imp.evaluate(
        """() => {
          const all = Array.from(document.querySelectorAll('*'));
          const interesting = [];
          for (const el of all) {
            const t = (el.innerText || '').trim();
            if (!t) continue;
            if (/Don.?t map this field/.test(t) && t.length < 40) {
              interesting.push({
                kind: 'dont',
                tag: el.tagName,
                role: el.getAttribute('role') || '',
                cls: String(el.className).slice(0, 120),
                t,
                aria: el.getAttribute('aria-label') || '',
                parentCls: String((el.parentElement||{}).className||'').slice(0,80)
              });
            }
          }
          // dropdown triggers near arrows / mapping
          const triggers = Array.from(document.querySelectorAll('button, [role=combobox], [aria-haspopup], .aui-button'))
            .map(el => ({
              tag: el.tagName,
              role: el.getAttribute('role') || '',
              cls: String(el.className).slice(0, 120),
              t: (el.innerText || '').trim().slice(0, 80),
              aria: el.getAttribute('aria-label') || ''
            }))
            .filter(x => x.t || x.aria)
            .slice(0, 60);
          return {interesting: interesting.slice(0, 30), triggers, html: document.body.innerHTML.slice(0, 12000)};
        }"""
    )
    (OUT / "map-dom.json").write_text(
        json.dumps({k: info[k] for k in ("interesting", "triggers")}, indent=2),
        encoding="utf-8",
    )
    (OUT / "map-html-snip.html").write_text(info["html"], encoding="utf-8")

    mapped = []
    # Strategy 1: click each Don't map leaf and choose matching option
    click_dont = """(idx) => {
      const nodes = [];
      for (const el of document.querySelectorAll('*')) {
        const own = Array.from(el.childNodes)
          .filter(n => n.nodeType === 3)
          .map(n => (n.textContent || '').trim())
          .filter(Boolean)
          .join(' ');
        if (/^Don.?t map this field$/i.test(own)) nodes.push(el);
      }
      if (!nodes[idx]) return {ok:false, count: nodes.length};
      const target = nodes[idx].closest('button, [role=combobox], [role=button], a, div[tabindex]') || nodes[idx];
      target.click();
      return {ok:true, count: nodes.length, tag: target.tagName, cls: String(target.className).slice(0,80)};
    }"""

    order = ["Action", "Data", "Expected Result"]
    for i, target in enumerate(order):
        hit = imp.evaluate(click_dont, i)
        log(f"open dropdown {i}: {hit}")
        time.sleep(0.6)
        picked = False
        # options may render in iframe or parent
        for root in (imp, page):
            for exact in (True, False):
                try:
                    root.get_by_role("option", name=target, exact=exact).first.click(timeout=1500)
                    picked = True
                    break
                except Exception:
                    pass
                try:
                    root.get_by_role("menuitem", name=target, exact=exact).first.click(timeout=1200)
                    picked = True
                    break
                except Exception:
                    pass
            if picked:
                break
            # raw text in popup lists
            try:
                root.locator(f"li:text-is('{target}'), div:text-is('{target}'), span:text-is('{target}')").last.click(
                    timeout=1200
                )
                picked = True
            except Exception:
                pass
            if picked:
                break
        if not picked:
            # dump visible popup text
            popup = page.evaluate(
                """() => {
                  const pops = Array.from(document.querySelectorAll('[role=listbox], [role=menu], .aui-dropdown2, [class*=Menu], [class*=menu], [class*=Dropdown]'))
                    .map(el => (el.innerText||'').slice(0,300));
                  return pops.slice(0,10);
                }"""
            )
            popup2 = imp.evaluate(
                """() => {
                  const pops = Array.from(document.querySelectorAll('[role=listbox], [role=menu], .aui-dropdown2, [class*=Menu], [class*=menu], [class*=Dropdown], ul, select'))
                    .map(el => ({t:(el.innerText||'').slice(0,300), tag: el.tagName, role: el.getAttribute('role')||''}));
                  return pops.slice(0,15);
                }"""
            )
            (OUT / f"popup-{i}.json").write_text(
                json.dumps({"page": popup, "imp": popup2}, indent=2), encoding="utf-8"
            )
            log(f"popup dump for {target}")
        else:
            mapped.append(target)
            log(f"mapped {target}")
        time.sleep(0.4)

    after = imp.locator("body").inner_text(timeout=4000) or ""
    (OUT / "map-after.txt").write_text(after, encoding="utf-8")
    return {"mapped": mapped, "body": after}


def finish(imp, page, aio) -> bool:
    for lab in ("Validate", "Import", "Finish", "Next", "Confirm"):
        try:
            b = imp.get_by_role("button", name=lab)
            if b.count() and b.first.is_enabled():
                b.first.click(timeout=3000)
                log(f"click {lab}")
                time.sleep(1.8)
                imp = wait_frame(page, "manual-steps-import", 5) or imp
        except Exception:
            continue
    for _ in range(45):
        time.sleep(0.5)
        aio2 = wait_frame(page, "all-in-one", 2) or aio
        try:
            body = aio2.locator("body").inner_text(timeout=2000) or ""
        except Exception:
            body = ""
        if "Expected Result" in body and "There are no steps defined" not in body:
            return True
        cur = wait_frame(page, "manual-steps-import", 1)
        if cur:
            for lab in ("Validate", "Import", "Finish", "Next", "Confirm"):
                try:
                    b = cur.get_by_role("button", name=lab)
                    if b.count() and b.first.is_enabled():
                        b.first.click(timeout=700)
                        log(f"retry {lab}")
                except Exception:
                    pass
    return False


def main() -> int:
    with sync_playwright() as p:
        b = p.chromium.connect_over_cdp(CDP)
        page = b.contexts[0].pages[0]
        aio, imp, already = open_map(page, "PF-59478", CSV)
        if already:
            log("already has steps")
            return 0
        result = dump_and_map(imp, page)
        log("mapped=" + ",".join(result["mapped"]))
        ok = finish(imp, page, aio)
        page.screenshot(
            path=str(OUT / ("PF-59478-ok.png" if ok else "PF-59478-mapfail.png")),
            full_page=True,
        )
        log("ok=" + str(ok))
        if not ok:
            cur = wait_frame(page, "manual-steps-import", 2)
            if cur:
                (OUT / "map-final.txt").write_text(
                    cur.locator("body").inner_text(timeout=3000) or "", encoding="utf-8"
                )
        return 0 if ok else 1


if __name__ == "__main__":
    raise SystemExit(main())

#!/usr/bin/env python3
"""Proper react-select mapping for Xray CSV import + handle Call Test errors."""
from __future__ import annotations

import json
import time
from pathlib import Path

from playwright.sync_api import sync_playwright

CDP = "http://127.0.0.1:9333"
CSV = Path(r"E:\LIQA\workspace\default-run\NewTestCases\PF-58380\sigiri-manual\P02\P02-steps.csv")
OUT = Path(r"E:\LIQA\workspace\default-run\reports\xray-ui-import")
OUT.mkdir(parents=True, exist_ok=True)

CLICK_FROM_CSV = """() => {
  for (const el of document.querySelectorAll('*')) {
    const own = Array.from(el.childNodes)
      .filter(n => n.nodeType === 3)
      .map(n => (n.textContent || '').trim())
      .filter(Boolean)
      .join(' ');
    if (/^From csv/i.test(own)) {
      (el.closest('[role=menuitem]') || el).click();
      return true;
    }
  }
  return false;
}"""


def wait_frame(page, needle: str, timeout_s: float = 50):
    end = time.time() + timeout_s
    while time.time() < end:
        for f in page.frames:
            if needle in (f.url or ""):
                return f
        time.sleep(0.35)
    return None


def log(msg: str) -> None:
    print(msg.encode("ascii", "replace").decode("ascii"), flush=True)


def open_to_map(page, issue: str, csv_path: Path):
    for _ in range(3):
        page.keyboard.press("Escape")
        time.sleep(0.15)
    page.goto(
        f"https://lolcgroupdev.atlassian.net/browse/{issue}",
        wait_until="domcontentloaded",
        timeout=120000,
    )
    time.sleep(8)
    for _ in range(20):
        page.mouse.wheel(0, 1100)
        time.sleep(0.1)
    try:
        page.get_by_text("Test details", exact=False).first.click(timeout=5000)
    except Exception:
        pass
    aio = wait_frame(page, "all-in-one", 50)
    if not aio:
        raise RuntimeError("no aio")
    time.sleep(1.5)
    try:
        aio.get_by_text("Dismiss", exact=True).first.click(timeout=800)
    except Exception:
        pass
    body = aio.locator("body").inner_text(timeout=5000) or ""
    if "Expected Result" in body and "There are no steps defined" not in body:
        return aio, None, True

    aio.get_by_role("button", name="Import").first.click(timeout=8000)
    time.sleep(0.9)
    assert aio.evaluate(CLICK_FROM_CSV)
    page.wait_for_selector("iframe[src*='manual-steps-import']", timeout=30000)
    time.sleep(2)
    imp = wait_frame(page, "manual-steps-import", 30)
    assert imp
    end = time.time() + 25
    while time.time() < end:
        try:
            if imp.locator("#xray-csv-file").count():
                break
        except Exception:
            imp = wait_frame(page, "manual-steps-import", 5) or imp
        time.sleep(0.3)

    # Dump first-screen options (step type / reset / encoding)
    first = imp.locator("body").inner_text(timeout=4000) or ""
    (OUT / "wizard-step1.txt").write_text(first, encoding="utf-8")
    # try check Contains Header
    try:
        for i in range(imp.locator("input[type=checkbox]").count()):
            lab = imp.locator("input[type=checkbox]").nth(i).evaluate(
                """e => (e.parentElement && e.parentElement.innerText) || e.getAttribute('name') || ''"""
            )
            if "header" in (lab or "").lower() or "Header" in (lab or ""):
                if not imp.locator("input[type=checkbox]").nth(i).is_checked():
                    imp.locator("input[type=checkbox]").nth(i).check()
    except Exception:
        pass

    imp.locator("#xray-csv-file").first.set_input_files(str(csv_path))
    time.sleep(1.2)
    imp.get_by_role("button", name="Next").first.click(timeout=8000)
    time.sleep(2.5)
    return aio, wait_frame(page, "manual-steps-import", 20) or imp, False


def map_react_select(imp, page) -> list[str]:
    """Map the 3 Step Field react-selects in order to Action, Data, Expected Result."""
    mapped = []
    # Find react-select control containers that currently show Don't map
    controls = imp.locator("div.css-17qmjyt-singleValue")
    # fallback: any singleValue
    if controls.count() == 0:
        controls = imp.locator("[class*=singleValue]")
    count = controls.count()
    log(f"singleValue count={count}")
    targets = ["Action", "Data", "Expected Result"]

    # Prefer clicking the control wrapper, not the value text alone
    for i, target in enumerate(targets):
        if i >= count:
            break
        # click parent control
        clicked = imp.evaluate(
            """(idx) => {
              const vals = Array.from(document.querySelectorAll('[class*=singleValue]'));
              if (!vals[idx]) return {ok:false, n: vals.length};
              let el = vals[idx];
              // climb to control
              for (let k=0;k<6;k++) {
                if (!el.parentElement) break;
                el = el.parentElement;
                const cls = String(el.className||'');
                if (cls.includes('control') || el.getAttribute('role')==='combobox' || cls.includes('Select')) break;
              }
              el.click();
              return {ok:true, cls: String(el.className).slice(0,100)};
            }""",
            i,
        )
        log(f"open {i} {clicked}")
        time.sleep(0.5)

        # Options typically appear in a portal - check both frames
        option_texts = []
        for root in (imp, page):
            try:
                opts = root.locator("[class*=option], [id*=option], [role=option]")
                n = opts.count()
                for j in range(n):
                    try:
                        option_texts.append(
                            {
                                "root": "imp" if root is imp else "page",
                                "j": j,
                                "t": (opts.nth(j).inner_text(timeout=500) or "").strip(),
                            }
                        )
                    except Exception:
                        pass
            except Exception:
                pass
        (OUT / f"options-{i}.json").write_text(json.dumps(option_texts, indent=2), encoding="utf-8")
        log(f"options-{i} n={len(option_texts)} sample={[o['t'] for o in option_texts[:12]]}")

        picked = False
        # exact match on role=option inside menu list
        for root in (imp, page):
            try:
                # react-select menu
                menu = root.locator("[class*=MenuList], [class*=menu], [role=listbox]").last
                opt = menu.get_by_text(target, exact=True)
                if opt.count():
                    opt.first.click(timeout=2000)
                    picked = True
                    break
            except Exception:
                pass
            try:
                root.locator(f"[class*=option]:text-is('{target}')").first.click(timeout=1500)
                picked = True
                break
            except Exception:
                pass
        if not picked:
            # keyboard typeahead
            try:
                page.keyboard.type(target, delay=40)
                time.sleep(0.3)
                page.keyboard.press("Enter")
                picked = True
                log(f"typed {target}")
            except Exception as e:
                log(f"type fail {e}")
        if picked:
            mapped.append(target)
        time.sleep(0.4)

    after = imp.locator("body").inner_text(timeout=4000) or ""
    (OUT / "map-after2.txt").write_text(after, encoding="utf-8")
    return mapped


def validate_and_import(imp, page, aio) -> dict:
    try:
        imp.get_by_role("button", name="Validate").first.click(timeout=4000)
        log("Validate")
    except Exception as e:
        log(f"Validate fail {e}")
    time.sleep(2.5)
    imp = wait_frame(page, "manual-steps-import", 10) or imp
    body = ""
    try:
        body = imp.locator("body").inner_text(timeout=4000) or ""
    except Exception:
        pass
    (OUT / "validate-result.txt").write_text(body, encoding="utf-8")
    log("validate snip: " + body[:200].replace("\n", " | "))

    # If Call Test errors, go Back and inspect mapping / first screen for step type
    if "Call Test" in body:
        log("Call Test required — trying Import Steps anyway / Back to remap")
        try:
            btn = imp.get_by_role("button", name="Import Steps")
            if btn.count() and btn.first.is_enabled():
                btn.first.click(timeout=2000)
                log("Import Steps clicked despite errors")
        except Exception:
            pass

    # Keep clicking Import Steps / Import when enabled
    for _ in range(30):
        time.sleep(0.5)
        aio2 = wait_frame(page, "all-in-one", 2) or aio
        try:
            ab = aio2.locator("body").inner_text(timeout=2000) or ""
        except Exception:
            ab = ""
        if "Expected Result" in ab and "There are no steps defined" not in ab:
            return {"ok": True}
        cur = wait_frame(page, "manual-steps-import", 1)
        if not cur:
            continue
        for lab in ("Import Steps", "Import", "Finish", "Confirm", "Next", "Validate"):
            try:
                b = cur.get_by_role("button", name=lab)
                if b.count() and b.first.is_enabled():
                    b.first.click(timeout=800)
                    log(f"click {lab}")
            except Exception:
                pass
    return {"ok": False, "body": body}


def main() -> int:
    with sync_playwright() as p:
        b = p.chromium.connect_over_cdp(CDP)
        page = b.contexts[0].pages[0]
        # If validation dialog already open, Back then remap; else full open
        imp = wait_frame(page, "manual-steps-import", 2)
        aio = wait_frame(page, "all-in-one", 2)
        already = False
        if imp:
            body = imp.locator("body").inner_text(timeout=3000) or ""
            if "Call Test" in body or "Validation" in body:
                try:
                    imp.get_by_role("button", name="Back").first.click(timeout=3000)
                    time.sleep(1.5)
                    imp = wait_frame(page, "manual-steps-import", 10) or imp
                    log("backed to map")
                except Exception:
                    pass
            if "Map Fields" not in (imp.locator("body").inner_text(timeout=3000) or ""):
                aio, imp, already = open_to_map(page, "PF-59478", CSV)
        else:
            aio, imp, already = open_to_map(page, "PF-59478", CSV)
        if already:
            log("already done")
            return 0
        mapped = map_react_select(imp, page)
        log("mapped=" + ",".join(mapped))
        result = validate_and_import(imp, page, aio)
        page.screenshot(
            path=str(OUT / ("PF-59478-ok.png" if result.get("ok") else "PF-59478-valfail.png")),
            full_page=True,
        )
        log("ok=" + str(result.get("ok")))
        return 0 if result.get("ok") else 1


if __name__ == "__main__":
    raise SystemExit(main())

