#!/usr/bin/env python3
"""Map Xray CSV fields via react-select inputs, then Validate + Import Steps."""
from __future__ import annotations

import json
import time
from pathlib import Path

from playwright.sync_api import sync_playwright

CDP = "http://127.0.0.1:9333"
OUT = Path(r"E:\LIQA\workspace\default-run\reports\xray-ui-import")
OUT.mkdir(parents=True, exist_ok=True)
ROOT = Path(r"E:\LIQA\workspace\default-run\NewTestCases\PF-58380\sigiri-manual")

CLICK_FROM_CSV = """() => {
  for (const el of document.querySelectorAll('*')) {
    const own = Array.from(el.childNodes)
      .filter(n => n.nodeType === 3)
      .map(n => (n.textContent || '').trim())
      .filter(Boolean)
      .join(' ');
    if (/^From csv/i.test(own)) {
      (el.closest('[role=menuitem]') || el).click();
      return true;
    }
  }
  return false;
}"""


def wait_frame(page, needle: str, timeout_s: float = 50):
    end = time.time() + timeout_s
    while time.time() < end:
        for f in page.frames:
            if needle in (f.url or ""):
                return f
        time.sleep(0.3)
    return None


def log(msg: str) -> None:
    print(msg.encode("ascii", "replace").decode("ascii"), flush=True)


def dismiss(page) -> None:
    for _ in range(3):
        try:
            page.keyboard.press("Escape")
        except Exception:
            pass
        time.sleep(0.15)


def open_map(page, issue: str, csv_path: Path):
    dismiss(page)
    page.goto(
        f"https://lolcgroupdev.atlassian.net/browse/{issue}",
        wait_until="domcontentloaded",
        timeout=120000,
    )
    time.sleep(8)
    for _ in range(20):
        page.mouse.wheel(0, 1100)
        time.sleep(0.1)
    try:
        page.get_by_text("Test details", exact=False).first.click(timeout=5000)
    except Exception:
        pass
    aio = wait_frame(page, "all-in-one", 50)
    if not aio:
        raise RuntimeError("no aio")
    time.sleep(1.5)
    try:
        aio.get_by_text("Dismiss", exact=True).first.click(timeout=800)
    except Exception:
        pass
    body = aio.locator("body").inner_text(timeout=5000) or ""
    if "Expected Result" in body and "There are no steps defined" not in body:
        return aio, None, True

    aio.get_by_role("button", name="Import").first.click(timeout=8000)
    time.sleep(0.9)
    assert aio.evaluate(CLICK_FROM_CSV)
    page.wait_for_selector("iframe[src*='manual-steps-import']", timeout=30000)
    time.sleep(2)
    imp = wait_frame(page, "manual-steps-import", 30)
    assert imp
    end = time.time() + 25
    while time.time() < end:
        try:
            if imp.locator("#xray-csv-file").count():
                break
        except Exception:
            imp = wait_frame(page, "manual-steps-import", 5) or imp
        time.sleep(0.3)

    imp.locator("#xray-csv-file").first.set_input_files(str(csv_path))
    time.sleep(1.2)
    imp.get_by_role("button", name="Next").first.click(timeout=8000)
    time.sleep(2.5)
    return aio, wait_frame(page, "manual-steps-import", 20) or imp, False


def select_step_field(imp, page, input_id: str, value: str) -> bool:
    """Drive react-select by focusing its input, typing, choosing option."""
    inp = imp.locator(f"#{input_id}")
    if inp.count() == 0:
        log(f"missing {input_id}")
        return False
    # click dropdown indicator in same control
    try:
        control = inp.locator("xpath=ancestor::div[contains(@class,'control')][1]")
        ind = control.locator("[class*=indicatorContainer]").last
        ind.click(timeout=2000)
    except Exception:
        inp.click(timeout=2000)
    time.sleep(0.35)
    inp.fill("")
    inp.type(value, delay=50)
    time.sleep(0.5)

    # Prefer menu option inside iframe
    picked = False
    for root in (imp, page):
        try:
            # react-select option id pattern react-select-N-option-M
            opts = root.locator("[id*='-option-']")
            n = opts.count()
            for j in range(n):
                t = (opts.nth(j).inner_text(timeout=500) or "").strip()
                if t == value:
                    opts.nth(j).click(timeout=1500)
                    picked = True
                    break
            if picked:
                break
        except Exception:
            pass
        try:
            root.locator(f"div[class*='option']").filter(has_text=value).first.click(timeout=1500)
            picked = True
            break
        except Exception:
            pass

    if not picked:
        # keyboard confirm first filtered option
        try:
            page.keyboard.press("Enter")
            picked = True
            log(f"Enter for {value}")
        except Exception:
            pass

    time.sleep(0.4)
    # verify singleValue text near this input
    try:
        shown = inp.evaluate(
            """e => {
              const control = e.closest('[class*=control]') || e.parentElement;
              const root = control && control.parentElement;
              const v = root && root.querySelector('[class*=singleValue]');
              return v ? v.textContent.trim() : '';
            }"""
        )
    except Exception:
        shown = ""
    ok = shown == value
    log(f"{input_id} -> want={value} shown={shown!r} ok={ok} picked={picked}")
    return ok


def map_fields(imp, page) -> bool:
    # Discover react-select input ids in order of rows
    ids = imp.evaluate(
        """() => Array.from(document.querySelectorAll('input[id^=react-select-][id$=-input]'))
          .map(e => e.id)"""
    )
    log(f"react-select inputs: {ids}")
    targets = ["Action", "Data", "Expected Result"]
    if len(ids) < 3:
        # fallback known ids from HTML snip
        ids = ["react-select-2-input", "react-select-3-input", "react-select-4-input"]
    ok_all = True
    for i, target in enumerate(targets):
        ok = select_step_field(imp, page, ids[i], target)
        ok_all = ok_all and ok
        # if failed, try ArrowDown navigation
        if not ok:
            try:
                inp = imp.locator(f"#{ids[i]}")
                inp.click()
                time.sleep(0.2)
                # open menu
                page.keyboard.press("Alt+ArrowDown")
                time.sleep(0.3)
                # dump options
                opts = imp.evaluate(
                    """() => Array.from(document.querySelectorAll('[id*=-option-]'))
                      .map(e => ({id:e.id, t:(e.textContent||'').trim()}))"""
                )
                (OUT / f"opts-{i}.json").write_text(json.dumps(opts, indent=2), encoding="utf-8")
                log(f"opts dump {opts}")
                # click matching
                for o in opts or []:
                    if o.get("t") == target:
                        imp.locator(f"#{o['id']}").click(timeout=1500)
                        ok_all = True
                        log(f"clicked {o['id']}")
                        break
            except Exception as e:
                log(f"fallback fail {e}")
    after = imp.locator("body").inner_text(timeout=4000) or ""
    (OUT / "map-verified.txt").write_text(after, encoding="utf-8")
    # success if Don't map count dropped
    dont = after.count("Don't map this field")
    log(f"Dont map remaining={dont}")
    return dont == 0


def validate_import(imp, page, aio) -> bool:
    imp.locator("#validate").click(timeout=4000)
    log("Validate clicked")
    time.sleep(2.5)
    imp = wait_frame(page, "manual-steps-import", 15) or imp
    body = imp.locator("body").inner_text(timeout=4000) or ""
    (OUT / "validate-result.txt").write_text(body, encoding="utf-8")
    log("validate: " + body[:180].replace("\n", " | "))

    if "error" in body.lower() and "Call Test" in body:
        # mapping still wrong
        return False

    # Click Import Steps when enabled
    for _ in range(40):
        time.sleep(0.45)
        aio2 = wait_frame(page, "all-in-one", 2) or aio
        try:
            ab = aio2.locator("body").inner_text(timeout=2000) or ""
        except Exception:
            ab = ""
        if "Expected Result" in ab and "There are no steps defined" not in ab:
            return True
        cur = wait_frame(page, "manual-steps-import", 1)
        if not cur:
            continue
        try:
            btn = cur.locator("#import, button:has-text('Import Steps')")
            # try both
            for sel in ("#import", "button:has-text('Import Steps')"):
                try:
                    b = cur.locator(sel).first
                    if b.count() and b.is_enabled():
                        b.click(timeout=1000)
                        log(f"clicked {sel}")
                except Exception:
                    pass
            try:
                b = cur.get_by_role("button", name="Import Steps")
                if b.count() and b.first.is_enabled():
                    b.first.click(timeout=1000)
                    log("clicked Import Steps")
            except Exception:
                pass
        except Exception:
            pass
    return False


def upload_one(page, issue: str, csv_path: Path) -> dict:
    aio, imp, already = open_map(page, issue, csv_path)
    if already:
        return {"ok": True, "issue": issue, "skipped": True}
    if not map_fields(imp, page):
        page.screenshot(path=str(OUT / f"{issue}-mapfail.png"), full_page=True)
        return {"ok": False, "issue": issue, "error": "mapping incomplete"}
    ok = validate_import(imp, page, aio)
    page.screenshot(
        path=str(OUT / (f"{issue}-ok.png" if ok else f"{issue}-valfail.png")),
        full_page=True,
    )
    return {"ok": ok, "issue": issue, "method": "react-select-map"}


def main() -> int:
    mapping = [
        ("PF-59476", ROOT / "P00" / "P00-owner-exact-120.csv"),
        ("PF-59478", ROOT / "P02" / "P02-steps.csv"),
        ("PF-59479", ROOT / "P03" / "P03-steps.csv"),
        ("PF-59481", ROOT / "P04" / "P04-steps.csv"),
        ("PF-59480", ROOT / "P05" / "P05-steps.csv"),
    ]
    if not mapping[0][1].exists():
        mapping[0] = ("PF-59476", ROOT / "P00" / "P00-steps.csv")

    results = []
    with sync_playwright() as p:
        b = p.chromium.connect_over_cdp(CDP)
        page = b.contexts[0].pages[0]
        # first prove on PF-59478 only if --all not set; here do all
        for issue, csv_path in mapping:
            log(f"=== {issue} ===")
            try:
                r = upload_one(page, issue, csv_path)
            except Exception as e:
                r = {"ok": False, "issue": issue, "error": str(e)}
            results.append(r)
            log(json.dumps({k: r.get(k) for k in ("ok", "issue", "error", "skipped")}))
            dismiss(page)
            time.sleep(1)

    (OUT / "batch-react-select.json").write_text(
        json.dumps({"all_ok": all(r.get("ok") for r in results), "results": results}, indent=2),
        encoding="utf-8",
    )
    log("all_ok=" + str(all(r.get("ok") for r in results)))
    return 0 if all(r.get("ok") for r in results) else 1


if __name__ == "__main__":
    raise SystemExit(main())

