          .map(e => ({id: e.id, t: (e.textContent || '').trim()}))
          .filter(o => o.t)"""
    )


def shown_value(imp, input_id: str) -> str:
    try:
        return imp.locator(f"#{input_id}").evaluate(
            """e => {
              const control = e.closest('[class*=control]');
              const root = control && control.parentElement;
              const v = root && root.querySelector('[class*=singleValue]');
              return v ? v.textContent.trim() : '';
            }"""
        )
    except Exception:
        return ""


def pick_option(imp, page, input_id: str, wanted: str) -> bool:
    """Open react-select for input_id and choose best matching option."""
    dismiss(page)  # close any open menu
    time.sleep(0.2)
    inp = imp.locator(f"#{input_id}")
    # click indicator
    try:
        inp.locator("xpath=ancestor::div[contains(@class,'control')][1]") \
            .locator("[class*=indicatorContainer]").last.click(timeout=2500)
    except Exception:
        inp.click(force=True, timeout=2500)
    time.sleep(0.45)
    opts = list_options(imp)
    log(f"{input_id} options={[o['t'] for o in opts]}")

    # match preference: exact, startswith wanted, wanted without star, contains
    candidates = [
        wanted,
        wanted + "*",
        wanted.rstrip("*"),
        "Action*" if wanted.lower().startswith("action") else wanted,
    ]
    chosen = None
    for cand in candidates:
        for o in opts:
            if o["t"] == cand:
                chosen = o
                break
        if chosen:
            break
    if not chosen:
        for o in opts:
            if wanted.lower() in o["t"].lower() and "call test" not in o["t"].lower() and "don't map" not in o["t"].lower():
                chosen = o
                break
    if not chosen:
        log(f"no option for {wanted}")
        dismiss(page)
        return False

    imp.locator(f"#{chosen['id']}").click(timeout=3000)
    time.sleep(0.35)
    dismiss(page)
    time.sleep(0.2)
    shown = shown_value(imp, input_id)
    ok = shown.lower().startswith(wanted.lower().rstrip("*")) or shown == chosen["t"]
    log(f"{input_id} chose={chosen['t']!r} shown={shown!r} ok={ok}")
    return ok


def map_fields(imp, page) -> bool:
    ids = imp.evaluate(
        """() => Array.from(document.querySelectorAll('input[id^=react-select-][id$=-input]'))
          .map(e => e.id)"""
    )
