    try:
        body = imp.locator("body").inner_text(timeout=3000) or ""
    except Exception:
        pass
    if "Don't map this field" in body:
        return {"ok": False, "error": "mapping incomplete", "mapped": mapped}
    return {"ok": True, "mapped": mapped}


