#!/usr/bin/env python3
"""Verify Manual steps on every registry Test; re-import any empty via proven wizard."""
from __future__ import annotations

import json
import time
from pathlib import Path

from playwright.sync_api import sync_playwright

# reuse proven uploader
import importlib.util

spec = importlib.util.spec_from_file_location(
    "xmap", r"E:\LIQA\scripts\xray_react_select_map.py"
)
xmap = importlib.util.module_from_spec(spec)
spec.loader.exec_module(xmap)

CDP = "http://127.0.0.1:9333"
OUT = Path(r"E:\LIQA\workspace\default-run\reports\xray-ui-import")
OUT.mkdir(parents=True, exist_ok=True)
REG = Path(
    r"E:\LIQA\workspace\default-run\NewTestCases\PF-58380\sigiri-manual\jira-created.json"
)
ROOT = Path(r"E:\LIQA\workspace\default-run\NewTestCases\PF-58380\sigiri-manual")

PACK_CSV = {
    "P00": ROOT / "P00" / "P00-owner-exact-120.csv",
    "P01": ROOT / "P01" / "P01-steps.csv",
    "P02": ROOT / "P02" / "P02-steps.csv",
    "P03": ROOT / "P03" / "P03-steps.csv",
    "P04": ROOT / "P04" / "P04-steps.csv",
    "P05": ROOT / "P05" / "P05-steps.csv",
}
if not PACK_CSV["P00"].exists():
    PACK_CSV["P00"] = ROOT / "P00" / "P00-steps.csv"


def wait_frame(page, needle: str, timeout_s: float = 50):
    end = time.time() + timeout_s
    while time.time() < end:
        for f in page.frames:
            if needle in (f.url or ""):
                return f
        time.sleep(0.3)
    return None


def ensure_logged_in(page) -> dict:
    """Use secrets/jira-ui-login.json if login wall appears."""
    url = (page.url or "").lower()
    body = ""
    try:
        body = page.locator("body").inner_text(timeout=4000) or ""
    except Exception:
        pass
    wall = (
        "id.atlassian.com" in url
        or "auth.atlassian.com" in url
        or "Log in" in body[:500]
        or page.locator("input[type=password]").count() > 0
        and "/browse/" not in url
    )
    if not wall and "browse" in url and len(body) > 80:
        return {"ok": True, "already": True}

    # load secrets
    sec = Path(r"E:\LIQA\workspace\default-run\secrets\jira-ui-login.json")
    if not sec.exists():
        return {"ok": False, "error": "no secrets file"}
    data = json.loads(sec.read_text(encoding="utf-8"))
    email = data.get("email") or ""
    password = data.get("password") or ""
    if not email or not password:
        return {"ok": False, "error": "empty creds"}

    # email step
    try:
        if page.locator("input[type=email], input#username").count():
            page.locator("input[type=email], input#username").first.fill(email)
            page.get_by_role("button", name="Continue").first.click(timeout=5000)
            time.sleep(2)
    except Exception:
        pass
    try:
        if page.locator("input[type=password]").count():
            page.locator("input[type=password]").first.fill(password)
            for lab in ("Log in", "Continue", "Sign in"):
                try:
                    page.get_by_role("button", name=lab).first.click(timeout=3000)
                    break
                except Exception:
                    continue
            time.sleep(5)
    except Exception as e:
        return {"ok": False, "error": f"login fill: {e}"}

    # MFA/OTP — cannot invent; report if still blocked
    url2 = (page.url or "").lower()
    if "id.atlassian.com" in url2 or "auth.atlassian.com" in url2:
        return {"ok": False, "error": "login wall remains (possible MFA)", "needs_human": True}
    return {"ok": True, "logged_in": True}


def inspect_issue(page, issue: str) -> dict:
    page.goto(
        f"https://lolcgroupdev.atlassian.net/browse/{issue}",
        wait_until="domcontentloaded",
        timeout=120000,
    )
    time.sleep(6)
    login = ensure_logged_in(page)
    if not login.get("ok") and login.get("needs_human"):
        return {"issue": issue, "ok": False, **login}
    if "browse" not in (page.url or ""):
        page.goto(
            f"https://lolcgroupdev.atlassian.net/browse/{issue}",
            wait_until="domcontentloaded",
            timeout=120000,
        )
        time.sleep(6)

    for _ in range(18):
        page.mouse.wheel(0, 1100)
        time.sleep(0.1)
