#!/usr/bin/env python3
"""Count Manual steps on each registry Test (scroll table / read aio text)."""
from __future__ import annotations

import json
import re
import time
from pathlib import Path

from playwright.sync_api import sync_playwright

CDP = "http://127.0.0.1:9333"
OUT = Path(r"E:\LIQA\workspace\default-run\reports\xray-ui-import")
REG = Path(
    r"E:\LIQA\workspace\default-run\NewTestCases\PF-58380\sigiri-manual\jira-created.json"
)
ROOT = Path(r"E:\LIQA\workspace\default-run\NewTestCases\PF-58380\sigiri-manual")


def wait_frame(page, needle, timeout_s=50):
    end = time.time() + timeout_s
    while time.time() < end:
        for f in page.frames:
            if needle in (f.url or ""):
                return f
        time.sleep(0.3)
    return None


def count_steps(page, issue: str) -> dict:
    page.goto(
        f"https://lolcgroupdev.atlassian.net/browse/{issue}",
        wait_until="domcontentloaded",
        timeout=120000,
    )
    time.sleep(7)
    for _ in range(20):
        page.mouse.wheel(0, 1100)
        time.sleep(0.1)
    try:
        page.get_by_text("Test details", exact=False).first.click(timeout=5000)
    except Exception:
        pass
    aio = wait_frame(page, "all-in-one", 50)
    if not aio:
        return {"issue": issue, "ok": False, "error": "no aio"}
    time.sleep(2)
    try:
        aio.get_by_text("Dismiss", exact=True).first.click(timeout=800)
    except Exception:
        pass

    # scroll inside aio to load virtualized rows
    for _ in range(30):
        try:
            aio.evaluate("() => { const el = document.scrollingElement || document.body; el.scrollBy(0, 800); }")
        except Exception:
            pass
        time.sleep(0.15)

    body = aio.locator("body").inner_text(timeout=8000) or ""
    empty = "There are no steps defined" in body
    # Count numbered step markers like "\n1\nAction" or rows
    nums = set()
    for m in re.finditer(r"(?m)^(\d+)\s*$", body):
        n = int(m.group(1))
        if 1 <= n <= 500:
            nums.add(n)
    # also try DOM step rows
    dom_count = aio.evaluate(
        """() => {
          const rows = document.querySelectorAll('[data-testid*=step], tr[id], [class*=step-row], [class*=StepRow]');
          // Xray often uses numbered cells
          const nums = new Set();
          document.querySelectorAll('*').forEach(el => {
            const t = (el.childNodes && el.childNodes.length===1 && el.childNodes[0].nodeType===3)
              ? (el.textContent||'').trim() : '';
            if (/^\\d+$/.test(t)) {
              const n = parseInt(t,10);
              if (n>=1 && n<=500) nums.add(n);
            }
          });
          return {rowGuess: rows.length, maxNum: nums.size ? Math.max(...nums) : 0, numCount: nums.size};
        }"""
    )
    page.screenshot(path=str(OUT / f"count-{issue}.png"), full_page=True)
    max_num = max(nums) if nums else dom_count.get("maxNum") or 0
    return {
        "issue": issue,
        "ok": (not empty) and max_num >= 1,
        "empty": empty,
        "max_step_num": max_num,
        "text_nums": len(nums),
        "dom": dom_count,
        "has_expected": "Expected Result" in body,
        "snip": body[:200].replace("\n", " | "),
    }


def main() -> int:
    reg = json.loads(REG.read_text(encoding="utf-8-sig"))
    expected = {t["key"]: t.get("steps") for t in reg["tests"]}
    results = []
    with sync_playwright() as p:
        b = p.chromium.connect_over_cdp(CDP)
        page = b.contexts[0].pages[0]
        for t in reg["tests"]:
            issue = t["key"]
            print(f"=== count {issue} expect~{t.get('steps')} ===", flush=True)
            info = count_steps(page, issue)
            info["expected_steps"] = t.get("steps")
            info["coverage_ok"] = (
                info.get("max_step_num", 0) >= max(1, int(t.get("steps") or 1) - 2)
            )
            results.append(info)
            print(
                json.dumps(
                    {
                        k: info.get(k)
                        for k in (
                            "issue",
                            "ok",
                            "max_step_num",
                            "expected_steps",
                            "coverage_ok",
                            "empty",
                        )
                    }
                ),
                flush=True,
            )
    summary = {
        "all_present": all(r.get("ok") for r in results),
        "all_full": all(r.get("coverage_ok") for r in results),
        "results": results,
    }
    (OUT / "count-all-manual-steps.json").write_text(
        json.dumps(summary, indent=2), encoding="utf-8"
    )
    print(json.dumps({k: summary[k] for k in ("all_present", "all_full")}, indent=2))
    return 0 if summary["all_present"] and summary["all_full"] else 1


if __name__ == "__main__":
    raise SystemExit(main())

#!/usr/bin/env python3
"""Precise step count: Action cells in Xray aio steps table only."""
from __future__ import annotations

import json
import time
from pathlib import Path

from playwright.sync_api import sync_playwright

CDP = "http://127.0.0.1:9333"
OUT = Path(r"E:\LIQA\workspace\default-run\reports\xray-ui-import")
REG = Path(
    r"E:\LIQA\workspace\default-run\NewTestCases\PF-58380\sigiri-manual\jira-created.json"
)
ROOT = Path(r"E:\LIQA\workspace\default-run\NewTestCases\PF-58380\sigiri-manual")


def wait_frame(page, needle, timeout_s=50):
    end = time.time() + timeout_s
    while time.time() < end:
        for f in page.frames:
            if needle in (f.url or ""):
                return f
        time.sleep(0.3)
    return None


def precise_count(page, issue: str) -> dict:
    page.goto(
        f"https://lolcgroupdev.atlassian.net/browse/{issue}",
        wait_until="domcontentloaded",
        timeout=120000,
    )
    time.sleep(7)
    for _ in range(18):
        page.mouse.wheel(0, 1100)
        time.sleep(0.1)
    try:
        page.get_by_text("Test details", exact=False).first.click(timeout=5000)
    except Exception:
        pass
    aio = wait_frame(page, "all-in-one", 50)
    if not aio:
        return {"issue": issue, "ok": False, "error": "no aio"}
    time.sleep(2)
    try:
        aio.get_by_text("Dismiss", exact=True).first.click(timeout=800)
    except Exception:
        pass

    # scroll steps area
    for _ in range(40):
        try:
            aio.mouse.wheel(0, 1200)
        except Exception:
            try:
                aio.evaluate("() => window.scrollBy(0, 900)")
            except Exception:
                pass
        time.sleep(0.12)

    info = aio.evaluate(
        """() => {
          const body = document.body.innerText || '';
          const empty = body.includes('There are no steps defined');
          // Prefer explicit step index cells next to Action labels
          const actions = [];
          const walk = document.createTreeWalker(document.body, NodeFilter.SHOW_ELEMENT);
          let node;
          while ((node = walk.nextNode())) {
            const own = Array.from(node.childNodes)
              .filter(n => n.nodeType === 3)
              .map(n => (n.textContent || '').trim())
              .filter(Boolean)
              .join(' ');
            if (own === 'Action') {
              // find nearby action text in parent row
              const row = node.closest('tr, [class*=Row], [class*=row], div');
              const txt = (row && row.innerText || '').split('\\n').map(s => s.trim()).filter(Boolean);
              actions.push(txt.slice(0, 8));
            }
          }
          // Count unique step headers pattern: number then Action
          let stepHeaders = 0;
          const lines = body.split('\\n').map(s => s.trim());
          for (let i = 0; i < lines.length - 1; i++) {
            if (/^\\d+$/.test(lines[i]) && lines[i+1] === 'Action') stepHeaders++;
          }
          // first action sample
          let firstAction = '';
          for (let i = 0; i < lines.length - 2; i++) {
            if (lines[i] === 'Action') {
              // next non-empty that isn't Data/Expected
              for (let j = i+1; j < Math.min(i+6, lines.length); j++) {
                if (!['Data','Expected Result','None',''].includes(lines[j]) && !/^\\d+$/.test(lines[j])) {
                  firstAction = lines[j];
                  break;
                }
              }
              break;
            }
          }
          return {
            empty,
            actionLabelCount: actions.length,
            stepHeaders,
            firstAction: firstAction.slice(0, 120),
            hasExpected: body.includes('Expected Result'),
          };
        }"""
    )
    return {"issue": issue, "ok": (not info.get("empty")) and info.get("hasExpected"), **info}


def main() -> int:
    reg = json.loads(REG.read_text(encoding="utf-8-sig"))
    # csv expected rows
    pack_rows = {}
    for t in reg["tests"]:
        pack = t["pack"]
        for cand in (
            ROOT / pack / f"{pack}-owner-exact-120.csv",
            ROOT / pack / f"{pack}-steps.csv",
        ):
            if cand.exists():
                rows = sum(1 for _ in cand.open(encoding="utf-8-sig")) - 1
                pack_rows[t["key"]] = {"pack": pack, "csv_rows": rows, "csv": str(cand)}
                break

    results = []
    with sync_playwright() as p:
        b = p.chromium.connect_over_cdp(CDP)
        page = b.contexts[0].pages[0]
        for t in reg["tests"]:
            issue = t["key"]
            print(f"=== {issue} ===", flush=True)
            info = precise_count(page, issue)
            meta = pack_rows.get(issue) or {}
            info.update(meta)
            # allow +/-2 for header/off-by-one
            csv_rows = int(meta.get("csv_rows") or t.get("steps") or 0)
            counted = max(int(info.get("stepHeaders") or 0), int(info.get("actionLabelCount") or 0))
            info["counted"] = counted
            info["match"] = abs(counted - csv_rows) <= 2 if csv_rows else counted >= 1
            results.append(info)
            print(
                json.dumps(
                    {
                        k: info.get(k)
                        for k in (
                            "issue",
                            "ok",
                            "counted",
                            "csv_rows",
                            "match",
                            "firstAction",
                            "empty",
                        )
                    }
                ),
                flush=True,
            )

    summary = {
        "all_ok": all(r.get("ok") and r.get("match") for r in results),
        "results": results,
    }
    (OUT / "precise-count.json").write_text(json.dumps(summary, indent=2), encoding="utf-8")
    print(json.dumps({"all_ok": summary["all_ok"]}, indent=2))
    return 0 if summary["all_ok"] else 1


if __name__ == "__main__":
    raise SystemExit(main())

