def collect(page, issue: str) -> dict:
    page.goto(
        f"https://lolcgroupdev.atlassian.net/browse/{issue}",
        wait_until="domcontentloaded",
        timeout=120000,
    )
    time.sleep(7)
    for _ in range(18):
