    time.sleep(2)
    try:
        aio.get_by_text("Dismiss", exact=True).first.click(timeout=800)
    except Exception:
        pass

    found = set()
    first_actions = []
    for _ in range(60):
        data = aio.evaluate(
            """() => {
              const lines = (document.body.innerText || '').split('\\n').map(s => s.trim());
              const nums = [];
              const actions = [];
              for (let i = 0; i < lines.length - 1; i++) {
                if (/^\\d+$/.test(lines[i]) && lines[i+1] === 'Action') {
                  const n = parseInt(lines[i], 10);
                  nums.push(n);
                  // action text
                  for (let j = i+2; j < Math.min(i+7, lines.length); j++) {
                    if (!['Data','Expected Result','None',''].includes(lines[j]) && !/^\\d+$/.test(lines[j]) && lines[j] !== 'Action') {
                      actions.push({n, a: lines[j].slice(0,100)});
                      break;
                    }
                  }
                }
              }
              return {nums, actions};
            }"""
        )
