import time
from pathlib import Path

from playwright.sync_api import sync_playwright

spec = importlib.util.spec_from_file_location(
    "xmap", r"E:\LIQA\scripts\xray_react_select_map.py"
)
xmap = importlib.util.module_from_spec(spec)
spec.loader.exec_module(xmap)

CDP = "http://127.0.0.1:9333"
CSV = Path(r"E:\LIQA\workspace\default-run\NewTestCases\PF-58380\sigiri-manual\P01\P01-steps.csv")
OUT = Path(r"E:\LIQA\workspace\default-run\reports\xray-ui-import")
CLICK_FROM_CSV = xmap.CLICK_FROM_CSV


def force_reset_upload(page, issue: str, csv_path: Path) -> dict:
    xmap.dismiss(page)
    page.goto(
        f"https://lolcgroupdev.atlassian.net/browse/{issue}",
        wait_until="domcontentloaded",
        timeout=120000,
    )
    time.sleep(8)
    for _ in range(20):
        page.mouse.wheel(0, 1100)
        time.sleep(0.1)
    try:
        page.get_by_text("Test details", exact=False).first.click(timeout=5000)
    except Exception:
        pass
    aio = xmap.wait_frame(page, "all-in-one", 50)
    if not aio:
        return {"ok": False, "error": "no aio"}
    time.sleep(1.5)
    try:
        aio.get_by_text("Dismiss", exact=True).first.click(timeout=800)
    except Exception:
        pass

    # Always open import even if steps exist
    # Prefer icon menu when filled
    body = aio.locator("body").inner_text(timeout=5000) or ""
    if "There are no steps defined" in body:
        aio.get_by_role("button", name="Import").first.click(timeout=8000)
    else:
        opened = False
        try:
            add = aio.get_by_role("button", name="Add Step")
            box = add.bounding_box()
            for i in range(aio.locator("button").count()):
                bb = aio.locator("button").nth(i).bounding_box()
                if (
                    bb
                    and box
                    and abs(bb["y"] - box["y"]) < 12
                    and bb["x"] > box["x"] + 8
                    and bb["width"] <= 55
                ):
                    aio.locator("button").nth(i).click()
                    opened = True
                    break
        except Exception:
            pass
        if not opened:
            try:
                aio.get_by_text("Import", exact=True).first.click(timeout=4000)
            except Exception:
                aio.get_by_role("button", name="Import").first.click(timeout=8000)
    time.sleep(0.9)
    assert aio.evaluate(CLICK_FROM_CSV)
    page.wait_for_selector("iframe[src*='manual-steps-import']", timeout=30000)
    time.sleep(2)
    imp = xmap.wait_frame(page, "manual-steps-import", 30)
    assert imp
    end = time.time() + 25
    while time.time() < end:
        try:
            if imp.locator("#xray-csv-file").count():
                break
        except Exception:
            imp = xmap.wait_frame(page, "manual-steps-import", 5) or imp
        time.sleep(0.3)

    # Check Reset Current Test Steps (name=Clear Steps)
    try:
        cb = imp.locator("input[type=checkbox][name='Clear Steps']")
        if cb.count():
            if not cb.first.is_checked():
                cb.first.check()
                xmap.log("checked Clear Steps / Reset")
        else:
            for i in range(imp.locator("input[type=checkbox]").count()):
                el = imp.locator("input[type=checkbox]").nth(i)
                lab = el.evaluate(
                    "e => ((e.parentElement&&e.parentElement.innerText)||e.name||'')"
                )
                if "reset" in (lab or "").lower() or "clear" in (lab or "").lower():
                    if not el.is_checked():
                        el.check()
                        xmap.log(f"checked {lab!r}")
    except Exception as e:
        xmap.log(f"reset cb err {e}")

    imp.locator("#xray-csv-file").first.set_input_files(str(csv_path))
    time.sleep(1.2)
    imp.get_by_role("button", name="Next").first.click(timeout=8000)
    time.sleep(2.5)
    imp = xmap.wait_frame(page, "manual-steps-import", 20) or imp
    if not xmap.map_fields(imp, page):
        page.screenshot(path=str(OUT / f"{issue}-reset-mapfail.png"), full_page=True)
        return {"ok": False, "issue": issue, "error": "mapping incomplete"}
    ok = xmap.validate_import(imp, page, aio)
    page.screenshot(
        path=str(OUT / (f"{issue}-reset-ok.png" if ok else f"{issue}-reset-fail.png")),
        full_page=True,
    )
    return {"ok": ok, "issue": issue, "method": "force-reset-import"}


def main() -> int:
    with sync_playwright() as p:
        b = p.chromium.connect_over_cdp(CDP)
        page = b.contexts[0].pages[0]
        r = force_reset_upload(page, "PF-59477", CSV)
        print(json.dumps(r, indent=2))
        # verify max step after
        time.sleep(2)
        page.goto(
            "https://lolcgroupdev.atlassian.net/browse/PF-59477",
            wait_until="domcontentloaded",
            timeout=120000,
        )
        time.sleep(7)
        for _ in range(15):
            page.mouse.wheel(0, 1100)
            time.sleep(0.1)
        try:
            page.get_by_text("Test details", exact=False).first.click(timeout=4000)
        except Exception:
            pass
        aio = xmap.wait_frame(page, "all-in-one", 40)
        time.sleep(2)
        found = set()
        for _ in range(40):
            data = aio.evaluate(
                """() => {
                  const lines = (document.body.innerText||'').split('\\n').map(s=>s.trim());
                  const nums=[];
                  for (let i=0;i<lines.length-1;i++){
                    if (/^\\d+$/.test(lines[i]) && lines[i+1]==='Action') nums.push(parseInt(lines[i],10));
                  }
                  return nums;
                }"""
            )
            found.update(data or [])
            try:
                aio.evaluate("() => window.scrollBy(0,1000)")
            except Exception:
                pass
            time.sleep(0.12)
        print(json.dumps({"verify_max": max(found) if found else 0, "unique": len(found)}))
        return 0 if r.get("ok") else 1


if __name__ == "__main__":
    raise SystemExit(main())

#!/usr/bin/env python3
"""Force Clear Steps via JS, then import P01 CSV into PF-59477."""
from __future__ import annotations

import importlib.util
import json
import time
from pathlib import Path

from playwright.sync_api import sync_playwright

spec = importlib.util.spec_from_file_location(
    "xmap", r"E:\LIQA\scripts\xray_react_select_map.py"
)
xmap = importlib.util.module_from_spec(spec)
spec.loader.exec_module(xmap)

CDP = "http://127.0.0.1:9333"
CSV = Path(r"E:\LIQA\workspace\default-run\NewTestCases\PF-58380\sigiri-manual\P01\P01-steps.csv")
OUT = Path(r"E:\LIQA\workspace\default-run\reports\xray-ui-import")


def main() -> int:
    with sync_playwright() as p:
        b = p.chromium.connect_over_cdp(CDP)
        page = b.contexts[0].pages[0]
        xmap.dismiss(page)
        page.goto(
            "https://lolcgroupdev.atlassian.net/browse/PF-59477",
            wait_until="domcontentloaded",
            timeout=120000,
        )
        time.sleep(8)
        for _ in range(18):
            page.mouse.wheel(0, 1100)
            time.sleep(0.1)
        try:
            page.get_by_text("Test details", exact=False).first.click(timeout=5000)
        except Exception:
            pass
        aio = xmap.wait_frame(page, "all-in-one", 50)
        assert aio
        time.sleep(1.5)
        # open import menu (filled state)
        opened = False
        try:
            add = aio.get_by_role("button", name="Add Step")
            box = add.bounding_box()
            for i in range(aio.locator("button").count()):
                bb = aio.locator("button").nth(i).bounding_box()
                if bb and box and abs(bb["y"] - box["y"]) < 12 and bb["x"] > box["x"] + 8 and bb["width"] <= 55:
                    aio.locator("button").nth(i).click()
                    opened = True
                    break
        except Exception:
            pass
        if not opened:
            aio.get_by_text("Import", exact=True).first.click(timeout=5000)
        time.sleep(0.8)
        assert aio.evaluate(xmap.CLICK_FROM_CSV)
        page.wait_for_selector("iframe[src*='manual-steps-import']", timeout=30000)
        time.sleep(2)
        imp = xmap.wait_frame(page, "manual-steps-import", 30)
        assert imp
        end = time.time() + 20
        while time.time() < end:
            if imp.locator("#xray-csv-file").count():
                break
            time.sleep(0.3)

        cleared = imp.evaluate(
            """() => {
              const boxes = Array.from(document.querySelectorAll('input[type=checkbox]'));
              let hit = null;
              for (const b of boxes) {
                const lab = ((b.parentElement && b.parentElement.innerText) || b.name || '').toLowerCase();
                if (b.name === 'Clear Steps' || lab.includes('reset') || lab.includes('clear')) {
                  b.checked = true;
                  b.dispatchEvent(new Event('input', {bubbles:true}));
                  b.dispatchEvent(new Event('change', {bubbles:true}));
                  b.click();
                  hit = {name: b.name, checked: b.checked, lab: lab.slice(0,80)};
                  break;
                }
              }
              // also click visible label text
              for (const el of document.querySelectorAll('*')) {
                const own = Array.from(el.childNodes).filter(n=>n.nodeType===3).map(n=>(n.textContent||'').trim()).join(' ');
                if (/Reset Current Test Steps/i.test(own)) { el.click(); }
              }
              const b2 = document.querySelector('input[name="Clear Steps"]');
              return {hit, checked: b2 ? b2.checked : null};
            }"""
        )
        print("clear", json.dumps(cleared))
        # if still false, set via label click with force through evaluate only
        if not cleared.get("checked"):
            imp.evaluate(
                """() => {
                  const b = document.querySelector('input[name="Clear Steps"]');
                  if (!b) return;
                  const setter = Object.getOwnPropertyDescriptor(HTMLInputElement.prototype, 'checked').set;
                  setter.call(b, true);
                  b.dispatchEvent(new Event('click', {bubbles:true}));
                  b.dispatchEvent(new Event('change', {bubbles:true}));
                }"""
            )
            print("forced checked", imp.evaluate("() => document.querySelector('input[name=\"Clear Steps\"]').checked"))

        imp.locator("#xray-csv-file").first.set_input_files(str(CSV))
        time.sleep(1)
        imp.get_by_role("button", name="Next").first.click(timeout=8000)
        time.sleep(2.5)
        imp = xmap.wait_frame(page, "manual-steps-import", 20) or imp
        assert xmap.map_fields(imp, page)
        ok = xmap.validate_import(imp, page, aio)
        page.screenshot(path=str(OUT / "PF-59477-clear-ok.png"), full_page=True)
        print(json.dumps({"ok": ok}))

        # verify
        time.sleep(2)
        page.goto(
            "https://lolcgroupdev.atlassian.net/browse/PF-59477",
            wait_until="domcontentloaded",
            timeout=120000,
        )
        time.sleep(7)
        for _ in range(15):
            page.mouse.wheel(0, 1100)
            time.sleep(0.1)
        try:
            page.get_by_text("Test details", exact=False).first.click(timeout=4000)
        except Exception:
            pass
        aio = xmap.wait_frame(page, "all-in-one", 40)
        time.sleep(2)
        found = set()
        last_actions = []
        for _ in range(50):
            data = aio.evaluate(
                """() => {
                  const lines=(document.body.innerText||'').split('\\n').map(s=>s.trim());
                  const out=[];
                  for (let i=0;i<lines.length-1;i++){
                    if (/^\\d+$/.test(lines[i]) && lines[i+1]==='Action'){
                      let a='';
                      for (let j=i+2;j<Math.min(i+7,lines.length);j++){
                        if (!['Data','Expected Result','None',''].includes(lines[j]) && !/^\\d+$/.test(lines[j]) && lines[j]!=='Action'){ a=lines[j]; break; }
                      }
                      out.push({n:parseInt(lines[i],10), a:a.slice(0,80)});
                    }
                  }
                  return out;
                }"""
            )
            for row in data or []:
                found.add(row["n"])
                if row not in last_actions:
                    last_actions.append(row)
            try:
                aio.evaluate("() => window.scrollBy(0,1100)")
            except Exception:
                pass
            time.sleep(0.12)
        print(
            json.dumps(
                {
                    "max": max(found) if found else 0,
                    "unique": len(found),
                    "samples": last_actions[:3],
                    "tail": last_actions[-3:],
                },
                indent=2,
            )
        )
        return 0 if ok and (max(found) if found else 0) <= 20 else 1


if __name__ == "__main__":
    raise SystemExit(main())

#!/usr/bin/env python3
"""Properly toggle Reset Current Test Steps by clicking the visible label, then import P01."""
from __future__ import annotations

import importlib.util
import json
import time
from pathlib import Path

from playwright.sync_api import sync_playwright

spec = importlib.util.spec_from_file_location(
    "xmap", r"E:\LIQA\scripts\xray_react_select_map.py"
)
xmap = importlib.util.module_from_spec(spec)
spec.loader.exec_module(xmap)

CDP = "http://127.0.0.1:9333"
CSV = Path(r"E:\LIQA\workspace\default-run\NewTestCases\PF-58380\sigiri-manual\P01\P01-steps.csv")
OUT = Path(r"E:\LIQA\workspace\default-run\reports\xray-ui-import")


def open_import_dialog(page):
    xmap.dismiss(page)
    page.goto(
        "https://lolcgroupdev.atlassian.net/browse/PF-59477",
        wait_until="domcontentloaded",
        timeout=120000,
    )
    time.sleep(8)
    for _ in range(18):
        page.mouse.wheel(0, 1100)
        time.sleep(0.1)
    try:
        page.get_by_text("Test details", exact=False).first.click(timeout=5000)
    except Exception:
        pass
    aio = xmap.wait_frame(page, "all-in-one", 50)
    assert aio
    time.sleep(1.5)
    # filled-state kebab / import icon
    opened = False
    try:
        add = aio.get_by_role("button", name="Add Step")
        box = add.bounding_box()
        for i in range(aio.locator("button").count()):
            bb = aio.locator("button").nth(i).bounding_box()
            if bb and box and abs(bb["y"] - box["y"]) < 12 and bb["x"] > box["x"] + 8 and bb["width"] <= 55:
                aio.locator("button").nth(i).click()
                opened = True
                break
    except Exception:
        pass
    if not opened:
        aio.get_by_text("Import", exact=True).first.click(timeout=5000)
    time.sleep(0.8)
    assert aio.evaluate(xmap.CLICK_FROM_CSV)
    page.wait_for_selector("iframe[src*='manual-steps-import']", timeout=30000)
    time.sleep(2)
    imp = xmap.wait_frame(page, "manual-steps-import", 30)
    assert imp
    end = time.time() + 20
    while time.time() < end:
        if imp.locator("#xray-csv-file").count():
            break
        time.sleep(0.3)
    return aio, imp


def toggle_reset(imp, page) -> bool:
    # dump checkbox + label HTML
    info = imp.evaluate(
        """() => {
          const b = document.querySelector('input[name="Clear Steps"]');
          if (!b) return {ok:false};
          const label = b.closest('label') || b.parentElement;
          return {
            ok:true,
            checked: b.checked,
            labelText: (label && label.innerText || '').slice(0,120),
            labelTag: label && label.tagName,
            html: (label && label.outerHTML || '').slice(0,500)
          };
        }"""
    )
    (OUT / "reset-checkbox.json").write_text(json.dumps(info, indent=2), encoding="utf-8")
    print("before", info.get("checked"), info.get("labelText"))

    # Click the text "Reset Current Test Steps"
    clicked = False
    try:
        imp.get_by_text("Reset Current Test Steps", exact=False).first.click(timeout=3000)
        clicked = True
    except Exception as e:
        print("text click fail", e)

    if not clicked:
        # click sibling span via JS with mouse events on label
        imp.evaluate(
            """() => {
              const b = document.querySelector('input[name="Clear Steps"]');
              const label = b.closest('label') || b.parentElement;
              if (label) {
                label.dispatchEvent(new MouseEvent('click', {bubbles:true, cancelable:true}));
              }
              // styled switch: click next element
              const sw = b.nextElementSibling || (label && label.querySelector('span'));
              if (sw) sw.dispatchEvent(new MouseEvent('click', {bubbles:true}));
            }"""
        )

    time.sleep(0.5)
    after = imp.evaluate("() => document.querySelector('input[name=\"Clear Steps\"]').checked")
    print("after", after)

    # If still false, try Playwright force on the input
    if not after:
        try:
            imp.locator("input[name='Clear Steps']").first.click(force=True, timeout=3000)
        except Exception as e:
            print("force click", e)
        time.sleep(0.3)
        after = imp.evaluate("() => document.querySelector('input[name=\"Clear Steps\"]').checked")
        print("after force", after)

    # Last resort: React fiber-ish by focusing and space
    if not after:
        try:
            loc = imp.locator("input[name='Clear Steps']")
            loc.focus()
            page.keyboard.press("Space")
            time.sleep(0.3)
        except Exception as e:
            print("space", e)
        after = imp.evaluate("() => document.querySelector('input[name=\"Clear Steps\"]').checked")
        print("after space", after)

    page.screenshot(path=str(OUT / "reset-toggle.png"), full_page=True)
    return bool(after)


def verify_max(page) -> dict:
    page.goto(
        "https://lolcgroupdev.atlassian.net/browse/PF-59477",
        wait_until="domcontentloaded",
        timeout=120000,
    )
    time.sleep(7)
    for _ in range(15):
        page.mouse.wheel(0, 1100)
        time.sleep(0.1)
    try:
        page.get_by_text("Test details", exact=False).first.click(timeout=4000)
    except Exception:
        pass
    aio = xmap.wait_frame(page, "all-in-one", 40)
    time.sleep(2)
    found = set()
    samples = []
    for _ in range(55):
        data = aio.evaluate(
            """() => {
              const lines=(document.body.innerText||'').split('\\n').map(s=>s.trim());
              const out=[];
              for (let i=0;i<lines.length-1;i++){
                if (/^\\d+$/.test(lines[i]) && lines[i+1]==='Action'){
                  let a='';
                  for (let j=i+2;j<Math.min(i+7,lines.length);j++){
                    if (!['Data','Expected Result','None',''].includes(lines[j]) && !/^\\d+$/.test(lines[j]) && lines[j]!=='Action'){ a=lines[j]; break; }
                  }
                  out.push({n:parseInt(lines[i],10), a:a.slice(0,90)});
                }
              }
              return out;
            }"""
        )
        for row in data or []:
            found.add(row["n"])
            if len(samples) < 8:
                samples.append(row)
        try:
            aio.evaluate("() => window.scrollBy(0,1200)")
        except Exception:
            pass
        time.sleep(0.1)
    return {"max": max(found) if found else 0, "unique": len(found), "samples": samples}


def main() -> int:
    with sync_playwright() as p:
        b = p.chromium.connect_over_cdp(CDP)
        page = b.contexts[0].pages[0]
        aio, imp = open_import_dialog(page)
        ok_toggle = toggle_reset(imp, page)
        if not ok_toggle:
            print("FAILED to toggle reset — abort import to avoid append")
            return 2

        imp.locator("#xray-csv-file").first.set_input_files(str(CSV))
        time.sleep(1)
        imp.get_by_role("button", name="Next").first.click(timeout=8000)
        time.sleep(2.5)
        imp = xmap.wait_frame(page, "manual-steps-import", 20) or imp
        assert xmap.map_fields(imp, page)
        ok = xmap.validate_import(imp, page, aio)
        print(json.dumps({"import_ok": ok, "reset_toggled": ok_toggle}))
        v = verify_max(page)
        print(json.dumps(v, indent=2))
        (OUT / "p01-reset-verify.json").write_text(
            json.dumps({"import_ok": ok, "verify": v}, indent=2), encoding="utf-8"
        )
        return 0 if ok and v.get("max", 999) <= 12 else 1


if __name__ == "__main__":
    raise SystemExit(main())

